window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0009", [{"word":"comprehensive","ipa_uk":"/ˌkɒmprɪˈhensɪv/","ipa_us":"/ˌkɑːmprɪˈhensɪv/","definition_zh":"全面的；综合的；包罗广泛的；全额包含的","definition_en":"covering all or nearly all aspects of something, or including everything that is needed","core_image":"一张把所有分支都收进同一个圆里的网","scene":"The committee ordered a comprehensive review of the city's flood defences, from the riverbanks to the drainage tunnels.","sceneCN":"这里 comprehensive 是「全面的、覆盖所有方面的」（第 1 个义项：范围上覆盖全部或几乎全部）；句意：委员会下令对城市防洪体系做一次全面审查，从河岸一直查到排水隧道。场景要点：一张同时列出河岸、堤坝和排水隧道的清单，所有地点被圈进同一个范围。","pos":[{"tag":"adj.","zh":"全面的；综合的；包罗广泛的"},{"tag":"adj.","zh":"（英）（学校）综合制的；全额包含的"}],"collocations":[{"phrase":"a comprehensive review","zh":"全面审查"},{"phrase":"comprehensive insurance","zh":"综合保险；全险"},{"phrase":"comprehensive coverage","zh":"全面覆盖；综合保障范围"},{"phrase":"a comprehensive school","zh":"（英国）综合中学"},{"phrase":"comprehensive reform","zh":"全面改革"},{"phrase":"a comprehensive understanding","zh":"全面的理解"}],"forms":[{"label":"比较级（多音节形容词用 more 构成）","form":"more comprehensive"}],"derivatives":[{"word":"comprehensively","pos":"adv.","zh":"全面地；彻底地"},{"word":"comprehensiveness","pos":"n.","zh":"全面性；包罗万象"},{"word":"comprehension","pos":"n.","zh":"理解；理解力；包含"},{"word":"comprehend","pos":"v.","zh":"理解；领会；包含"},{"word":"comprehensible","pos":"adj.","zh":"可理解的；易懂的"},{"word":"incomprehensible","pos":"adj.","zh":"无法理解的；难以懂的"}],"senses":[{"no":"01","title":"Covering all aspects: wide in scope","titleCN":"覆盖各个方面：范围全面","definition":"including or dealing with all or nearly all aspects of a subject or situation","definitionCN":"包括或处理某一主题、某一情况的全部或几乎全部方面","example":"The report gives a comprehensive picture of the region's economy.","exampleCN":"这份报告全面呈现了该地区的经济状况。","why":"Com- means 'together' and prehendere means 'to seize'. A comprehensive account seizes every part and holds all of them together in one grasp, so nothing important is left outside.","whyCN":"com- 是“一起”，prehendere 是“抓住”。comprehensive 的叙述把所有部分都抓住并握在同一只手里，因此没有重要内容被落在外面。"},{"no":"02","title":"Thorough in depth: detailed and complete","titleCN":"深入彻底：详尽完整","definition":"complete and careful in the way details are treated, not merely wide in range","definitionCN":"在细节处理上完整而仔细，不只是范围宽","example":"She wrote a comprehensive guide to the museum's collection.","exampleCN":"她为博物馆的藏品写了一本详尽完整的指南。","why":"The same grip is applied downward into detail: a comprehensive guide does not just list the rooms, it also holds the dates, materials and history of each object.","whyCN":"同一只“抓握”的手又向细节深处延伸：comprehensive 的指南不只是列出展厅，还把每件器物的年代、材质与来历一并握住。"},{"no":"03","title":"All-inclusive in price or content","titleCN":"费用或内容全额包含","definition":"including everything in one price or package, with no major item left to be paid separately","definitionCN":"把全部项目都包含在一个价格或套餐里，没有大项需要另外付费","example":"The tour price is comprehensive: flights, hotels and meals are all included.","exampleCN":"这个团费是全包的：机票、酒店和餐食都包含在内。","why":"If every part is held inside the package, the buyer does not meet a missing piece at the counter. The word therefore labels a price or package with no gaps.","whyCN":"如果每个部分都被握进套餐之内，买家就不会在付款时突然遇到缺失的一项。因此这个词用来标记没有缺口的报价或套餐。"},{"no":"04","title":"Insurance: covering a wide range of risks","titleCN":"保险：保障范围广","definition":"used of insurance that protects against many kinds of loss rather than only one named risk","definitionCN":"用于保险，指防范多种损失，而不只是某一种指定风险","example":"Comprehensive insurance covered the damage to the parked car.","exampleCN":"综合保险赔付了那辆停放车辆所受的损坏。","why":"An insurer's 'coverage' is literally what its policy holds inside its boundary. A comprehensive policy draws its boundary wide enough to include collision, theft and fire together.","whyCN":"保险的 coverage 字面上就是保单边界内“握住”的内容。comprehensive 保单把边界画得足够宽，把碰撞、盗抢和火灾一并包含进来。"},{"no":"05","title":"British school: all abilities in one school","titleCN":"英国教育：综合制学校","definition":"in Britain, a secondary school that admits pupils of all abilities instead of selecting by exam","definitionCN":"在英国，指招收各种能力水平学生、不按考试选拔的中学","example":"Both of her children attend the local comprehensive.","exampleCN":"她的两个孩子都在当地的综合中学就读。","why":"The school's intake is comprehensive in the original sense: children of every level are gathered into one institution rather than separated into selective schools.","whyCN":"这类学校招收的学生正是原义上的 comprehensive：各种水平的孩子被收进同一所学校，而不是按能力分流到选拔性学校。"},{"no":"06","title":"Wide-ranging action: search, reform, survey","titleCN":"大规模行动：搜查、改革、调查","definition":"used of an action that reaches across a whole field rather than a small corner of it","definitionCN":"用于形容某项行动横跨整个领域，而不是只触及一小块角落","example":"The government promised a comprehensive reform of the tax system.","exampleCN":"政府承诺对税制进行全面改革。","why":"A reform that is comprehensive sweeps the whole field into its net; partial reform touches one part and leaves the rest untouched.","whyCN":"全面的改革把整个领域都扫进网里；局部改革只碰到一部分，其余部分仍原封不动。"},{"no":"07","title":"Total in degree: a comprehensive victory","titleCN":"程度上的彻底：全面胜利","definition":"complete and overwhelming in degree, so that no part of the result is left in doubt","definitionCN":"在程度上彻底而压倒性，使结果没有任何部分存疑","example":"The final score was a comprehensive victory for the home team.","exampleCN":"终场比分是主队的一场全面胜利。","why":"Here completeness moves from range to degree: every part of the contest was held by one side, so nothing remained outside its control.","whyCN":"这里“完整”从范围转向程度：比赛的每一部分都被一方握在手里，没有任何部分留在其控制之外。"},{"no":"08","title":"Archaic: able to grasp mentally","titleCN":"古旧义：有理解力的","definition":"in older usage, having the power to understand or grasp many things; now rare","definitionCN":"在较早的用法中，指有能力理解、领会许多事物；现已罕见","example":"The old essay praises the comprehensive mind of the true scholar.","exampleCN":"那篇旧文章称赞真正学者那种能容纳万有的理解力。","why":"This is the mental version of the same Latin verb: a comprehensive mind can prehendere, 'seize', many ideas and hold them together. Modern English usually keeps the word for scope, not for the mind that grasps it.","whyCN":"这是同一个拉丁动词的“心智版”：comprehensive 的头脑能把许多观念抓住并握在一起。现代英语通常只用它表示范围，而不用来形容具备这种理解力的头脑。"}],"etymology":{"intro":{"en":"Comprehensive is a Latin-derived adjective whose parts still speak: com- 'together' plus prehendere 'to seize'. Dates are approximate.","cn":"comprehensive 是一个拉丁来源的形容词，构词成分至今仍能读懂：com-“一起”加 prehendere“抓住”。年代为大致估计。"},"items":[{"era":"1610s","en":"First recorded in English meaning 'containing much in comparatively small limits', borrowed through French comprehénsif.","cn":"英语中最早记录于 17 世纪 10 年代，意为“在相对小的范围内包含很多内容”，经由法语 comprehénsif 借入。"},{"era":"LATE LATIN","en":"Late Latin comprehensivus was formed on the stem comprehens-, from the past participle of comprehendere 'to take together, unite; include; grasp with the mind'.","cn":"晚期拉丁语 comprehensivus 由词干 comprehens- 构成，来自 comprehendere 的过去分词，意为“一起拿住、联合；包含；用头脑理解”。"},{"era":"LATIN","en":"Comprehendere joins com- 'together' (here probably intensive, 'completely') and prehendere 'to catch hold of, seize', itself from prae- 'before' plus -hendere, from PIE *ghend- 'to seize, take'.","cn":"comprehendere 由 com-“一起”（这里很可能是加强义“完全”）和 prehendere“抓住、握取”组成，后者又来自 prae-“在前”加 -hendere，可追溯到原始印欧语 *ghend-“抓住、拿取”。"},{"era":"PROTO-INDO-EUROPEAN","en":"The reconstructed root *ghend- 'to seize' also underlies get, guess, prison, prize and prehensile. Reconstructed roots are not directly attested.","cn":"重构词根 *ghend-“抓住”也是 get、guess、prison、prize、prehensile 的来源。这类词根没有直接文献记录。"},{"era":"MODERN ENGLISH","en":"The modern sense widened from 'holding much in little space' to 'covering all aspects'. Comprehension and comprehensible took the mental branch of the same verb, while comprise is a French-shaped cousin of the same Latin root.","cn":"现代词义从“在小空间里容纳很多”扩展到“覆盖所有方面”。comprehension 与 comprehensible 走的是同一动词的“心智”分支，而 comprise 是同一拉丁词根经法语塑形的表亲。"}]},"similar":{"note":{"en":"The first group separates the adjectives and nouns built on the same Latin verb; the second group collects words that also mean 'covering a lot'.","cn":"第一组区分由同一个拉丁动词构成的形容词与名词；第二组收集同样表示“覆盖很多”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"comprehensible","ipa":"/ˌkɒmprɪˈhensəbl/","tag":"different suffix","definition":"able to be understood. The suffix -ible marks possibility, while -ive in comprehensive marks a quality of covering; a comprehensible text need not be comprehensive.","definitionCN":"可理解的。后缀 -ible 表示“能够被”，而 comprehensive 的 -ive 表示“具有覆盖的性质”；一篇可理解的文章不一定全面。"},{"word":"comprehension","ipa":"/ˌkɒmprɪˈhenʃn/","tag":"same verb, noun","definition":"the act or power of understanding, or the act of including. It is the noun of the mental branch, not a synonym of comprehensive.","definitionCN":"理解的行为或能力，也可指包含。它是同一动词“心智”分支的名词，并不是 comprehensive 的同义词。"},{"word":"comprise","ipa":"/kəmˈpraɪz/","tag":"same root, different verb","definition":"to consist of or to make up a whole. It comes from the same comprehendere, but it names the relation between parts and whole, not a wide scope.","definitionCN":"由……组成，或构成整体。它来自同一个 comprehendere，但表示部分与整体的关系，不表示范围的宽广。"}]},{"heading":"NEAR MEANING","entries":[{"word":"exhaustive","ipa":"/ɪɡˈzɔːstɪv/","tag":"complete to the last item","definition":"covering every possible detail so that nothing is left out. It is stronger and more technical than comprehensive, and often suggests a list that has been used up.","definitionCN":"详尽无遗，覆盖每一个可能的细节。它比 comprehensive 更强、更技术化，常暗示清单已被穷尽。"},{"word":"thorough","ipa":"/ˈθʌrə/","tag":"careful depth","definition":"done with great care and attention to detail. Thorough stresses the quality of the work; comprehensive stresses the size of the field.","definitionCN":"做事仔细、注重细节。thorough 强调工作的细致程度，comprehensive 强调所覆盖领域的广度。"},{"word":"all-inclusive","ipa":"/ˌɔːl ɪnˈkluːsɪv/","tag":"price or package","definition":"including everything in one price. It is mainly commercial and applies to travel, resorts and packages, not to studies or reforms.","definitionCN":"一个价格包含全部项目。它主要用于商业语境，形容旅行、度假村和套餐，不用于研究或改革。"},{"word":"broad","ipa":"/brɔːd/","tag":"wide but not deep","definition":"covering a large area or range, but not necessarily in detail. Broad can be wide and shallow; comprehensive implies both width and completeness.","definitionCN":"覆盖广大区域或范围，但不一定深入。broad 可以宽而浅；comprehensive 则同时含有广度与完整度。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: com- 'together', prehendere 'seize', and the everyday pair comprehension / comprehensible.","cn":"只用真实的构词成分与真实同族词：com-“一起”、prehendere“抓住”，以及日常成对的 comprehension／comprehensible。"},"normal":[{"en":"com- means 'together' and prehendere means 'seize'. Comprehensive means every part has been seized into one hand.","cn":"com- 表示“一起”，prehendere 表示“抓住”。comprehensive 就是每个部分都被抓进同一只手里。"},{"en":"The -ive ending makes an adjective of quality, as in creative and decisive; comprehensive describes something that has the quality of covering.","cn":"-ive 构成性质形容词，如 creative、decisive；comprehensive 描述事物具有“覆盖”的性质。"},{"en":"Comprehension is the noun for understanding; comprehensible means able to be understood. Both keep the mental branch of the same verb.","cn":"comprehension 是表示“理解”的名词；comprehensible 意为“可理解的”。两者都保留了同一动词的“心智”分支。"},{"en":"A comprehensive school is not a school about comprehension: it is a school that gathers all ability levels into one place.","cn":"comprehensive school 不是“理解学校”：它是把所有能力水平的学生收进同一所学校的综合中学。"},{"en":"Comprehensive insurance is a real fixed term: it covers many risks, not just one named risk.","cn":"comprehensive insurance 是固定说法：它覆盖多种风险，而不只是某一项指定风险。"}],"abstract":[{"en":"Picture a net thrown over a whole map: rivers, roads and tunnels all sit inside the same circle. Comprehensive is that circle closing.","cn":"想象把一张网罩在整幅地图上：河流、道路、隧道都落在同一个圆圈里。comprehensive 就是这张网收拢的瞬间。"},{"en":"The same circle can tighten into depth instead of width: a comprehensive guide holds the dates and materials of each object, not only the list of rooms.","cn":"同一个圆圈也可以不收宽而收深：comprehensive 的指南握有每件器物的年代与材质，而不只是展厅清单。"},{"en":"When the circle closes on a contest or a price, completeness becomes totality: every part is inside, so nothing can be paid or lost outside it.","cn":"当这个圆圈收紧到一场比赛或一个价格上，完整就变成“全部”：每个部分都在圈内，圈外没有可再付费或可再失去的东西。"}]},"examples":[{"en":"The city needs a comprehensive plan that links transport, housing and waste treatment.","cn":"这座城市需要一份把交通、住房和垃圾处理联系起来的全面规划。"},{"en":"Her comprehensive notes saved the group during the final review.","cn":"她详尽完整的笔记在期末复习时救了整个小组。"},{"en":"The policy is comprehensive in name but leaves dental care to be paid separately.","cn":"这份保险名义上是全险，却把牙科护理留作另外付费。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“扛普瑞，很细翻”——扛着普瑞的全部资料，很细地翻一遍，一页不漏 → comprehensive 全面的、包罗广泛的","word":"comprehensive"},"root":"源自拉丁语 comprehendere“一起抓住”，由 com-“一起”+ prehendere“抓住”构成，核心是“把所有部分攥在同一只手里”。","sensesIntro":{"en":"Eight senses of comprehensive, all built on one gesture: a hand closes around every part and holds them together, whether the parts are topics, details, costs, risks or points in a contest.","cn":"comprehensive 的八个义项都建立在同一个动作上：一只手把所有部分收拢并握在一起——不论这些部分是主题、细节、费用、风险，还是一场较量中的得分。"},"semanticMap":{"core":{"en":"CORE IMAGE: one hand closes around every part and holds them together.","cn":"核心意象：一只手把所有部分收拢，握在一起。"},"chain":["HOLD TOGETHER","SEIZE EVERY PART","WIDE SCOPE","FULL COVERAGE","ALL-INCLUSIVE","TOTAL OR EXHAUSTIVE"],"branches":[{"senses":"S1 · S6","en":"SCOPE: a review or reform that reaches across a whole field holds every corner of it.","cn":"范围：横跨整个领域的审查或改革，把该领域的每个角落都握进来。"},{"senses":"S2","en":"DEPTH: the grip tightens downward into details, so the account is complete as well as wide.","cn":"深度：抓握向下收紧到细节，因此叙述既宽又完整。"},{"senses":"S3 · S4","en":"COVERAGE: a price, package or policy has no gap because every item or risk lies inside its boundary.","cn":"覆盖：价格、套餐或保单没有缺口，因为每个项目或风险都落在边界之内。"},{"senses":"S5","en":"INSTITUTION: a school gathers all ability levels into one place, the social version of the same circle.","cn":"机构：学校把各种能力水平收进同一处，是同一个圆圈的社会版本。"},{"senses":"S7 · S8","en":"TOTALITY AND MIND: in a contest the circle covers every point; in older use the mind itself can grasp many ideas at once.","cn":"全部与心智：在比赛中圆圈覆盖每一分；在较早用法里，头脑本身也能一次握住许多观念。"}]},"affixes":{"intro":{"en":"Comprehensive is built from Latin pieces that are still transparent: com- 'together' and prehendere 'to seize', with the adjective suffix -ive. English then adds ordinary suffixes and a negative prefix.","cn":"comprehensive 由仍然透明的拉丁成分构成：com-“一起”、prehendere“抓住”，再加形容词后缀 -ive。英语随后又加普通后缀和否定前缀。"},"latinIntro":{"en":"The Latin family is built on comprehendere 'to seize together': comprehensio 'a grasping', comprehensivus 'grasping', and the verb itself. The same root gives comprise through French, and prehensile directly from prehendere.","cn":"这一拉丁词族建立在 comprehendere“一起抓住”上：comprehensio“抓握”、comprehensivus“能抓握的”，以及动词本身。同一词根经法语给出 comprise，并由 prehendere 直接给出 prehensile。"},"items":[{"word":"comprehensively","structure":"comprehensive + -ly (adverb)","meaning":"in a way that covers all or nearly all aspects","meaningCN":"全面地；彻底地（-ly 构成副词）","example":"The safety rules were comprehensively rewritten after the accident.","exampleCN":"事故之后，安全规则被全面改写。"},{"word":"comprehensiveness","structure":"comprehensive + -ness (quality noun)","meaning":"the quality of covering everything needed","meaningCN":"全面性；完整性（-ness 构成性质名词）","example":"Reviewers praised the comprehensiveness of the survey.","exampleCN":"评审者称赞这份调查的全面性。"},{"word":"comprehension","structure":"comprehend + -ion (action or result noun)","meaning":"the act or power of understanding; also inclusion","meaningCN":"理解；理解力；也指包含（-ion 构成行为或结果名词）","example":"The passage is beyond the comprehension of most beginners.","exampleCN":"这段文字超出大多数初学者的理解范围。"},{"word":"comprehend","structure":"com- (together) + prehendere (seize)","meaning":"to grasp mentally; to include","meaningCN":"理解；领会；包含（com- 一起 + prehendere 抓住）","example":"Few readers can comprehend the scale of the change.","exampleCN":"很少有读者能理解这场变化的规模。"},{"word":"comprehensible","structure":"comprehens- + -ible (able to be)","meaning":"able to be understood","meaningCN":"可理解的；易懂的（-ible 表示“能够被”）","example":"The manual is written in comprehensible language.","exampleCN":"这本手册用易懂的语言写成。"},{"word":"incomprehensible","structure":"in- (not) + comprehensible","meaning":"impossible to understand","meaningCN":"无法理解的（in- 表示否定）","example":"His explanation was almost incomprehensible to the class.","exampleCN":"他的解释对全班来说几乎无法理解。"},{"word":"comprise","structure":"com- (together) + French prendre (to take), from Latin prehendere","meaning":"to consist of; to make up","meaningCN":"由……组成；构成（同一拉丁词根经法语进入英语）","example":"The course comprises six modules and a final project.","exampleCN":"这门课由六个模块和一个结项作业组成。"},{"word":"prehensile","structure":"prehens- + -ile (able to)","meaning":"able to grasp or hold, as a monkey's tail","meaningCN":"能抓握的（-ile 表示能力）；如猴子的尾巴","example":"The animal uses its prehensile tail to hang from branches.","exampleCN":"这种动物用能抓握的尾巴挂在树枝上。"},{"word":"apprehend","structure":"ad- (to) + prehendere (seize)","meaning":"to seize or arrest; to understand","meaningCN":"逮捕；抓住；理解（ad- 向 + prehendere 抓住）","example":"The police apprehended the suspect at the border.","exampleCN":"警方在边境逮捕了嫌疑人。"}],"latinEntries":[{"word":"comprehendere","structure":"com- (together) + prehendere (seize)","meaning":"to take together, unite, include; to grasp with the mind","meaningCN":"一起拿住；联合；包含；用头脑理解"},{"word":"comprehensivus","structure":"comprehens- + -ivus (adjective)","meaning":"having the power of grasping or including","meaningCN":"有抓握力或包含力的"},{"word":"comprehensio","structure":"comprehendere + -io (action noun)","meaning":"a grasping together; inclusion; understanding","meaningCN":"一起抓握；包含；理解"},{"word":"prehendere","structure":"prae- (before) + -hendere (seize)","meaning":"to catch hold of, seize","meaningCN":"抓住；握取"}]}},{"word":"comprise","ipa_uk":"/kəmˈpraɪz/","ipa_us":"/kəmˈpraɪz/","definition_zh":"包括；由……组成；构成（整体由部分构成）","definition_en":"to consist of particular parts, or to constitute and make up a whole","core_image":"一只箱子把六个模块收进同一条边界里","scene":"The training programme comprises six modules, each ending with a practical assessment.","sceneCN":"这里 comprise 是「由……组成、包括」（第 1 个义项：整体由若干部分构成）；句意：这个培训项目由六个模块组成，每个模块都以一次实操考核收尾。场景要点：一个整体（培训项目）、六个部分（模块）、整体把部分收进自己的边界。","pos":[{"tag":"v.","zh":"包括；由……组成"},{"tag":"v.","zh":"构成；组成（部分构成整体）"}],"collocations":[{"phrase":"be comprised of","zh":"由……组成（被动说法，传统用法对此有争议）"},{"phrase":"comprise the majority of","zh":"占……的大多数"},{"phrase":"comprise several parts","zh":"由若干部分组成"},{"phrase":"broadly comprise","zh":"大体包括；大致由……构成"},{"phrase":"comprise about half of","zh":"约占……的一半"},{"phrase":"a team comprising experts from","zh":"由来自……的专家组成的团队"}],"forms":[{"label":"第三人称单数","form":"comprises"},{"label":"过去式","form":"comprised"},{"label":"过去分词","form":"comprised"},{"label":"现在分词","form":"comprising"}],"derivatives":[{"word":"comprisal","pos":"n.","zh":"包含；构成（罕用）"},{"word":"comprisable","pos":"adj.","zh":"可被包含的（罕用）"},{"word":"comprehend","pos":"v.","zh":"理解；包含（同源词，非 comprise 派生）"},{"word":"comprehension","pos":"n.","zh":"理解；理解力；包含（同源词）"},{"word":"comprehensive","pos":"adj.","zh":"全面的；综合的（同源词，勿与 comprise 混用）"}],"senses":[{"no":"01","title":"The whole holds its parts","titleCN":"整体收拢部分：由……组成","definition":"to consist of particular parts, with the whole as the subject and the parts inside it","definitionCN":"由若干特定部分组成；主语是整体，部分位于整体之内","example":"The course comprises six modules and a final project.","exampleCN":"这门课由六个模块和一个结项作业组成。","why":"French compris, the past participle of comprendre, meant 'included'. English kept that picture: the parts have already been taken inside the whole, so the whole is the natural subject.","whyCN":"法语 compris 是 comprendre 的过去分词，意为“被包含的”。英语保留了这个画面：部分已经被收进整体里，所以整体自然成为主语。"},{"no":"02","title":"The parts build the whole","titleCN":"部分构成整体：占……比例","definition":"to constitute or make up a whole, used when the subject is the parts rather than the container","definitionCN":"构成或组成一个整体；此时主语是部分，而不是容器","example":"Women comprise about half of the workforce in this sector.","exampleCN":"在这一行业，女性约占劳动力的一半。","why":"The 1794 sense looked at the same box from inside: instead of asking what the whole contains, it asks what the parts add up to. The parts now take the subject position.","whyCN":"1794 年出现的义项是从箱子内部看同一件事：不问整体装了什么，而问部分加起来成了什么。此时部分占据了主语位置。"},{"no":"03","title":"Be comprised of: the passive frame","titleCN":"被动框架：be comprised of","definition":"in the passive, to be made up of particular parts","definitionCN":"用于被动语态，表示由若干部分构成","example":"The committee is comprised of twelve members, four of them independent.","exampleCN":"该委员会由十二名成员组成，其中四名是独立成员。","why":"The passive turns the whole into the receiver: the whole 'is included' out of its parts. Traditional handbooks call this disputed and prefer 'comprises' or 'is composed of', though the passive is common in modern writing.","whyCN":"被动语态把整体变成接受者：整体“由部分被构成”。传统用法手册认为这种说法有争议，更倾向用 comprises 或 is composed of，但它在现代写作中很常见。"},{"no":"04","title":"A collection and what it holds","titleCN":"藏品与内容：包括这些项目","definition":"to include particular items as the contents of a collection, archive, or set","definitionCN":"指某一收藏、档案或集合的内容包括某些项目","example":"The archive comprises letters, diaries and about two thousand photographs.","exampleCN":"该档案馆藏有书信、日记以及约两千张照片。","why":"Here the box is a collection and the parts are its contents. Nothing is built or measured; the whole simply holds what is listed inside its boundary.","whyCN":"这里的箱子是一个收藏，部分是它的内容。既不涉及“构成”，也不涉及“度量”，整体只是把列出的东西收在自己的边界里。"},{"no":"05","title":"Scope embraced: covering a range","titleCN":"范围收拢：涵盖整个区域","definition":"to cover or embrace a whole range of people or things within one survey, rule, or view","definitionCN":"在一项调查、规则或视野内覆盖或囊括整个人群或全部事物","example":"The survey comprises every household in the district, not just the homeowners.","exampleCN":"这项调查涵盖该区的每一户人家，而不只是有房者。","why":"To 'take together' can be spatial as well as structural: the survey draws a line around all the households and takes them in at once.","whyCN":"“一起拿住”既可以是结构上的，也可以是空间上的：调查在所有住户外面画一条线，把它们一次收进来。"},{"no":"06","title":"Definitional inclusion: what a term covers","titleCN":"定义上的包含：术语涵盖什么","definition":"of a word or rule, to include certain cases within its meaning","definitionCN":"指某个词或规则在其含义中包括某些情形","example":"In this contract, 'employee' comprises part-time and temporary staff as well.","exampleCN":"在这份合同中，employee 一词也包括兼职和临时员工。","why":"A definition is a boundary too. When a term comprises certain cases, those cases are held inside the term's scope, even if they are not physical parts.","whyCN":"定义也是一条边界。当一个术语 comprises 某些情形时，这些情形就被收在术语范围之内，即使它们并不是物理上的组成部分。"},{"no":"07","title":"Taxonomy: a group and its members","titleCN":"分类学：科由属组成","definition":"in biology, of a group such as a family or genus, to contain the taxa ranked below it","definitionCN":"在生物学中，指科、属等分类阶元包含其下各级分类单元","example":"The family comprises twelve genera and more than three hundred species.","exampleCN":"该科由十二个属、三百多个种组成。","why":"Taxonomy is the most literal use of the box: each rank is a container whose contents are the ranks below it, and the list is expected to be complete.","whyCN":"分类学是“箱子”最字面的用法：每一个阶元都是一个容器，里面装的是低一级的阶元，而且这份清单被期待是完整的。"},{"no":"08","title":"Stated extent: what a property consists of","titleCN":"面积与范围：地产包含多少","definition":"of an area or property, to consist of a stated extent or set of resources","definitionCN":"指一片区域或地产由所述面积或资源构成","example":"The estate comprises four hundred hectares of woodland and two lakes.","exampleCN":"这片地产包括四百公顷林地和两个湖泊。","why":"A whole can be measured as well as listed. Here the boundary is drawn on the ground, and comprise reports everything inside that line.","whyCN":"整体除了被列举，也可以被度量。这里边界画在地面上，comprise 报告的就是这条线以内的一切。"}],"etymology":{"intro":{"en":"Comprise entered English through French, shaped by the past participle compris. Its Latin ancestor is the same verb that gives comprehensive, though the two words were given different jobs.","cn":"comprise 经由法语进入英语，词形来自过去分词 compris。它的拉丁语祖先与 comprehensive 同出一个动词，但两个词后来承担了不同的职务。"},"items":[{"era":"EARLY 15C.","en":"First recorded in English with the sense 'to include'. The word arrived through French rather than directly from Latin.","cn":"英语中最早记录于 15 世纪初，意为“包括”。这个词是经法语而来的，而不是直接从拉丁语借入。"},{"era":"OLD FRENCH compris","en":"Old French compris was the past participle of comprendre 'to include, comprise', itself from Latin comprehendere.","cn":"古法语 compris 是 comprendre“包括、由……构成”的过去分词，后者来自拉丁语 comprehendere。"},{"era":"LATIN comprehendere","en":"Comprehendere meant 'to take together, include, seize': com- 'together' plus prehendere 'to catch hold of', which joins prae- 'before' and -hendere, from PIE *ghend- 'to seize'.","cn":"comprehendere 意为“一起拿住、包括、抓住”：com-“一起”加 prehendere“抓住”，后者由 prae-“在前”和 -hendere 组成，可追溯到原始印欧语 *ghend-“抓住”。"},{"era":"PROTO-INDO-EUROPEAN","en":"The reconstructed root *ghend- 'to seize' also lies behind get, guess, prison and prehensile. Such roots are reconstructions, not attested forms.","cn":"重构词根 *ghend-“抓住”也是 get、guess、prison、prehensile 的来源。这类词根是重构形式，并非有直接文献记录的词形。"},{"era":"LATE 15C. · 1794","en":"By the late 15th century comprise meant 'to contain, to have as parts'. In 1794 a further sense appeared: 'to constitute, make up', with the parts as subject.","cn":"到 15 世纪后期，comprise 已表示“包含、以……为组成部分”。1794 年又出现“构成、组成”的义项，此时主语是部分。"},{"era":"MODERN USAGE","en":"The passive 'be comprised of' is widely used but has long been criticized by traditional handbooks, which prefer 'comprises' or 'is composed of'. Note the direction: the whole comprises the parts; the parts compose the whole.","cn":"被动说法 be comprised of 使用广泛，但长期受到传统用法手册批评，它们更倾向 comprises 或 is composed of。注意方向：整体 comprise 部分；部分 compose 整体。"}]},"similar":{"note":{"en":"The first group separates words built on the same Latin verb; the second group compares words that also describe parts and wholes, with attention to which side is the subject.","cn":"第一组区分由同一个拉丁动词构成的词；第二组比较同样描述部分与整体的词，重点看哪一方作主语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"comprehensive","ipa":"/ˌkɒmprɪˈhensɪv/","tag":"same root, different job","definition":"covering all or nearly all aspects of something. It shares the Latin verb comprehendere with comprise but describes wide scope, not the parts that make up a whole.","definitionCN":"覆盖全部或几乎全部方面。它与 comprise 共享拉丁动词 comprehendere，但描述范围宽广，而不是构成整体的各个部分。"},{"word":"comprehension","ipa":"/ˌkɒmprɪˈhenʃn/","tag":"noun of the mental branch","definition":"the act or power of understanding; also the act of including. It is the noun of the 'grasp with the mind' branch, not a synonym of comprise.","definitionCN":"理解的行为或能力；也可指包含。它是“用头脑抓住”这一分支的名词，并不是 comprise 的同义词。"},{"word":"comprised","ipa":"/kəmˈpraɪzd/","tag":"participial form","definition":"the past participle, used in the passive 'be comprised of'. It is a form of the verb, not a separate noun or adjective with its own meaning.","definitionCN":"过去分词，用于被动结构 be comprised of。它只是动词的一种形式，不是另有含义的名词或形容词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"compose","ipa":"/kəmˈpəʊz/","tag":"opposite direction","definition":"of parts, to make up a whole: 'Six modules compose the course'. The direction is the reverse of comprise, whose subject is the whole.","definitionCN":"指部分构成整体：Six modules compose the course。方向与 comprise 相反，comprise 的主语是整体。"},{"word":"consist of","ipa":"/kənˈsɪst əv/","tag":"active only","definition":"to be made up of: 'The course consists of six modules'. It has no passive form, so 'is consisted of' is an error, and it names only the whole-to-parts relation.","definitionCN":"由……组成：The course consists of six modules。它没有被动形式，因此 is consisted of 是错误说法；它只表示整体到部分的关系。"},{"word":"include","ipa":"/ɪnˈkluːd/","tag":"not necessarily all","definition":"to have something as part of a larger group. A whole can include a few items without containing all of them; comprise usually implies the full set.","definitionCN":"把某物作为更大群体的一部分。整体可以只 include 少数几项，而不必包含全部；comprise 通常暗示是完整的一套。"},{"word":"contain","ipa":"/kənˈteɪn/","tag":"container image","definition":"to have something inside a container or boundary. It stresses physical or spatial enclosure more than comprise, which stresses the parts of a structure.","definitionCN":"在容器或边界内装有某物。它比 comprise 更强调物理或空间上的围合，而 comprise 强调结构上的组成部分。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: the French participle compris, the Latin com- 'together' plus prehendere 'seize', and the comprehend family.","cn":"只用真实构词成分与真实同族词：法语分词 compris、拉丁语 com-“一起”加 prehendere“抓住”，以及 comprehend 词族。"},"normal":[{"en":"Compris is the past participle of French comprendre 'to include'. English borrowed the 'included' form, so the parts are pictured as already inside the whole.","cn":"compris 是法语 comprendre“包括”的过去分词。英语借来的是“已被包含”的形式，所以画面上部分已经在整体之内。"},{"en":"com- means 'together' and prehendere means 'seize': the parts are seized together into one boundary.","cn":"com- 是“一起”，prehendere 是“抓住”：各部分被一起抓进同一条边界。"},{"en":"Test the direction before you write: if the subject is the whole, use comprise; if the subject is the parts, use compose or make up.","cn":"下笔前先辨方向：主语是整体，用 comprise；主语是部分，用 compose 或 make up。"},{"en":"Traditional handbooks dislike 'be comprised of' and prefer 'comprises' or 'is composed of'; the passive is nonetheless everywhere in modern writing.","cn":"传统用法手册不喜欢 be comprised of，更倾向 comprises 或 is composed of；但在现代写作中被动说法随处可见。"},{"en":"Comprehension is understanding, comprehensive is covering everything, comprise is containing parts. One Latin verb, three separate jobs.","cn":"comprehension 是理解，comprehensive 是覆盖全部，comprise 是包含各部分。同一个拉丁动词，分化成三项不同的工作。"}],"abstract":[{"en":"Picture a box with six labelled modules inside it. Comprise is the box closing its lid: everything listed is now within one boundary.","cn":"想象一只箱子，里面放着六个贴好标签的模块。comprise 就是箱子合上盖子的动作：列出的东西现在都在同一条边界内。"},{"en":"Stand outside the box and you say the whole comprises the parts; stand inside and you say the parts compose or make up the whole.","cn":"站在箱子外面，你说整体 comprises 部分；站在箱子里面，你说部分 compose 或 make up 整体。"},{"en":"The word is about enclosure, not about size: a committee, a course, an archive and a family are all boxes of different shapes.","cn":"这个词说的是“围合”，不是大小：委员会、课程、档案馆、生物科属，都是形状不同的箱子。"}]},"examples":[{"en":"The panel comprises a chair, two scientists and a lawyer.","cn":"该专家组由一名主席、两名科学家和一名律师组成。"},{"en":"Ten chapters comprise the whole book, and each one can be read on its own.","cn":"整本书由十章构成，每一章都可以单独阅读。"},{"en":"The region is comprised of seven provinces, a phrasing that careful editors still replace with 'comprises seven provinces'.","cn":"该地区由七个省组成；谨慎的编辑仍会把 is comprised of 改成 comprises seven provinces。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“肯姆普莱兹”——肯姆把普莱兹（place）里的六样东西全收进一只箱子，箱子里就包含了它们 → comprise 包括、由……组成","word":"comprise"},"root":"源自拉丁语 comprehendere“一起抓住、包括”，经古法语 compris 进入英语，核心是“整体把部分收进自己的边界”。","sensesIntro":{"en":"Eight senses of comprise, all grown from one image: a whole that holds its parts inside its own boundary — and, seen from the other side, parts that build that whole.","cn":"comprise 的八个义项都从同一个意象长出来：整体把部分收在自己的边界里——换个方向看，就是部分建起了这个整体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a whole closes its boundary around the parts it holds.","cn":"核心意象：整体合上边界，把所装的部分圈在其中。"},"chain":["A WHOLE","PARTS INSIDE","BOUNDARY CLOSES","CONTENTS INCLUDED","SCOPE EMBRACED","PARTS CONSTITUTE THE WHOLE"],"branches":[{"senses":"S1 · S8","en":"STRUCTURE: a course or an estate consists of its modules or hectares, and the whole is the subject.","cn":"结构：课程或地产由其模块或公顷数构成，主语是整体。"},{"senses":"S2 · S3","en":"DIRECTION: the parts can take the subject position and make up the whole, or the passive can present the whole as made up.","cn":"方向：部分可以作主语构成整体，也可以用被动把整体说成由部分构成。"},{"senses":"S4 · S6","en":"INCLUSION: an archive holds its contents, and a definition holds the cases inside its scope.","cn":"包含：档案馆装着自己的藏品，定义把某些情形收在自己的范围里。"},{"senses":"S5","en":"SCOPE: a survey draws a line around every household and takes them all in.","cn":"范围：调查在每一户外面画一条线，把它们全部收进来。"},{"senses":"S7","en":"TAXONOMY: a family is a box whose contents are the genera and species ranked below it.","cn":"分类学：科是一只箱子，里面装的是其下排的属与种。"}]},"affixes":{"intro":{"en":"Comprise is not built from a live English prefix. Its Latin pieces com- 'together' and prehendere 'seize' came to English through French, and English adds only ordinary suffixes such as -ed, -ing and -al.","cn":"comprise 并不是用活的英语前缀造出来的。它的拉丁成分 com-“一起”和 prehendere“抓住”经法语进入英语，英语只再加上 -ed、-ing、-al 这类普通后缀。"},"latinIntro":{"en":"The Latin family is built on comprehendere 'to seize together': comprehensio, comprehensivus, and the verb itself. French shortened the stem to compris-, and English uses both the French-shaped comprise and the Latin-shaped comprehend.","cn":"这一拉丁词族建立在 comprehendere“一起抓住”上：comprehensio、comprehensivus 以及动词本身。法语把词干压缩成 compris-，英语同时使用法语形的 comprise 和拉丁语形的 comprehend。"},"items":[{"word":"comprisal","structure":"comprise + -al (action noun)","meaning":"the act of including or comprising; rare","meaningCN":"包含、构成的行为（-al 构成行为名词；罕用）","example":"The comprisal of all departments in one report took weeks.","exampleCN":"把所有部门都纳入一份报告，花了数周时间。"},{"word":"comprisable","structure":"comprise + -able (able to be)","meaning":"able to be included or comprised; rare","meaningCN":"可被包含的（-able 表示“能够被”；罕用）","example":"Not every item is comprisable under the existing category.","exampleCN":"并非每一项都能归入现有类别。"},{"word":"comprising","structure":"comprise + -ing (present participle or gerund)","meaning":"including; the act of consisting of","meaningCN":"包括；由……组成（现在分词或动名词）","example":"A team comprising five engineers wrote the specification.","exampleCN":"一个由五名工程师组成的团队编写了规范。"},{"word":"comprised","structure":"comprise + -ed (past tense and participle)","meaning":"included, or made up, in the passive frame","meaningCN":"被包含、被构成的（过去式与过去分词）","example":"The old county was comprised of eleven parishes.","exampleCN":"这个旧郡由十一个教区组成。"},{"word":"comprehend","structure":"com- (together) + prehendere (seize)","meaning":"to grasp with the mind; to include","meaningCN":"理解；领会；包含（同一拉丁词根，非直接派生）","example":"Few readers can comprehend the scale of the change.","exampleCN":"很少有读者能理解这场变化的规模。"},{"word":"comprehension","structure":"comprehend + -ion (action or result noun)","meaning":"understanding; inclusion","meaningCN":"理解；理解力；包含","example":"The passage is beyond the comprehension of most beginners.","exampleCN":"这段文字超出大多数初学者的理解范围。"},{"word":"comprehensive","structure":"comprehens- + -ive (adjective of quality)","meaning":"covering all or nearly all aspects","meaningCN":"全面的；综合的（-ive 构成性质形容词）","example":"The report gives a comprehensive picture of the region's economy.","exampleCN":"这份报告全面呈现了该地区的经济状况。"},{"word":"comprehensible","structure":"comprehens- + -ible (able to be)","meaning":"able to be understood","meaningCN":"可理解的；易懂的","example":"The manual is written in comprehensible language.","exampleCN":"这本手册用易懂的语言写成。"},{"word":"prehensile","structure":"prehens- + -ile (able to)","meaning":"able to grasp or hold, as a tail","meaningCN":"能抓握的（-ile 表示能力）","example":"The animal uses its prehensile tail to hang from branches.","exampleCN":"这种动物用能抓握的尾巴挂在树枝上。"},{"word":"apprehend","structure":"ad- (to) + prehendere (seize)","meaning":"to seize or arrest; to understand","meaningCN":"逮捕；抓住；理解（ad- “向”加“抓住”）","example":"The police apprehended the suspect at the border.","exampleCN":"警方在边境逮捕了嫌疑人。"}],"latinEntries":[{"word":"comprehendere","structure":"com- (together) + prehendere (seize)","meaning":"to take together, include; to grasp with the mind","meaningCN":"一起拿住；包括；用头脑理解"},{"word":"prehendere","structure":"prae- (before) + -hendere (seize)","meaning":"to catch hold of, seize","meaningCN":"抓住；握取"},{"word":"comprehensio","structure":"comprehendere + -io (action noun)","meaning":"a grasping together; inclusion; understanding","meaningCN":"一起抓握；包含；理解"}]}},{"word":"concentrate","ipa_uk":"/ˈkɒnsəntreɪt/","ipa_us":"/ˈkɑːnsəntreɪt/","definition_zh":"集中（注意力、努力）；使聚集；浓缩；浓缩物","definition_en":"to bring people, things, or attention together at one point; to make a liquid stronger by removing water; a concentrated substance","core_image":"许多细流同时被吸向同一个中心点","scene":"She switched off the radio and concentrated on the last chapter of her thesis.","sceneCN":"这里 concentrate 是「集中注意力」（第 3 个义项：把心思收拢到一件事上）；句意：她关掉收音机，专心读论文的最后一章。场景要点：一个嘈杂的房间、一个被关掉的干扰源、全部心思收拢到一页纸上。","pos":[{"tag":"v.","zh":"集中（注意力、努力）；使聚集"},{"tag":"n.","zh":"浓缩物；精矿"}],"collocations":[{"phrase":"concentrate on","zh":"专注于；集中精力于"},{"phrase":"concentrate one's attention","zh":"集中注意力"},{"phrase":"concentrate efforts on","zh":"把努力集中在……上"},{"phrase":"orange juice concentrate","zh":"浓缩橙汁"},{"phrase":"concentrate the mind","zh":"使头脑高度集中；使认真思考"},{"phrase":"concentrate power in","zh":"把权力集中到……"}],"forms":[{"label":"第三人称单数","form":"concentrates"},{"label":"过去式","form":"concentrated"},{"label":"过去分词","form":"concentrated"},{"label":"现在分词","form":"concentrating"},{"label":"名词复数","form":"concentrates"}],"derivatives":[{"word":"concentrated","pos":"adj.","zh":"集中的；浓缩的；全神贯注的"},{"word":"concentration","pos":"n.","zh":"专注；集中；浓度"},{"word":"concentrator","pos":"n.","zh":"浓缩器；集中装置"},{"word":"concentrative","pos":"adj.","zh":"有集中作用的（罕用）"},{"word":"deconcentrate","pos":"v.","zh":"分散（权力、机构）"},{"word":"reconcentrate","pos":"v.","zh":"重新集中"}],"senses":[{"no":"01","title":"All rays to one point","titleCN":"光线汇聚：把能量收到一点","definition":"of light, heat, or energy, to bring rays together so that they meet at a single point","definitionCN":"指光、热或能量，把射线聚拢，使它们交于一点","example":"The lens concentrates the sun's rays at a single point and can set paper alight.","exampleCN":"这块透镜把阳光聚到一个点上，能把纸点燃。","why":"The 1630s word meant 'bring or come to a common center'. A lens is the clearest picture of that: many separate rays are drawn into one point.","whyCN":"这个义项可追溯到 17 世纪 30 年代，意为“带到共同的中心”。透镜是这个画面最清楚的例子：许多分散的光线被拉进同一个点。"},{"no":"02","title":"Gather in one place","titleCN":"人马聚集：收拢到一处","definition":"to bring people, troops, or objects together into one place","definitionCN":"把人、军队或物体集中到一个地方","example":"The general concentrated his troops along the eastern bank of the river.","exampleCN":"将军把部队集结在河东岸。","why":"People and troops can be treated like rays: the many are drawn from scattered positions into one area, so that force is available at a single point.","whyCN":"人和军队也可以像光线一样处理：分散各处的众多单位被拉进同一个区域，力量因此集中在一点上。"},{"no":"03","title":"Focus the mind","titleCN":"心思收拢：专注","definition":"to direct all one's attention and mental effort to one activity or subject","definitionCN":"把全部注意力和脑力投入到一项活动或一个主题上","example":"She switched off the radio and concentrated on the last chapter of her thesis.","exampleCN":"她关掉收音机，专心读论文的最后一章。","why":"The mental sense is recorded only from the 1860s, but it uses the same geometry: scattered thoughts are gathered and fixed on one point, and everything else is shut out.","whyCN":"这个“心智”义项要到 19 世纪 60 年代才有记录，但它沿用同一套几何：散乱的念头被收拢并固定在一个点上，其余一切被关在门外。"},{"no":"04","title":"Aim effort at one goal","titleCN":"力量定向：把资源投到一处","definition":"to direct resources, efforts, or activity toward a single aim rather than spreading them out","definitionCN":"把资源、努力或活动指向单一目标，而不是分散使用","example":"The company concentrated its resources on a single battery design.","exampleCN":"公司把资源集中到一种电池设计上。","why":"From the 1758 sense 'intensify the action': effort becomes stronger when it is not spread over many targets, because all of it arrives at the same place.","whyCN":"这来自 1758 年的义项“加强行动”：努力不铺在很多目标上时反而更强，因为全部力量都抵达同一处。"},{"no":"05","title":"Condense by removing water","titleCN":"浓缩：去掉水分使变浓","definition":"to make a liquid or substance stronger by removing water or other diluting material","definitionCN":"通过去除水分或其他稀释物，使液体或物质变浓","example":"The factory concentrates the orange juice by evaporating most of its water.","exampleCN":"工厂通过蒸发掉大部分水分来浓缩橙汁。","why":"The 1680s sense was 'condense'. If the useful part is what remains after water is taken away, then the substance has been gathered into a smaller volume — the same centering, now in a liquid.","whyCN":"17 世纪 80 年代的义项是“浓缩、压缩”。如果去掉水之后留下的才是有用部分，那么物质就被收进了更小的体积——同一个“向心”，只是发生在液体里。"},{"no":"06","title":"Enrich ore: keep the valuable part","titleCN":"选矿：留下有用矿物","definition":"in mining, to separate ore from waste rock so that the valuable mineral is more abundant","definitionCN":"在采矿中把矿石与废石分离，使有用矿物所占比例提高","example":"The plant concentrates the ore before it is shipped to the smelter.","exampleCN":"矿石在运往冶炼厂之前先经过选矿富集。","why":"Here the center is the valuable mineral: worthless rock is removed until what matters is gathered into a smaller, richer mass.","whyCN":"这里的“中心”是有价值的矿物：无用的废石被剔除，直到重要的东西被收成一小团更富的矿料。"},{"no":"07","title":"The concentrated substance","titleCN":"浓缩物：浓缩后的成品","definition":"a substance from which water has been removed, usually to be diluted before use","definitionCN":"已去除水分的物质，通常在使用前再稀释","example":"Add one spoonful of the concentrate to a litre of water.","exampleCN":"往一升水里加一勺浓缩液。","why":"The noun is recorded from 1883. Once the process is familiar, the product of the process takes the same name: the thing that has been gathered into a small volume.","whyCN":"名词用法记录于 1883 年。当这个过程为人熟悉之后，过程的产物就沿用了同一个名字：被收进小体积里的那个东西。"},{"no":"08","title":"Draw power to one center","titleCN":"权力集中：收到一个中心","definition":"to bring authority, control, or institutions together under one center","definitionCN":"把权力、控制权或机构收拢到一个中心之下","example":"The reform concentrated decision-making in the capital and weakened local councils.","exampleCN":"这项改革把决策权集中到首都，削弱了地方议会。","why":"Power behaves like rays too: when many separate decisions are drawn to one office, the center becomes stronger and the edges weaker.","whyCN":"权力也像光线：当许多分散的决策被吸到一个机构，中心变强，边缘变弱。"},{"no":"09","title":"Sharpened by pressure","titleCN":"压力逼出专注：使头脑清醒","definition":"to make someone think hard and seriously, often because of danger or a deadline","definitionCN":"使人认真而紧张地思考，常因危险或期限所致","example":"The prospect of being fired concentrated his mind wonderfully.","exampleCN":"被解雇的可能性奇妙地让他头脑高度集中起来。","why":"This is the mind sense under pressure: fear removes every competing thought, so all mental force arrives at one point, as if a lens had been held up to the sun.","whyCN":"这是“心智”义项在压力下的版本：恐惧赶走了所有竞争的念头，全部脑力抵达同一点，就像把透镜对准了太阳。"}],"etymology":{"intro":{"en":"Concentrate began as a word about geometry, not about thought: it named the act of bringing things to a common center. The mental and chemical senses came later.","cn":"concentrate 最初说的是几何，不是思想：它指把事物带到共同中心的动作。心智义与化学义都是后来才长出来的。"},"items":[{"era":"1630s","en":"First recorded in English as 'bring or come to a common center'. The earlier English form was concenter, with the same meaning.","cn":"英语中最早记录于 17 世纪 30 年代，意为“带到共同的中心”或“聚到共同的中心”。更早的英语形式是 concenter，意思相同。"},{"era":"ITALIAN concentrare","en":"The verb came through Italian concentrare, formed on Latin com- 'together' plus centrum 'center'. English did not build it from live English pieces.","cn":"这个动词经意大利语 concentrare 而来，由拉丁语 com-“一起”加 centrum“中心”构成。英语并不是用活的英语成分临时造出它的。"},{"era":"GREEK kentron","en":"Latin centrum came from Greek kentron 'sharp point, goad', from kentein 'to prick', from PIE *kent- 'prick'. The original picture is a pointed stick, not a circle.","cn":"拉丁语 centrum 来自希腊语 kentron“尖点、刺棒”，后者来自 kentein“刺”，可追溯到原始印欧语 *kent-“刺”。最初的画面是一根尖棒，而不是一个圆圈。"},{"era":"1680s","en":"A new sense appeared: 'to condense', that is, to reduce a substance to a smaller volume by removing water.","cn":"出现新义“浓缩、压缩”，即通过去除水分把物质减到更小的体积。"},{"era":"1758 · 1860s","en":"In 1758 the verb could mean 'to intensify the action'; from the 1860s it could mean 'to focus the mind'. The geometry had moved from space to attention.","cn":"1758 年起这个词可表示“加强行动”；19 世纪 60 年代起可表示“集中注意力”。这套几何从空间挪到了注意力上。"},{"era":"1883","en":"The noun appeared, meaning 'a concentrated substance'. By then the process and its product shared one word.","cn":"名词出现于 1883 年，意为“浓缩的物质”。到这时，过程和产物共用一个词。"}]},"similar":{"note":{"en":"The first group separates forms of the same word; the second group compares words that also describe drawing things together, each with a different mechanism.","cn":"第一组区分同一个词的各种形式；第二组比较同样表示“收拢”的词，但各自的作用机制不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"concentrated","ipa":"/ˈkɒnsntreɪtɪd/","tag":"adjective form","definition":"made stronger by removing water, or showing great mental effort. It describes the result or the person, while concentrate is the verb or the substance.","definitionCN":"经去水而变浓的，或全神贯注的。它描述结果或人的状态，而 concentrate 是动词或浓缩物本身。"},{"word":"concentration","ipa":"/ˌkɒnsənˈtreɪʃn/","tag":"noun of process and measure","definition":"the act of focusing, or the amount of a substance in a given volume. It is the noun, not a synonym of the verb.","definitionCN":"专注的行为，或某物质在一定体积中的含量。它是名词，并不是动词的同义词。"},{"word":"concenter","ipa":"/kənˈsentə/","tag":"older spelling","definition":"an older English form meaning 'to bring to a common center'. It survives in some American dictionaries as a variant, but concentrate is the standard form.","definitionCN":"较早的英语形式，意为“带到共同中心”。部分美国词典仍把它列为变体，但标准形式是 concentrate。"}]},{"heading":"NEAR MEANING","entries":[{"word":"focus","ipa":"/ˈfəʊkəs/","tag":"point of sharpness","definition":"to adjust so that an image or attention is sharp at one point. Focus is often used for eyes, cameras and attention; concentrate adds the idea of gathering scattered force.","definitionCN":"调整使图像或注意力在某一点上清晰。focus 常用于眼睛、相机和注意力；concentrate 还多一层“把分散的力量收拢”的意思。"},{"word":"condense","ipa":"/kənˈdens/","tag":"reduce volume","definition":"to make something denser or shorter, especially by removing water or words. Condense names the physical reduction; concentrate names the gathering of what remains.","definitionCN":"使某物更密或更短，尤其通过去除水分或文字。condense 说的是体积上的压缩，concentrate 说的是剩余物被收拢。"},{"word":"centralize","ipa":"/ˈsentrəlaɪz/","tag":"power to one center","definition":"to move control or administration to one central authority. It is mainly institutional and political; concentrate can also be physical or mental.","definitionCN":"把控制权或管理权移到某个中央机构。它主要用于制度和政治语境；concentrate 还可以是物理或心智上的。"},{"word":"gather","ipa":"/ˈɡæðə/","tag":"general collecting","definition":"to bring people or things together. Gather is neutral about where they end up; concentrate implies that they are drawn to a single center.","definitionCN":"把人或物聚到一起。gather 不强调最终聚在哪里；concentrate 暗示它们被吸向同一个中心。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: con- 'together', centrum 'center', the suffix -ate, and the older spelling concenter.","cn":"只用真实构词成分与真实同族词：con-“一起”、centrum“中心”、后缀 -ate，以及旧拼写 concenter。"},"normal":[{"en":"con- means 'together' and centrum means 'center'. To concentrate is to bring things together at one center.","cn":"con- 表示“一起”，centrum 表示“中心”。concentrate 就是把事物一起带到同一个中心。"},{"en":"The older English spelling was concenter, literally 'center together'. Concentrate is the form that became standard.","cn":"较早的英语拼写是 concenter，字面就是“把中心并到一起”。后来成为标准形式的是 concentrate。"},{"en":"Space came first: in the 1630s the word was about rays and troops, not about studying. The mind sense is only from the 1860s.","cn":"空间义在先：17 世纪 30 年代这个词说的是光线和军队，不是读书。心智义要到 19 世纪 60 年代才出现。"},{"en":"Concentration is both the act of focusing and the measure of strength, as in the concentration of a solution.","cn":"concentration 既是“专注”这个动作，也是“浓度”这个量度，如溶液的浓度。"},{"en":"A concentrate is the substance left after water is removed: the useful part gathered into a small volume.","cn":"a concentrate 是去掉水之后留下的物质：有用部分被收进了很小的体积。"}],"abstract":[{"en":"Picture many thin streams of water running across a floor, then all bending toward one drain. That bending is concentrate.","cn":"想象地板上许多细细的水流，然后全部弯向同一个排水口。那个“弯向一处”的过程就是 concentrate。"},{"en":"The drain can be a lens, a battlefield, a single goal, a sheet of paper, or a spoonful of juice. What stays constant is the many becoming one point.","cn":"这个排水口可以是透镜，可以是战场，可以是一个目标、一页纸，也可以是一勺果汁。不变的是“许多”变成“一个点”。"},{"en":"When the mind is the scene, the word does not mean 'try harder' but 'remove everything that is not the point'.","cn":"当场景换成头脑，这个词的意思不是“更努力”，而是“把不是这一点的东西全部移开”。"}]},"examples":[{"en":"The lens concentrated the sunlight and burned a small hole in the paper.","cn":"透镜把阳光聚起来，在纸上烧出了一个小洞。"},{"en":"It is hard to concentrate on a lecture when the room is too hot.","cn":"房间太热时，很难把注意力集中在讲座上。"},{"en":"The manufacturer ships frozen concentrate, and the buyer adds water at the factory.","cn":"制造商运送冷冻浓缩液，买家在工厂里加水稀释。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“肯森吹特”——肯（con）森（cen）吹（tra）特（te）：森林里风很大，他仍把全部心思收在一个点上 → concentrate 集中、专心","word":"concentrate"},"root":"源自拉丁语 com-“一起”+ centrum“中心”（后者出自希腊语 kentron“尖点”），核心是“把分散的东西收拢到同一个中心”。","sensesIntro":{"en":"Nine senses of concentrate, all built on one geometry: many scattered things are drawn to a single center, whether they are rays, troops, thoughts, resources, water, ore or power.","cn":"concentrate 的九个义项都建立在同一个几何上：许多分散的东西被吸向单一中心——不论它们是光线、军队、念头、资源、水、矿石还是权力。"},"semanticMap":{"core":{"en":"CORE IMAGE: scattered lines bend toward one center.","cn":"核心意象：分散的线条弯向同一个中心。"},"chain":["MANY DIRECTIONS","ONE CENTER","DRAW TOGETHER","ATTENTION FIXED","WATER REMOVED","STRENGTH INTENSIFIED"],"branches":[{"senses":"S1 · S2","en":"PHYSICAL CONVERGENCE: rays meet at a focal point; troops or crowds are gathered into one area.","cn":"物理汇聚：光线交于焦点；军队或人群被集结到一个区域。"},{"senses":"S3 · S9","en":"MENTAL FOCUS: thoughts are fixed on one subject, and pressure can sharpen that focus to a single point.","cn":"心智专注：念头固定在一个主题上，压力还能把这种专注逼成一点。"},{"senses":"S4 · S8","en":"DIRECTED FORCE: resources are aimed at one goal, and authority is drawn into one center.","cn":"定向力量：资源投向一个目标，权力被吸进一个中心。"},{"senses":"S5 · S7","en":"REDUCED VOLUME: water is removed, and the remaining substance takes the name of the process.","cn":"体积缩小：水分被去掉，剩下的物质沿用了这个过程的名字。"},{"senses":"S6","en":"ENRICHMENT: waste rock is removed until the valuable mineral is gathered into a richer mass.","cn":"富集：废石被剔除，直到有用矿物被收成更富的一团。"}]},"affixes":{"intro":{"en":"Concentrate is built from Latin pieces that are still readable: con- 'together', centrum 'center', and the verb suffix -ate. English then adds -ed, -ion, -or and productive prefixes such as de- and re-.","cn":"concentrate 由仍然可读的拉丁成分构成：con-“一起”、centrum“中心”，以及动词后缀 -ate。英语随后再加 -ed、-ion、-or，以及 de-、re- 这类能产前缀。"},"latinIntro":{"en":"The Latin verb concentrare joins com- and centrum. Latin centrum itself was borrowed from Greek kentron, whose first meaning was a sharp point or goad. The center of a circle is named after that point.","cn":"拉丁动词 concentrare 由 com- 与 centrum 组成。拉丁语 centrum 又是从希腊语 kentron 借来的，其最初含义是尖点或刺棒。圆圈的“中心”正是由这个尖点得名。"},"items":[{"word":"concentrated","structure":"concentrate + -ed (past participle and adjective)","meaning":"made denser, or fully attentive","meaningCN":"浓缩的；集中的；全神贯注的（-ed 构成分词与形容词）","example":"A concentrated solution needs less space on the shelf.","exampleCN":"浓缩溶液在货架上占的空间更小。"},{"word":"concentration","structure":"concentrate + -ion (action or result noun)","meaning":"the act of focusing; the amount present in a volume","meaningCN":"专注；集中；浓度（-ion 构成行为或结果名词）","example":"The concentration of salt in the lake has doubled.","exampleCN":"湖水的含盐浓度翻了一倍。"},{"word":"concentrator","structure":"concentrate + -or (agent or instrument noun)","meaning":"a device or person that concentrates something","meaningCN":"浓缩器；选矿设备；集中者（-or 表示施动者或工具）","example":"The concentrator removes water from the milk before transport.","exampleCN":"浓缩器在运输前把牛奶中的水去掉。"},{"word":"concentrative","structure":"concentrate + -ive (adjective of tendency)","meaning":"having the power to concentrate; rare","meaningCN":"有集中作用的（-ive 表示倾向；罕用）","example":"The lens has a concentrative effect on weak sunlight.","exampleCN":"这块透镜对微弱阳光有汇聚作用。"},{"word":"deconcentrate","structure":"de- (reverse, away) + concentrate","meaning":"to spread out power or institutions that were centralised","meaningCN":"分散（原已集中的权力或机构）（de- 表示反向）","example":"The government promised to deconcentrate health services.","exampleCN":"政府承诺把医疗服务的管理权下放分散。"},{"word":"deconcentration","structure":"de- + concentrate + -ion","meaning":"the process of spreading power away from one center","meaningCN":"权力分散化；去集中化","example":"Deconcentration moved offices to three regional cities.","exampleCN":"分散化把办公机构迁到了三个区域城市。"},{"word":"reconcentrate","structure":"re- (again) + concentrate","meaning":"to concentrate again or more tightly","meaningCN":"重新集中；再次收拢（re- 表示再次）","example":"The army reconcentrated its units after the retreat.","exampleCN":"撤退之后，军队重新集结了部队。"},{"word":"center","structure":"centr- + -er, from Latin centrum","meaning":"the middle point of something","meaningCN":"中心；中央（同一 centrum 词根）","example":"A circle is measured from its center.","exampleCN":"圆是从圆心开始度量的。"},{"word":"eccentric","structure":"ek- (out of) + centrum (center)","meaning":"away from the center; hence unconventional","meaningCN":"偏离中心的；引申为古怪的（ek- 表示“在……之外”）","example":"An eccentric orbit is not centred on the earth.","exampleCN":"偏心轨道的中心与地球并不重合。"},{"word":"centric","structure":"centr- + -ic (adjective)","meaning":"placed at or relating to a center","meaningCN":"中心的；以中心为准的","example":"The design is centric, with everything radiating from one hall.","exampleCN":"这个设计是中心式的，一切都从一个大厅向外辐射。"},{"word":"centrifugal","structure":"centr- + -fugal (from fugere 'to flee')","meaning":"moving or tending away from the center","meaningCN":"离心的（-fugal 来自 fugere“逃离”）","example":"The spinning drum pushes the liquid outward by centrifugal force.","exampleCN":"旋转的圆筒靠离心力把液体推向外侧。"},{"word":"centripetal","structure":"centr- + -petal (from petere 'to seek')","meaning":"moving or tending toward the center","meaningCN":"向心的（-petal 来自 petere“寻求”）","example":"Gravity supplies the centripetal force that keeps the planet in orbit.","exampleCN":"引力提供向心力，使行星保持在轨道上。"}],"latinEntries":[{"word":"concentrare","structure":"com- (together) + centrum (center) + -are (verb)","meaning":"to bring to a common center","meaningCN":"带到共同的中心；集中"},{"word":"centrum","structure":"borrowed from Greek kentron","meaning":"center, middle point","meaningCN":"中心；中点"},{"word":"kentron","structure":"kentein 'to prick' + -tron (instrument)","meaning":"sharp point, goad","meaningCN":"尖点；刺棒"}]}},{"word":"concept","ipa_uk":"/ˈkɒnsept/","ipa_us":"/ˈkɑːnsept/","definition_zh":"概念；观念；构想；（产品或设计的）概念方案","definition_en":"an abstract idea or general notion formed in the mind; also a plan or design idea for something to be made","core_image":"把许多具体事例收进一个可以反复使用的思维盒子","scene":"The concept of fairness is easy to invoke and very hard to define.","sceneCN":"这里 concept 是「概念、观念」（第 1 个义项：从许多具体事例中抽象出来的一般观念）；句意：公平这个概念很容易被援引，却很难被定义。场景要点：一个抽象的思维单位、许多具体案例、定义时的困难。","pos":[{"tag":"n.","zh":"概念；观念"},{"tag":"n.","zh":"构想；（产品或设计的）概念方案"}],"collocations":[{"phrase":"the concept of","zh":"……的概念"},{"phrase":"a basic concept","zh":"基本概念"},{"phrase":"an abstract concept","zh":"抽象概念"},{"phrase":"grasp the concept","zh":"理解这个概念"},{"phrase":"proof of concept","zh":"概念验证；可行性验证"},{"phrase":"a concept car","zh":"概念车"},{"phrase":"a concept album","zh":"概念专辑"}],"forms":[{"label":"名词复数","form":"concepts"}],"derivatives":[{"word":"conceptual","pos":"adj.","zh":"概念上的；观念性的"},{"word":"conceptually","pos":"adv.","zh":"在概念上；从观念层面看"},{"word":"conception","pos":"n.","zh":"概念的形成；构想；受孕"},{"word":"conceptualize","pos":"v.","zh":"使概念化；形成概念"},{"word":"conceptualization","pos":"n.","zh":"概念化；概念形成过程"},{"word":"misconception","pos":"n.","zh":"误解；错误观念"}],"senses":[{"no":"01","title":"A general idea formed by abstraction","titleCN":"抽象而成的一般观念","definition":"a general idea of something, formed by taking what many particular cases share and leaving the rest aside","definitionCN":"关于某事物的一般观念，由提取许多具体事例的共同点、略去其余细节而形成","example":"The concept of fairness is easy to invoke and very hard to define.","exampleCN":"公平这个概念很容易被援引，却很难被定义。","why":"Latin conceptum meant 'a draft, an abstract'. The mind takes many cases in and holds only their common shape, which is exactly what a concept is.","whyCN":"拉丁语 conceptum 意为“草稿、抽象物”。头脑把许多事例拿进来，只保留它们共同的形状，这正是概念。"},{"no":"02","title":"A plan or design idea","titleCN":"构想：还没做出来的方案","definition":"an idea for something that could be made or done, existing first in the mind rather than in the world","definitionCN":"关于某件可以做出来或做成的事情的想法，先存在于头脑而非现实世界","example":"The architect showed us the concept for the new library before drawing a single wall.","exampleCN":"建筑师还没画一面墙，就先给我们看了新图书馆的构想。","why":"A concept is a thing held in the mind before it is built. The abstract unit becomes a plan when it is pointed at a future object.","whyCN":"概念是在事物被造出来之前先被头脑握住的东西。当这个抽象单位指向未来的某个对象时，它就成了方案。"},{"no":"03","title":"Product concept: a car, store or phone that is not for sale","titleCN":"产品概念：概念车、概念店","definition":"a prototype or themed format shown to test and advertise an idea rather than to be sold as it stands","definitionCN":"为检验和展示某个想法而推出的原型或主题化形式，本身并不作为成品出售","example":"The company unveiled a concept car with no steering wheel.","exampleCN":"公司推出了一款没有方向盘的概念车。","why":"Industry borrows the word for a design that exists mainly to carry an idea. The object is real, but its job is to hold and display the concept.","whyCN":"工业界借用了这个词，指主要为承载某个想法而存在的设计。这个物件是真实的，但它的任务是握住并展示那个概念。"},{"no":"04","title":"A philosophical or scientific category","titleCN":"哲学与科学的范畴","definition":"in philosophy and science, a general category or term under which particular things are thought","definitionCN":"在哲学与科学中，用来统摄具体事物的一般范畴或术语","example":"In Kant's account, a concept without intuition is empty.","exampleCN":"在康德的理论中，没有直观的概念是空的。","why":"Philosophy made the word technical: a concept is the unit by which the mind organizes experience, so it must be both general and applicable to cases.","whyCN":"哲学把这个词术语化：概念是头脑组织经验的单位，因此它既必须是一般的，又必须能落到具体事例上。"},{"no":"05","title":"A mental representation in psychology","titleCN":"心理学中的心理表征","definition":"in psychology, the internal representation of a category that lets a person recognize new examples","definitionCN":"在心理学中，某类事物的内部表征，使人能够认出新的例子","example":"Children form a concept of number long before they learn written numerals.","exampleCN":"儿童在学习书写数字之前很久，就已形成数的概念。","why":"If a concept is something held in the mind, psychology can study the holding itself: how it is formed, stored and used to sort new cases.","whyCN":"如果概念是被头脑握住的东西，心理学就可以研究“握住”本身：它如何形成、储存，并被用来归类新的例子。"},{"no":"06","title":"An organizing theme in art","titleCN":"艺术中的统摄主题","definition":"a unifying idea that shapes a work or a group of works, such as an album or an exhibition","definitionCN":"统摄一件作品或一组作品（如专辑、展览）的统一想法","example":"The album's concept is a journey through five cities, one side per city.","exampleCN":"这张专辑的概念是穿越五座城市的旅程，每座城市占一面。","why":"A concept can hold a set of songs or paintings together the way it holds a set of cases: one idea gives many separate pieces a common shape.","whyCN":"概念可以像统摄许多事例那样统摄一组歌曲或画作：一个想法赋予许多独立作品共同的形状。"},{"no":"07","title":"Awareness or understanding, often in the negative","titleCN":"了解与认识（常用于否定）","definition":"an understanding of something, especially in phrases such as 'no concept of'","definitionCN":"对某事物的了解，尤用于 no concept of 这类说法","example":"He has no concept of how much this renovation will cost.","exampleCN":"他完全不知道这次翻修要花多少钱。","why":"Not to have a concept is not to hold the idea at all: the mental box is missing, so the facts have nowhere to sit.","whyCN":"没有概念，就是根本没有握住那个想法：头脑里的盒子不在，事实便无处安放。"},{"no":"08","title":"Proof of concept: an idea tested in small form","titleCN":"概念验证：用小样检验想法","definition":"a small trial or prototype that shows an idea can work, without yet being a full product","definitionCN":"用小型试验或原型证明某个想法可行，但还不是完整产品","example":"The device is only a proof of concept; a market version is years away.","exampleCN":"这个装置只是概念验证；面向市场的版本还要多年。","why":"Before an idea is built at full size, it is held in a small object to see whether it survives contact with reality. That object is the concept made testable.","whyCN":"在一个想法被完整造出来之前，先把它握在一件小物件里，看它能否经得起现实的接触。那件小物件就是被变得可检验的概念。"},{"no":"09","title":"A unit of meaning in semantics","titleCN":"语义学中的意义单位","definition":"in semantics and logic, the abstract meaning that a word or symbol expresses","definitionCN":"在语义学和逻辑学中，词或符号所表达的抽象意义","example":"The word 'red' expresses the concept RED, which many languages divide differently.","exampleCN":"red 这个词表达 RED 这一概念，而许多语言对它的切分并不相同。","why":"This is the abstract unit at its purest: a concept is what a word carries, independent of any single thing in the world that happens to be red.","whyCN":"这是抽象单位最纯粹的形态：概念是词所承载的东西，独立于世界上任何一个恰好是红色的事物。"}],"etymology":{"intro":{"en":"Concept is a Renaissance borrowing from Medieval Latin, and its doublet conceit tells the story of why it had to be borrowed twice.","cn":"concept 是文艺复兴时期从中世纪拉丁语借来的词，而它的同源异形词 conceit 正好解释了它为什么被借了两次。"},"items":[{"era":"1550s","en":"First recorded in English in the 1550s, meaning 'an abstract idea, a general notion'.","cn":"英语中最早记录于 16 世纪 50 年代，意为“抽象观念、一般概念”。"},{"era":"MEDIEVAL LATIN conceptum","en":"Medieval Latin conceptum meant 'a draft, an abstract'. It was a noun use of the past participle of concipere.","cn":"中世纪拉丁语 conceptum 意为“草稿、抽象物”，是 concipere 过去分词的名词化用法。"},{"era":"LATIN concipere","en":"Concipere meant 'to take in and hold; to become pregnant': con- (probably intensive) plus capere 'to take', from PIE *kap- 'to grasp'.","cn":"concipere 意为“拿进来并握住；受孕”：con-（可能为加强义）加 capere“拿取”，可追溯到原始印欧语 *kap-“抓握”。"},{"era":"DOUBLET conceit","en":"Conceit is the same Latin word shaped through French. In the 16th century conceit acquired a negative colouring (vanity, a fanciful turn of phrase), so concept was brought in again as a neutral term.","cn":"conceit 是同一个拉丁词经法语塑形后的形式。16 世纪 conceit 染上了负面色彩（自负、奇巧的措辞），于是 concept 被重新引入，用作中性的说法。"},{"era":"17C.–18C.","en":"Concept became a standard technical term in philosophy and logic, naming the general idea under which particulars are thought.","cn":"17 至 18 世纪，concept 成为哲学与逻辑学的标准术语，指统摄具体事物的一般观念。"},{"era":"MODERN ENGLISH","en":"Modern English extends the word to design (concept car), business (proof of concept), art (concept album) and retail (concept store). The abstract unit is now attached to objects that carry it.","cn":"现代英语把这个词扩展到设计（概念车）、商业（概念验证）、艺术（概念专辑）和零售（概念店）。这个抽象单位如今被附着在承载它的物件上。"}]},"similar":{"note":{"en":"The first group is made of forms and relatives of the same Latin verb; the second group compares words that also name something held in the mind.","cn":"第一组由同一个拉丁动词的各种形式与亲属词构成；第二组比较同样指“头脑中所握之物”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conceit","ipa":"/kənˈsiːt/","tag":"doublet, now negative","definition":"the same Latin word as concept, but it now means excessive pride or a fanciful literary comparison. Its negative colour is why concept was borrowed again.","definitionCN":"与 concept 同出一个拉丁词，但现在指过度自负或奇巧的文学比喻。正是它的负面色彩促使 concept 被再次借入。"},{"word":"conception","ipa":"/kənˈsepʃn/","tag":"same root, different noun","definition":"the act of forming a concept, a particular way of understanding something, or (biologically) becoming pregnant. It names the forming or the version held, while concept names the unit itself.","definitionCN":"形成概念的行为、对某事物的特定理解方式，或（生物学上的）受孕。它说的是“形成过程”或“所持的版本”，而 concept 说的是那个单位本身。"},{"word":"misconception","ipa":"/ˌmɪskənˈsepʃn/","tag":"mis- + conception","definition":"a wrong belief or understanding. It is a conception that has taken in the wrong shape, not a concept that has been badly defined.","definitionCN":"错误的信念或理解。它是“收错了形状”的 conception，而不是“定义得不好”的 concept。"}]},{"heading":"NEAR MEANING","entries":[{"word":"notion","ipa":"/ˈnəʊʃn/","tag":"vague or faint idea","definition":"a general or vague idea, often one held without much evidence. A notion can be faint or whimsical; a concept is usually more definite and shareable.","definitionCN":"一般或模糊的想法，常缺乏充分依据。notion 可以模糊、随意；concept 通常更确定、更可共享。"},{"word":"idea","ipa":"/aɪˈdɪə/","tag":"broad everyday word","definition":"a thought, plan, or belief of any kind. It is the widest of the group: an idea can be a sudden thought, a plan, or a whole philosophy.","definitionCN":"任何种类的想法、计划或信念。它是这组词里范围最广的：可以是一闪而过的念头、一个计划，也可以是整套哲学。"},{"word":"conception","ipa":"/kənˈsepʃn/","tag":"a particular understanding","definition":"a person's or a period's way of understanding something: 'a medieval conception of the universe'. It is the shaped version, while concept is the unit.","definitionCN":"某个人或某个时期对某事物的理解方式，如 a medieval conception of the universe。它强调的是成形的版本，而 concept 是单位本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: con- 'together', capere 'to take', the Medieval Latin conceptum 'draft', and the doublet conceit.","cn":"只用真实构词成分与真实同族词：con-“一起”、capere“拿取”、中世纪拉丁语 conceptum“草稿”，以及同源异形词 conceit。"},"normal":[{"en":"con- means 'together' and capere means 'to take'. A concept is what the mind takes in and holds together.","cn":"con- 表示“一起”，capere 表示“拿取”。concept 就是头脑拿进来并握在一起的东西。"},{"en":"Conceptum meant 'a draft, an abstract': a sketch of many cases reduced to their common outline.","cn":"conceptum 意为“草稿、抽象物”：把许多事例压缩成共同轮廓的一张草图。"},{"en":"Conceit is the same word through French; when it turned negative in the 16th century, concept was borrowed again to do the neutral work.","cn":"conceit 是同一个词经法语而来的形式；16 世纪它染上负面色彩后，concept 被再次借入，承担中性的职务。"},{"en":"Conception is the act of forming a concept, and also the biological sense 'becoming pregnant', both from the same Latin verb.","cn":"conception 是形成概念的行为，也有生物学上的“受孕”义，两者都来自同一个拉丁动词。"},{"en":"Conceptual means 'of concepts'; to conceptualize is to turn an experience into a concept that can be handled and shared.","cn":"conceptual 意为“概念上的”；conceptualize 就是把经验变成一个可以操作、可以共享的概念。"}],"abstract":[{"en":"Picture a row of different red objects, then a hand taking only their redness and putting it into a labelled box. That box is the concept.","cn":"想象一排各不相同的红色物件，然后一只手只取走它们的“红”，放进一只贴标签的盒子。那只盒子就是概念。"},{"en":"The same box can later be handed to someone else, tested on a new object, or drawn on a sketchpad as a design. That is how a concept becomes shared, applied, or built.","cn":"同一只盒子随后可以交给别人、拿去检验新对象，或者画在草图上变成设计。概念就是这样变得可共享、可应用、可建造。"},{"en":"A concept is not a word and not a thing: it is the stable shape that lets a word point to many things without naming each one.","cn":"概念既不是词，也不是物：它是那个稳定的形状，使一个词能指向许多事物而不必逐一命名。"}]},"examples":[{"en":"The concept of zero took centuries to become ordinary in Europe.","cn":"零的概念在欧洲用了好几个世纪才变得平常。"},{"en":"The team agreed on the concept before arguing about the details.","cn":"团队先就总体构想达成一致，然后才争论细节。"},{"en":"The prototype is a proof of concept, not a finished product.","cn":"这个原型只是概念验证，不是成品。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康塞普特”——康（con）把许多例子塞（cep）进一个盒子，普特（pt）贴上标签，盒子就成了概念 → concept 概念、观念","word":"concept"},"root":"源自拉丁语 concipere“拿进来并握住；受孕”，经中世纪拉丁语 conceptum“草稿、抽象物”进入英语，核心是“头脑把许多具体事例握成一个可反复使用的单位”。","sensesIntro":{"en":"Nine senses of concept, all grown from one act: the mind takes many particulars in, holds their common shape, and can then apply that shape to new cases, new designs, or new works.","cn":"concept 的九个义项都从同一个动作长出来：头脑把许多具体事物拿进来，握住它们共同的形状，随后又能把这个形状用到新事例、新设计或新作品上。"},"semanticMap":{"core":{"en":"CORE IMAGE: many particulars are reduced to one shape that the mind can hold and reuse.","cn":"核心意象：许多具体事物被收成一个形状，头脑可以握住它并反复使用。"},"chain":["MANY PARTICULARS","MIND TAKES IN","ONE HELD SHAPE","ABSTRACT UNIT","SHARED MEANING","PLAN OR THEME"],"branches":[{"senses":"S1 · S9","en":"THE ABSTRACT UNIT: a general idea, and the meaning a word or symbol carries.","cn":"抽象单位：一般观念，以及词或符号所承载的意义。"},{"senses":"S2 · S3","en":"THE DESIGN IDEA: a plan held before anything is built, and a prototype that displays it.","cn":"设计构想：建造之前就握住的方案，以及展示它的原型。"},{"senses":"S4","en":"THE CATEGORY: philosophy turns the unit into a technical term for organizing experience.","cn":"范畴：哲学把这个单位变成组织经验的术语。"},{"senses":"S5 · S7","en":"THE MENTAL GRIP: psychology studies how the shape is formed, and everyday speech asks whether someone holds it at all.","cn":"心智握持：心理学研究这个形状如何形成，日常说法则问一个人到底有没有握住它。"},{"senses":"S6 · S8","en":"THE ORGANIZING IDEA: one concept can shape an album, or be shrunk into a small test of feasibility.","cn":"统摄性想法：一个概念可以塑成一张专辑，也可以被缩小成一次可行性检验。"}]},"affixes":{"intro":{"en":"Concept is a borrowed Latin noun, so English does not build it from a live prefix. Its Latin pieces con- 'together' and capere 'to take' remain visible, and English adds -ual, -ion, -ize and -ization to make new words.","cn":"concept 是借入的拉丁名词，英语并不是用活的前缀来造它的。它的拉丁成分 con-“一起”和 capere“拿取”仍然看得见，英语再通过 -ual、-ion、-ize、-ization 造新词。"},"latinIntro":{"en":"The Latin family is built on concipere 'to take in, hold; conceive': conceptum 'a draft, abstract', conceptio 'a taking in', and the verb itself. English uses both the Latin-shaped concept and the French-shaped conceit.","cn":"这一拉丁词族建立在 concipere“拿进来、握住；受孕”上：conceptum“草稿、抽象物”、conceptio“拿进来”，以及动词本身。英语同时使用拉丁语形的 concept 和法语形的 conceit。"},"items":[{"word":"conceptual","structure":"concept + -ual (adjective)","meaning":"relating to concepts or to the level of ideas","meaningCN":"概念上的；观念层面的（-ual 构成形容词）","example":"The two plans differ only at the conceptual level.","exampleCN":"这两个方案只在概念层面有所不同。"},{"word":"conceptually","structure":"conceptual + -ly (adverb)","meaning":"in terms of concepts","meaningCN":"在概念上；从观念层面看","example":"The problem is conceptually simple but technically difficult.","exampleCN":"这个问题在概念上很简单，技术上却很难。"},{"word":"conception","structure":"concept + -ion (action or result noun)","meaning":"the forming of a concept; a way of understanding; also becoming pregnant","meaningCN":"概念的形成；理解方式；也指受孕（-ion 构成行为或结果名词）","example":"Her conception of the problem changed after the interview.","exampleCN":"采访之后，她对这一问题的理解改变了。"},{"word":"conceptualize","structure":"conceptual + -ize (verb)","meaning":"to form a concept of something","meaningCN":"使概念化；形成关于某事的概念（-ize 构成动词）","example":"It is hard to conceptualize a number as large as a trillion.","exampleCN":"很难把一万亿这样大的数字概念化。"},{"word":"conceptualization","structure":"conceptualize + -ation (process noun)","meaning":"the process of forming a concept","meaningCN":"概念化；概念形成过程","example":"The study traces the conceptualization of race in early maps.","exampleCN":"这项研究追溯了早期地图中“种族”概念的形成过程。"},{"word":"misconceive","structure":"mis- (wrongly) + conceive","meaning":"to understand something wrongly","meaningCN":"误解；对……形成错误理解","example":"Critics misconceive the purpose of the rule.","exampleCN":"批评者误解了这条规则的目的。"},{"word":"misconception","structure":"mis- + conception","meaning":"a wrong belief or understanding","meaningCN":"误解；错误观念","example":"It is a common misconception that gold is the heaviest metal.","exampleCN":"认为金是最重的金属，是一种常见的误解。"},{"word":"conceive","structure":"con- (together) + capere (take)","meaning":"to form an idea; to become pregnant","meaningCN":"构想；想出；怀孕","example":"She conceived the plan while walking home.","exampleCN":"她在走回家的路上想出了这个计划。"},{"word":"accept","structure":"ac- (to) + capere (take)","meaning":"to take something offered","meaningCN":"接受；收下（同一 capere 词根）","example":"He accepted the offer without hesitation.","exampleCN":"他毫不犹豫地接受了这个提议。"},{"word":"receive","structure":"re- (back) + capere (take)","meaning":"to take into one's hands or possession","meaningCN":"收到；接到（同一 capere 词根）","example":"She received the letter two days later.","exampleCN":"她两天后收到了那封信。"},{"word":"intercept","structure":"inter- (between) + capere (take)","meaning":"to take something on its way from one place to another","meaningCN":"拦截；截取（同一 capere 词根）","example":"The guard intercepted the pass and scored.","exampleCN":"后卫截下了那次传球并得分。"},{"word":"capture","structure":"capt- (from capere) + -ure (noun and verb)","meaning":"to take something by force; the act of taking","meaningCN":"捕获；俘获（capt- 来自 capere）","example":"The photograph captures the moment of surprise.","exampleCN":"这张照片捕捉到了惊讶的瞬间。"}],"latinEntries":[{"word":"concipere","structure":"con- (together, intensive) + capere (take)","meaning":"to take in and hold; to conceive, become pregnant","meaningCN":"拿进来并握住；构想；受孕"},{"word":"conceptum","structure":"concipere + -tum (past participle as noun)","meaning":"a draft, an abstract","meaningCN":"草稿；抽象物"},{"word":"capere","structure":"PIE *kap- 'to grasp'","meaning":"to take, seize, grasp","meaningCN":"拿取；抓住；握"}]}},{"word":"concern","ipa_uk":"/kənˈsɜːn/","ipa_us":"/kənˈsɜːrn/","definition_zh":"涉及；关系到；使担忧；担忧；关切；事务；公司","definition_en":"to relate to or affect someone; to make someone worried; a feeling of worry or care; a matter that belongs to someone, or a business","core_image":"一条线从某件事牵到你身上，把你的利害与它绑在一起","scene":"The second half of the report concerns the city's water supply.","sceneCN":"这里 concern 是「涉及、关于」（第 1 个义项：以某事为主题或对象）；句意：报告的后半部分讲的是城市供水问题。场景要点：一份报告、一个主题、后半部分全部落在这件事上。","pos":[{"tag":"v.","zh":"涉及；关系到；使担忧"},{"tag":"n.","zh":"担忧；关切；事务；公司"}],"collocations":[{"phrase":"be concerned about","zh":"对……感到担忧"},{"phrase":"as far as ... is concerned","zh":"就……而言"},{"phrase":"concern oneself with","zh":"关心；忙于；涉及"},{"phrase":"of concern to","zh":"对……来说值得关切的"},{"phrase":"express concern","zh":"表达关切"},{"phrase":"a going concern","zh":"持续经营的企业"},{"phrase":"no concern of mine","zh":"不关我的事"}],"forms":[{"label":"第三人称单数","form":"concerns"},{"label":"过去式","form":"concerned"},{"label":"过去分词","form":"concerned"},{"label":"现在分词","form":"concerning"},{"label":"名词复数","form":"concerns"}],"derivatives":[{"word":"concerned","pos":"adj.","zh":"担忧的；有关的；关切的"},{"word":"concerning","pos":"prep.","zh":"关于；涉及"},{"word":"unconcerned","pos":"adj.","zh":"不担忧的；漠不关心的"},{"word":"unconcern","pos":"n.","zh":"漠不关心；无忧虑"},{"word":"concernment","pos":"n.","zh":"重要性；关切（罕用）"}],"senses":[{"no":"01","title":"To be about: the subject of a text or talk","titleCN":"以……为主题：关于","definition":"of a text, speech, or discussion, to have a particular subject","definitionCN":"指文章、讲话或讨论以某一特定主题为内容","example":"The second half of the report concerns the city's water supply.","exampleCN":"报告的后半部分讲的是城市供水问题。","why":"Old French concerner could mean 'to relate to'. A report concerns a topic because the whole text is tied to that one matter.","whyCN":"古法语 concerner 可以表示“与……有关”。报告 concern 某个主题，是因为整篇文字都被系在那一件事上。"},{"no":"02","title":"To affect someone's interests","titleCN":"触及利害：与某人相关","definition":"to affect someone or something, especially in matters of interest, right, or risk","definitionCN":"影响某人或某事物，尤指在利益、权利或风险方面","example":"The new tax concerns every household in the district.","exampleCN":"这项新税关系到该区的每一户人家。","why":"The late 15th-century sense was 'affect the interest of'. The line from the matter reaches the person, so what happens to the matter also happens to the person.","whyCN":"15 世纪后期的义项是“影响……的利益”。那条从事情伸到人的线接上了，事情的变化也就成了人的变化。"},{"no":"03","title":"To involve oneself: concern oneself with","titleCN":"主动介入：关心并参与","definition":"to occupy oneself with something, or to take an interest in it and act on it","definitionCN":"使自己忙于某事，或对之产生兴趣并采取行动","example":"She concerned herself with the details that everyone else had ignored.","exampleCN":"她着手处理那些其他人都忽略了的细节。","why":"If a matter is tied to you, you can pull on the line yourself. The reflexive phrase makes the connection active rather than merely given.","whyCN":"如果一件事与你相连，你也可以自己拉那条线。反身说法让这层联系从“被动相关”变成“主动介入”。"},{"no":"04","title":"To make someone worried","titleCN":"使担忧：让人放不下心","definition":"to cause someone to feel anxious or troubled","definitionCN":"使某人感到焦虑或不安","example":"It concerns me that the back door was left open all night.","exampleCN":"后门整夜开着，这让我很不安。","why":"The 'worry' sense appeared in the 17th century. When something touches your interests and you cannot control it, the connection is felt as anxiety.","whyCN":"“担忧”义出现在 17 世纪。当某件事触及你的利害、而你又无法控制它时，这条连接就被感受为焦虑。"},{"no":"05","title":"Worry as a noun","titleCN":"名词：忧虑、担心","definition":"a feeling of anxiety about a problem or possible danger","definitionCN":"对某个问题或可能发生的危险感到焦虑","example":"There is growing concern about air quality in the valley.","exampleCN":"人们对山谷里的空气质量越来越担忧。","why":"The noun is recorded from the 1580s. It names the state produced by that taut line: the interest is still there, but it has tightened into unease.","whyCN":"名词用法记录于 16 世纪 80 年代。它命名的是那条绷紧的线所产生的状态：利害仍在，但已收紧成不安。"},{"no":"06","title":"Care for someone's welfare","titleCN":"关切：为他人的福祉操心","definition":"a feeling of care and responsibility for another person's well-being","definitionCN":"对他人福祉的关心与责任感","example":"Her concern for the new students went beyond their grades.","exampleCN":"她对新生们的关切超出了成绩范围。","why":"The same line can be warm rather than anxious. When the other person's interest matters to you, concern becomes care rather than worry.","whyCN":"同一条线也可以是温暖的，而不只是焦虑的。当对方的利害对你有分量时，concern 就成了关切，而不只是担忧。"},{"no":"07","title":"One's own business: a matter that belongs to you","titleCN":"分内之事：不关别人的事","definition":"a matter that belongs to a particular person and is their responsibility, not another's","definitionCN":"属于某个人、由其负责而不属于他人的事情","example":"What I do after work is no concern of yours.","exampleCN":"我下班后做什么不关你的事。","why":"If a matter is tied to you, it belongs to your side of the line. The noun therefore means a piece of business that is yours to handle.","whyCN":"如果一件事系在你身上，它就属于你这一侧。因此这个名词也指一件该由你处理的分内之事。"},{"no":"08","title":"A business or enterprise","titleCN":"商号、企业","definition":"a commercial business or firm, especially in older or formal usage","definitionCN":"商业企业或商号，尤见于较早或正式用法","example":"The family runs a small publishing concern in the old town.","exampleCN":"这家人在这座老城里经营一家小型出版公司。","why":"The 1680s sense was 'business, establishment'. A firm is a bundle of interests tied together, so the word for a tied matter came to name the organization that holds them.","whyCN":"17 世纪 80 年代的义项是“business、机构”。一家公司就是一束被系在一起的利害，于是表示“被系住之事”的词，转指握有这些利害的组织。"},{"no":"09","title":"As far as ... is concerned: the viewpoint frame","titleCN":"就……而言：划定视角","definition":"in the phrase 'as far as ... is concerned', with respect to that person or thing","definitionCN":"在 as far as ... is concerned 这一说法中，表示“就某人或某事物而言”","example":"As far as I'm concerned, the matter is closed.","exampleCN":"就我而言，这件事已经结束了。","why":"The phrase draws the line around one person's interests and says: from inside this boundary, this is how things look.","whyCN":"这个说法在某一个人的利害周围画一条线，意思是：站在这条边界以内看，事情是这样。"}],"etymology":{"intro":{"en":"Concern came through French from a Late Latin verb about sifting and mixing. The modern meanings of relation, worry and business all grow from that image of things being stirred together.","cn":"concern 经法语来自一个晚期拉丁动词，本义与“筛、混合”有关。现代的关系、担忧、事务等义，都从“东西被搅在一起”这个画面长出来。"},"items":[{"era":"EARLY 15C.","en":"First recorded in English, borrowed from Old French concerner, with the sense 'to relate to, to be relevant to'.","cn":"英语中最早记录于 15 世纪初，借自法语 concerner，意为“与……有关、对……有影响”。"},{"era":"MEDIEVAL LATIN concernere","en":"Medieval Latin concernere meant 'to concern, touch, belong to'. This was a figurative use of an older verb.","cn":"中世纪拉丁语 concernere 意为“涉及、触及、属于”。这是一个更早动词的比喻用法。"},{"era":"LATE LATIN concernere","en":"Late Latin concernere meant 'to sift, to mix as in a sieve': com- 'together' plus cernere 'to sift, perceive', from PIE *krei- 'sieve'.","cn":"晚期拉丁语 concernere 意为“筛、像用筛子那样混合”：com-“一起”加 cernere“筛、分辨”，可追溯到原始印欧语 *krei-“筛”。"},{"era":"LATE 15C.","en":"The sense 'to affect the interest of' is recorded. This is the bridge from 'be related to' to 'matter to someone'.","cn":"记录到“影响……的利益”这一义项。这是从“与……有关”通向“对某人有分量”的桥梁。"},{"era":"17C. · 1580s","en":"The emotional sense 'to worry' appears in the 17th century, while the noun is recorded from the 1580s with the sense of 'care, solicitude'.","cn":"“使担忧”的情感义出现在 17 世纪；名词则从 16 世纪 80 年代起有记录，意为“关心、挂念”。"},{"era":"1680s","en":"The noun acquired the sense 'business, establishment', which survives in 'a going concern' and in descriptions of a firm as a concern.","cn":"名词获得“business、机构”的义项，这一用法保存在 a going concern 以及把公司称作 a concern 的说法里。"}]},"similar":{"note":{"en":"The first group separates adjective, preposition and negative forms of the same word; the second group compares verbs of relation and verbs of feeling.","cn":"第一组区分同一个词的形容词、介词与否定形式；第二组比较表示“关联”的动词与表示“情感”的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"concerned","ipa":"/kənˈsɜːnd/","tag":"adjective form","definition":"worried, or involved in something: 'the concerned parents', 'the departments concerned'. It describes a person or thing, not the act of relating.","definitionCN":"担忧的，或与某事有关的：the concerned parents、the departments concerned。它描述人或事物，不表示“涉及”这个动作。"},{"word":"concerning","ipa":"/kənˈsɜːnɪŋ/","tag":"preposition form","definition":"about, with regard to: 'a letter concerning the lease'. As a preposition it is formal and close to 'regarding'.","definitionCN":"关于、就……而言：a letter concerning the lease。作介词时较正式，接近 regarding。"},{"word":"unconcerned","ipa":"/ˌʌnkənˈsɜːnd/","tag":"negative of the feeling","definition":"not worried or not interested. The un- negates the feeling, not the relation: an unconcerned observer is still observing the event.","definitionCN":"不担忧或不关心的。un- 否定的是情感，而不是关联：an unconcerned observer 仍然在观察那件事。"}]},{"heading":"NEAR MEANING","entries":[{"word":"worry","ipa":"/ˈwʌri/","tag":"emotional state","definition":"to feel anxious about a problem. It is more personal and emotional than concern, which can also be calm, formal care.","definitionCN":"对问题感到焦虑。它比 concern 更个人化、更情绪化；concern 也可以是冷静、正式的关切。"},{"word":"involve","ipa":"/ɪnˈvɒlv/","tag":"include as a participant","definition":"to include someone or something as a necessary part or participant. Concern means the matter touches someone's interests; involve means the person is inside the activity.","definitionCN":"把某人或某物作为必要部分或参与者包括进来。concern 指事情触及某人的利害；involve 指人处在活动之内。"},{"word":"pertain","ipa":"/pəˈteɪn/","tag":"formal relation","definition":"to relate or belong to something, used with 'to'. It is formal and has no emotional sense, unlike concern.","definitionCN":"与某事物有关或属于某事物，常与 to 连用。它较正式，也没有 concern 那种情感义。"},{"word":"affect","ipa":"/əˈfekt/","tag":"have an effect on","definition":"to produce a change in someone or something. Affect is broad and neutral; concern 02 adds the idea that the effect touches interests or rights.","definitionCN":"对某人或某物造成变化。affect 范围广且中性；concern 的第 2 个义项多一层“触及利益或权利”。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: com- 'together', cernere 'to sift', the Late Latin sense 'mix as in a sieve', and the ordinary derivatives concerned / concerning.","cn":"只用真实构词成分与真实同族词：com-“一起”、cernere“筛”、晚期拉丁语“像筛子一样混合”，以及普通派生词 concerned／concerning。"},"normal":[{"en":"Late Latin concernere meant 'to sift or mix together'. To be concerned is to have your affairs stirred into the same sieve as another's.","cn":"晚期拉丁语 concernere 意为“筛、一起混合”。be concerned 就是你的利害被搅进与对方同一只筛子里。"},{"en":"The medieval sense was 'touch, belong to': what concerns you is what touches you.","cn":"中世纪义项是“触及、属于”：concern 你的事，就是触到你的事。"},{"en":"Keep the forms apart: concerned means worried or involved, concerning means about, unconcerned means not worried — not 'not related'.","cn":"把形式分清：concerned 是“担忧的、有关的”，concerning 是“关于”，unconcerned 是“不担忧的”，而不是“无关的”。"},{"en":"The noun came first in the 1580s; the 'worry' sense is 17th-century. The emotion is a later tightening of the relation.","cn":"名词在 16 世纪 80 年代先出现；“担忧”义是 17 世纪的。情感是这层关系后来绷紧的结果。"},{"en":"A going concern is a business still operating: concern here means an enterprise, from the 1680s sense 'business, establishment'.","cn":"a going concern 指仍在经营的企业：这里的 concern 是“企业”，来自 17 世纪 80 年代“business、机构”的义项。"}],"abstract":[{"en":"Picture a thin thread tied to a parcel on one end and to your wrist on the other. Concern is that thread going taut.","cn":"想象一根细线，一头系在包裹上，另一头系在你的手腕上。concern 就是这根线绷紧的动作。"},{"en":"The thread explains all the senses: the parcel is the subject (S1), the pull is the effect (S2), the tug is worry (S4–S5), and the parcel on your side is your own business (S7–S8).","cn":"这根线能解释所有义项：包裹是主题（S1），拉力是影响（S2），猛拽是担忧（S4–S5），包裹落在你这一侧就是你的分内事（S7–S8）。"},{"en":"Concern is not automatically negative: a warm thread is care for someone, a slack thread is unconcern.","cn":"concern 并不自动是负面的：温暖的线是对人的关切，松掉的线就是漠不关心。"}]},"examples":[{"en":"The meeting will concern next year's budget and nothing else.","cn":"这次会议只讨论明年的预算，不涉及其他内容。"},{"en":"Parents are increasingly concerned about the amount of screen time their children get.","cn":"家长们越来越担心孩子使用屏幕的时间过长。"},{"en":"The company is a going concern and has no plans to close.","cn":"这家公司仍在持续经营，没有关闭的计划。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“肯瑟恩”——肯（con）把别人的事和自己的心用一根线瑟（cer）在一起，恩（n）怨也就跟着来了 → concern 涉及、担忧、关切","word":"concern"},"root":"源自拉丁语 concernere，晚期拉丁语意为“一起筛、混合”，中世纪拉丁语转为“触及、与……有关”，核心是“一件事与你缠在一起”。","sensesIntro":{"en":"Nine senses of concern, all grown from one thread: a matter is tied to a person, so it becomes that person's subject, interest, worry, care, or private business.","cn":"concern 的九个义项都从同一根线长出来：一件事系在某人身上，于是成为他的主题、利害、担忧、关切或分内之事。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thread ties a matter to a person's interests.","cn":"核心意象：一根线把一件事与一个人的利害系在一起。"},"chain":["A MATTER","TOUCHES YOU","YOUR INTEREST AT STAKE","YOU CARE","YOU WORRY","YOUR OWN BUSINESS"],"branches":[{"senses":"S1 · S2","en":"RELATION AND EFFECT: a text has a subject, and a change touches someone's rights or interests.","cn":"关系与影响：文本有一个主题，变化则触及某人的权利或利益。"},{"senses":"S3 · S6","en":"ENGAGEMENT AND CARE: the thread can be pulled actively, and it can be warm rather than anxious.","cn":"介入与关切：这根线可以被主动拉动，也可以是温暖的而不是焦虑的。"},{"senses":"S4 · S5","en":"WORRY: when the taut thread cannot be controlled, relation becomes anxiety in verb and noun.","cn":"担忧：绷紧的线无法控制时，关系就变成动词和名词上的焦虑。"},{"senses":"S7 · S9","en":"OWN BUSINESS AND VIEWPOINT: what is tied to your side is yours to handle, and the phrase 'as far as ... is concerned' marks that side.","cn":"分内事与视角：系在你这一侧的事由你处理；as far as ... is concerned 则标出这一侧。"},{"senses":"S8","en":"ENTERPRISE: a firm is a bundle of interests tied together, so concern comes to name the organization.","cn":"企业：公司是一束被系在一起的利害，因此 concern 转指这个组织。"}]},"affixes":{"intro":{"en":"Concern is a borrowed French verb, not an English prefix-plus-root construction. Its Latin pieces com- 'together' and cernere 'to sift' are frozen inside, while English freely adds -ed, -ing and un-.","cn":"concern 是借入的法语动词，不是英语“前缀加词根”的构造。它的拉丁成分 com-“一起”和 cernere“筛”凝固在词内，而英语可以自由加上 -ed、-ing 和 un-。"},"latinIntro":{"en":"The Latin family is built on cernere 'to sift, separate, perceive'. Concernere mixes things together; discernere separates them apart. The same root also gives secret, discrete and discriminate.","cn":"这一拉丁词族建立在 cernere“筛、分离、分辨”上。concernere 把东西混在一起；discernere 把它们分开。同一词根还给出 secret、discrete、discriminate。"},"items":[{"word":"concerned","structure":"concern + -ed (past participle and adjective)","meaning":"worried, or involved in a matter","meaningCN":"担忧的；有关的（-ed 构成分词与形容词）","example":"The concerned neighbours called the fire service.","exampleCN":"忧心的邻居们打电话叫来了消防队。"},{"word":"concerning","structure":"concern + -ing (present participle and preposition)","meaning":"about, with regard to","meaningCN":"关于；就……而言（-ing 构成分词与介词）","example":"She wrote a long letter concerning the delay.","exampleCN":"她就延误一事写了一封长信。"},{"word":"unconcerned","structure":"un- (not) + concerned","meaning":"not worried or not interested","meaningCN":"不担忧的；漠不关心的（un- 表示否定）","example":"He seemed unconcerned by the falling sales figures.","exampleCN":"他对下滑的销售数字似乎毫不在意。"},{"word":"unconcern","structure":"un- + concern (noun)","meaning":"lack of worry or interest","meaningCN":"漠不关心；无忧虑","example":"Her unconcern surprised the whole committee.","exampleCN":"她的漠不关心让整个委员会都很意外。"},{"word":"concernment","structure":"concern + -ment (state or thing noun)","meaning":"importance, or a matter of concern; rare","meaningCN":"重要性；关切之事（-ment 构成名词；罕用）","example":"The concernment of the issue was clear to everyone.","exampleCN":"这个问题的重要性人人都看得清楚。"},{"word":"discern","structure":"dis- (apart) + cernere (sift)","meaning":"to recognize or tell apart","meaningCN":"辨别；看出（dis- “分开”加“筛”）","example":"It is hard to discern the original colour of the wall.","exampleCN":"很难辨认出这面墙原来的颜色。"},{"word":"discernment","structure":"discern + -ment (quality noun)","meaning":"the ability to judge well","meaningCN":"洞察力；判断力","example":"She showed real discernment in choosing the design.","exampleCN":"她在选择设计方案时表现出真正的判断力。"},{"word":"discrete","structure":"dis- (apart) + cernere (sift) + -e","meaning":"separate and distinct","meaningCN":"分离的；各不相同的","example":"The process has four discrete stages.","exampleCN":"这个过程有四个彼此分离的阶段。"},{"word":"discretion","structure":"discret- + -ion (noun)","meaning":"the freedom to decide; also careful judgement","meaningCN":"自行决定权；谨慎","example":"The choice is left to the manager's discretion.","exampleCN":"这个选择交由经理自行决定。"},{"word":"discriminate","structure":"dis- (apart) + crimen (from cernere) + -ate","meaning":"to tell the difference; also to treat unfairly","meaningCN":"区别；歧视（同一 cernere 词根）","example":"A good taster can discriminate between two similar teas.","exampleCN":"好的品茶师能区分两种相近的茶。"},{"word":"secret","structure":"se- (apart) + cernere (sift)","meaning":"kept apart from the knowledge of others","meaningCN":"秘密的；被分出来不让人知道的","example":"They kept the plan secret until the last day.","exampleCN":"他们把这个计划一直保密到最后一天。"}],"latinEntries":[{"word":"concernere","structure":"com- (together) + cernere (sift)","meaning":"in Late Latin, to sift or mix as in a sieve; later, to concern or belong to","meaningCN":"晚期拉丁语中指“筛、像用筛子一样混合”；后转为“涉及、属于”"},{"word":"cernere","structure":"PIE *krei- 'sieve'","meaning":"to sift, separate, perceive","meaningCN":"筛；分离；分辨"},{"word":"discernere","structure":"dis- (apart) + cernere (sift)","meaning":"to separate, distinguish","meaningCN":"分开；辨别"}]}},{"word":"conclude","ipa_uk":"/kənˈkluːd/","ipa_us":"/kənˈkluːd/","definition_zh":"得出结论；断定；结束；缔结（协议）","definition_en":"to reach a judgment after reasoning; to bring something to an end; to settle an agreement formally","core_image":"把话头、争论或事务关进一只盒子，然后封口上锁","scene":"The chair concluded the meeting at noon, with no item left open.","sceneCN":"这里 conclude 是「结束、使终止」（第 1 个义项：把正在进行的事情带到终点）；句意：主席在正午结束了会议，没有留下任何未决议题。场景要点：一场会议、一个明确的终点、所有议题都被收口。","pos":[{"tag":"v.","zh":"得出结论；推断；断定"},{"tag":"v.","zh":"结束；终止；缔结（协议）"}],"collocations":[{"phrase":"conclude that","zh":"得出结论认为"},{"phrase":"conclude a deal","zh":"达成交易"},{"phrase":"conclude a treaty","zh":"缔结条约"},{"phrase":"conclude with","zh":"以……结束"},{"phrase":"to conclude","zh":"最后；总而言之"},{"phrase":"conclude from the evidence","zh":"根据证据推断"},{"phrase":"it is reasonable to conclude that","zh":"有理由断定"}],"forms":[{"label":"第三人称单数","form":"concludes"},{"label":"过去式","form":"concluded"},{"label":"过去分词","form":"concluded"},{"label":"现在分词","form":"concluding"}],"derivatives":[{"word":"conclusion","pos":"n.","zh":"结论；结束；缔结"},{"word":"conclusive","pos":"adj.","zh":"决定性的；结论性的"},{"word":"conclusively","pos":"adv.","zh":"决定性地；确凿地"},{"word":"inconclusive","pos":"adj.","zh":"无定论的；不足以定论的"},{"word":"conclusiveness","pos":"n.","zh":"决定性；确凿性"},{"word":"concluding","pos":"adj.","zh":"最后的；结尾的"}],"senses":[{"no":"01","title":"Shut the box: bring something to an end","titleCN":"关上盒子：把某事带到终点","definition":"to bring a meeting, activity, or period of time to an end","definitionCN":"把会议、活动或一段时间带到终点","example":"The chair concluded the meeting at noon, with no item left open.","exampleCN":"主席在正午结束了会议，没有留下任何未决议题。","why":"Latin concludere meant 'shut up, enclose'. To conclude a meeting is to shut all its business inside one closed space, so that nothing remains open.","whyCN":"拉丁语 concludere 意为“关闭、围住”。conclude a meeting 就是把会议的所有事务关进同一个封闭空间，不再有敞着的事项。"},{"no":"02","title":"Infer: reason from evidence","titleCN":"推断：从证据一路推下去","definition":"to reach a belief about something by reasoning from the available evidence","definitionCN":"根据现有证据进行推理，从而对某事形成判断","example":"From the footprints, we concluded that the thief had left through the garden.","exampleCN":"根据脚印，我们推断窃贼是从花园离开的。","why":"The late 14th-century sense was 'infer, deduce'. Reasoning moves step by step until the evidence is shut into one result: the conclusion closes the inquiry.","whyCN":"14 世纪后期的义项是“推断、演绎”。推理一步步向前，直到证据被关进同一个结果里：结论为探究封口。"},{"no":"03","title":"Arrive at a judgment","titleCN":"形成判断：断定","definition":"to decide or judge after considering the facts, especially in an official or formal setting","definitionCN":"在考虑事实之后作出决定或判断，尤指在正式场合","example":"The jury concluded that the evidence was insufficient to convict.","exampleCN":"陪审团断定证据不足以定罪。","why":"A judgment is the point at which deliberation stops. The box closes not because the topic is exhausted but because a decision has been reached.","whyCN":"判断是 deliberations 停止的那一点。盒子合上，不是因为话题被穷尽，而是因为已经作出了决定。"},{"no":"04","title":"Settle formally: conclude a treaty or deal","titleCN":"正式议定：缔结条约或交易","definition":"to settle an agreement, treaty, or deal in a formal and final way","definitionCN":"以正式而最终的方式议定协议、条约或交易","example":"The two countries concluded a trade agreement after eight months of talks.","exampleCN":"经过八个月的谈判，两国缔结了一项贸易协定。","why":"The early 15th-century sense was 'settle, arrange'. Negotiation stays open while terms move; conclude seals the terms inside a final text.","whyCN":"15 世纪早期的义项是“议定、安排”。条款还在变动时，谈判是敞开的；conclude 则把条款封进最终文本。"},{"no":"05","title":"End an argument by winning it","titleCN":"辩赢收场（古义）","definition":"in older usage, to end an argument by getting the better of one's opponent","definitionCN":"在较早用法中，指辩胜对手、使争论收场","example":"He concluded the debate with a single question that no one could answer.","exampleCN":"他用一个无人能答的问题结束了那场辩论。","why":"This is the earliest recorded sense, from the early 14th century: the argument is closed by shutting the other speaker out. Victory is the lock.","whyCN":"这是最早有记录的义项，来自 14 世纪早期：争论被关上，是因为对方被关在了外面。胜利就是那把锁。"},{"no":"06","title":"Come to an end","titleCN":"自行结束：落下帷幕","definition":"of an event or period, to come to an end without an outside agent","definitionCN":"指事件或时期自行走到终点，无需外部施动者","example":"The concert concluded with a standing ovation.","exampleCN":"音乐会在全场起立鼓掌中结束。","why":"The same closing can be viewed from the inside: instead of someone shutting the event, the event itself reaches the moment when it closes.","whyCN":"同一个“关闭”也可以从内部看：不是有人把事件关上，而是事件自己走到合拢的那一刻。"},{"no":"07","title":"Conclude with: finish by doing something","titleCN":"以……收尾：最后一项","definition":"to end a speech, performance, or list with a particular item","definitionCN":"以某一特定内容结束讲话、演出或清单","example":"She concluded her talk with a warning about the coming winter.","exampleCN":"她以一句关于即将到来的冬天的警告结束了演讲。","why":"The preposition marks the last object placed inside the box before the lid goes down. It is the final item that completes the boundary.","whyCN":"这个介词标出盖子落下之前放进盒子的最后一件东西。正是这最后一项补全了边界。"},{"no":"08","title":"To conclude: the summary marker","titleCN":"话语标记：最后、总而言之","definition":"in the phrase 'to conclude', used to introduce the final point of a speech or piece of writing","definitionCN":"在 to conclude 这一说法中，用来引出讲话或文章的最后一个要点","example":"To conclude, the plan is expensive but still the cheapest option available.","exampleCN":"总而言之，这个方案虽然昂贵，仍是现有选项中最便宜的。","why":"The verb becomes a signpost: the speaker announces that the box is about to close, so the audience knows no further points are coming.","whyCN":"这个动词变成了路标：说话人宣布盒子即将合上，听众因此知道不会再有新的要点了。"},{"no":"09","title":"Archaic: to enclose or shut in","titleCN":"古义：围住、关闭","definition":"in older usage, to shut something in or surround it with a boundary","definitionCN":"在较早用法中，指把某物关在里面或用边界围住","example":"The old walls concluded the garden on three sides.","exampleCN":"旧墙从三面围住了花园。","why":"This is the original physical sense of claudere 'to shut'. Every later meaning — ending, inferring, settling — is a closing of some kind.","whyCN":"这是 claudere“关闭”最原始的物理义。后来的一切含义——结束、推断、议定——都是一种“关闭”。"}],"etymology":{"intro":{"en":"Conclude is built on a Latin verb for shutting, and its many meanings are all versions of closing something: an argument, an inquiry, a bargain, a speech, or a space.","cn":"conclude 建立在一个表示“关闭”的拉丁动词上，它的众多含义都是“关掉某物”的变体：争论、探究、交易、讲话或一片空间。"},"items":[{"era":"EARLY 14C.","en":"First recorded in English with the sense 'to end an argument by winning it'. Victory, not neutrality, was the earliest kind of closing.","cn":"英语中最早记录于 14 世纪早期，意为“辩赢对手、使争论收场”。最早的“关闭”是胜利，而不是中立收场。"},{"era":"LATIN concludere","en":"Latin concludere meant 'to shut up, enclose': com- 'together' plus claudere 'to shut', from PIE *klau- 'hook, peg, nail, lock'.","cn":"拉丁语 concludere 意为“关闭、围住”：com-“一起”加 claudere“关上”，可追溯到原始印欧语 *klau-“钩、钉、锁”。"},{"era":"LATE 14C.","en":"Two further senses appeared: 'to infer, deduce' and 'to bring to an end'. Reasoning and finishing were both pictured as closing.","cn":"又出现两个义项：“推断、演绎”和“使结束”。推理与收尾都被想象成“关闭”。"},{"era":"EARLY 15C.","en":"The sense 'to settle, arrange' is recorded, which leads to concluding a treaty or a deal.","cn":"记录到“议定、安排”的义项，由此发展出“缔结条约或交易”的用法。"},{"era":"LATE 14C. · conclusion","en":"The noun conclusion is recorded from the late 14th century, built on the same Latin stem. Conclusive and inconclusive follow from it.","cn":"名词 conclusion 从 14 世纪后期起有记录，建立在同一拉丁词干上。conclusive 与 inconclusive 由它而来。"},{"era":"RELATED FAMILY","en":"Include, exclude, preclude, seclude, close, closure and clause all belong to the claudere family: each one shuts something in, out, or off.","cn":"include、exclude、preclude、seclude、close、closure、clause 都属于 claudere 词族：每一个都在把某物关进、关出或关掉。"}]},"similar":{"note":{"en":"The first group is the claudere family, where the same 'shut' image produces very different words; the second group compares ways of ending and of reasoning to a judgment.","cn":"第一组是 claudere 词族，同一个“关闭”意象造出了很不一样的词；第二组比较“结束”与“推理得出判断”的不同说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conclusion","ipa":"/kənˈkluːʒn/","tag":"same verb, noun","definition":"the judgment reached, or the ending of something. It is the noun of conclude, naming the closed result rather than the act.","definitionCN":"所达到的判断，或某事的结尾。它是 conclude 的名词，命名的是被关上的结果，而不是动作。"},{"word":"include","ipa":"/ɪnˈkluːd/","tag":"claudere family, inward","definition":"to shut something inside a group or boundary. It shares Latin claudere 'to shut' with conclude, but the prefix in- points inward rather than to a finished end.","definitionCN":"把某物关进一个群体或边界之内。它与 conclude 共享拉丁语 claudere“关闭”，但前缀 in- 指向内部，而不是指向终点。"},{"word":"exclude","ipa":"/ɪkˈskluːd/","tag":"claudere family, outward","definition":"to shut someone or something out. The same claudere root appears with ex- 'out', the mirror image of include and a distant cousin of conclude.","definitionCN":"把某人或某物关在外面。同一 claudere 词根加上 ex-“向外”，是 include 的镜像，也是 conclude 的远亲。"}]},{"heading":"NEAR MEANING","entries":[{"word":"infer","ipa":"/ɪnˈfɜː/","tag":"reason from evidence","definition":"to reach an opinion from evidence rather than from direct statement. Infer names the movement of reasoning; conclude names the endpoint where reasoning closes.","definitionCN":"根据证据而非直接陈述得出看法。infer 强调推理的过程，conclude 强调推理收口的那一端。"},{"word":"deduce","ipa":"/dɪˈdjuːs/","tag":"strict logical derivation","definition":"to derive a conclusion logically from premises. It is narrower and more formal than conclude, which also covers judgments and endings.","definitionCN":"从前提按逻辑推出结论。它比 conclude 更窄、更正式；conclude 还包含判断与结束等义。"},{"word":"finish","ipa":"/ˈfɪnɪʃ/","tag":"reach the end","definition":"to bring or come to the end of an activity. Finish is general and physical; conclude sounds more formal and often implies closing a discussion or arrangement.","definitionCN":"把活动带到终点或自行结束。finish 一般而具体；conclude 更正式，常暗示关闭一场讨论或一项安排。"},{"word":"end","ipa":"/end/","tag":"plain termination","definition":"to stop or terminate. End is the plainest word of the group and carries no hint of reasoning or formal settlement.","definitionCN":"停止、终止。end 是这组里最朴素的词，不含推理或正式议定的意味。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: con- 'together', claudere 'to shut', and the large family include / exclude / close / clause.","cn":"只用真实构词成分与真实同族词：con-“一起”、claudere“关闭”，以及 include／exclude／close／clause 这一大家子。"},"normal":[{"en":"con- means 'together' and claudere means 'to shut'. To conclude is to shut everything together into one closed space.","cn":"con- 表示“一起”，claudere 表示“关闭”。conclude 就是把一切关进同一个封闭空间。"},{"en":"Conclusion is the closed result, conclusive means able to settle the matter, and inconclusive means the lid will not shut.","cn":"conclusion 是被关上的结果，conclusive 表示足以定论，inconclusive 表示盖子合不上。"},{"en":"The claudere family is easy to hear once you know it: include shuts in, exclude shuts out, preclude shuts before, seclude shuts apart, close and clause are the plain relatives.","cn":"认识 claudere 之后，这个词族很容易听出来：include 关进，exclude 关出，preclude 提前关掉，seclude 关到一旁，close 与 clause 是朴素亲戚。"},{"en":"The earliest sense was 'end an argument by winning it', so a conclusion originally had a victor.","cn":"最早的义项是“辩赢、使争论收场”，所以 conclusion 最初是有胜利者的。"},{"en":"To conclude is a signpost: it tells the listener that the lid is about to close and no new point will follow.","cn":"to conclude 是一个路标：它告诉听者盖子即将合上，不会再有新要点了。"}],"abstract":[{"en":"Picture a wooden box full of loose papers. Conclude is the hand pressing the lid down until the papers can no longer move.","cn":"想象一只木箱，里面全是散乱的纸。conclude 就是一只手把盖子压下去，直到纸再也动不了。"},{"en":"The box can hold an argument, a set of clues, a negotiation, a speech, or a garden. Whatever it holds, the word means the same: the boundary is now closed.","cn":"这只箱子可以装一场争论、一组线索、一次谈判、一篇讲话，也可以围住一座花园。不论装什么，词义都一样：边界现在合上了。"},{"en":"A conclusion is not merely the last thing said; it is the point after which the matter is shut and cannot be reopened without force.","cn":"结论不只是最后说出的那句话；它是事情被关上、不费力就无法重新打开的那一点。"}]},"examples":[{"en":"The report concludes that the bridge should be closed for repairs.","cn":"报告得出结论：这座桥应关闭维修。"},{"en":"The negotiations concluded with an agreement that satisfied neither side completely.","cn":"谈判以一项双方都不完全满意的协议告终。"},{"en":"To conclude, the evidence supports the original claim but leaves one question open.","cn":"总而言之，证据支持最初的论断，但仍留下一个问题未决。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“肯克路德”——肯（con）把争论一路克（c）到终点，路德（de）最后关上盒子，得出结论 → conclude 结束、得出结论","word":"conclude"},"root":"源自拉丁语 concludere“关闭、围住”，由 com-“一起”+ claudere“关上”构成，核心是“把话头或事务关进盒子并封口”。","sensesIntro":{"en":"Nine senses of conclude, all grown from one act: something open — an argument, an inquiry, a bargain, a speech, a space — is shut inside a boundary and cannot continue.","cn":"conclude 的九个义项都从同一个动作长出来：某个敞开的东西——争论、探究、交易、讲话、空间——被关进一条边界里，不能再继续。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lid closes over an open matter.","cn":"核心意象：盖子合上，把敞开的事情关在里面。"},"chain":["AN OPEN MATTER","SHUT IT IN","ARGUMENT CLOSED","JUDGMENT REACHED","TERMS SETTLED","END REACHED"],"branches":[{"senses":"S1 · S6","en":"ENDING: someone closes a meeting, or an event closes itself, and nothing is left open.","cn":"结束：有人把会议关上，或事件自行合拢，不留任何敞开之处。"},{"senses":"S2 · S3","en":"JUDGMENT: evidence is reasoned through until it is shut into one conclusion or verdict.","cn":"判断：证据被一路推理，直到被关进同一个结论或裁决。"},{"senses":"S4","en":"SETTLEMENT: negotiation ends when the terms are sealed inside a final agreement.","cn":"议定：条款被封进最终协议时，谈判结束。"},{"senses":"S5 · S8","en":"CLOSING THE DEBATE: in older use the opponent is shut out; in modern speech 'to conclude' announces the final point.","cn":"收束辩论：较早用法把对手关在门外；现代说法 to conclude 则宣告最后一个要点。"},{"senses":"S7 · S9","en":"BOUNDARY: the last item completes the edge of a speech, and the oldest sense simply means to shut a space in.","cn":"边界：最后一项补全讲话的边缘；最古老的义项就是单纯把一片空间围住。"}]},"affixes":{"intro":{"en":"Conclude is a Latin verb borrowed whole: con- 'together' plus claudere 'to shut'. English then adds -ion, -ive, -ly and in-, and shares the same root with a large family of everyday words.","cn":"conclude 是整体借入的拉丁动词：con-“一起”加 claudere“关闭”。英语随后加上 -ion、-ive、-ly 和 in-，并与一大群日常词共享同一词根。"},"latinIntro":{"en":"The Latin family is built on claudere 'to shut': concludere closes together, includere shuts in, excludere shuts out, and claustrum gives English cloister and closet.","cn":"这一拉丁词族建立在 claudere“关闭”上：concludere 关在一起，includere 关进，excludere 关出；claustrum 则给出英语的 cloister 与 closet。"},"items":[{"word":"conclusion","structure":"concludere + -ion (action or result noun)","meaning":"a judgment reached; the ending or settlement of something","meaningCN":"结论；结尾；缔结（-ion 构成行为或结果名词）","example":"The conclusion of the study surprised the researchers.","exampleCN":"这项研究的结论让研究者们感到意外。"},{"word":"conclusive","structure":"conclus- + -ive (adjective)","meaning":"decisive, able to settle a matter","meaningCN":"决定性的；足以定论的（-ive 构成形容词）","example":"The fingerprint was conclusive evidence of his presence.","exampleCN":"那枚指纹是他曾在场的决定性证据。"},{"word":"conclusively","structure":"conclusive + -ly (adverb)","meaning":"in a way that settles the matter","meaningCN":"决定性地；确凿地","example":"The test conclusively ruled out infection.","exampleCN":"这项检测确凿地排除了感染。"},{"word":"inconclusive","structure":"in- (not) + conclusive","meaning":"not able to settle a question","meaningCN":"无定论的；不足以定论的（in- 表示否定）","example":"The talks ended inconclusive after two days.","exampleCN":"会谈持续两天，仍无定论。"},{"word":"conclusiveness","structure":"conclusive + -ness (quality noun)","meaning":"the quality of being decisive","meaningCN":"决定性；确凿性","example":"The conclusiveness of the data convinced the board.","exampleCN":"数据的确定性说服了董事会。"},{"word":"include","structure":"in- (in) + claudere (shut)","meaning":"to shut something inside a group or boundary","meaningCN":"包括；把……关在里面（in- “向内”加“关闭”）","example":"The price includes breakfast and parking.","exampleCN":"价格包含早餐和停车。"},{"word":"exclude","structure":"ex- (out) + claudere (shut)","meaning":"to shut someone or something out","meaningCN":"排除；把……关在外面","example":"The rule excludes students who miss the deadline.","exampleCN":"这条规则把错过截止日期的学生排除在外。"},{"word":"preclude","structure":"prae- (before) + claudere (shut)","meaning":"to shut something off in advance; to prevent","meaningCN":"预先排除；阻止","example":"The injury precluded any chance of playing.","exampleCN":"这次受伤使他完全失去了上场的可能。"},{"word":"seclude","structure":"se- (apart) + claudere (shut)","meaning":"to shut someone apart from others","meaningCN":"使隔离；使隐居","example":"The family secluded itself in a house by the sea.","exampleCN":"这家人隐居在海边的一栋房子里。"},{"word":"close","structure":"claudere, through Old French clos","meaning":"to shut; the end of something","meaningCN":"关闭；结束（经法语来自同一词根）","example":"Please close the window before you leave.","exampleCN":"离开前请把窗户关上。"},{"word":"closure","structure":"clos- + -ure (noun of result)","meaning":"the act of closing; a sense of resolution","meaningCN":"关闭；了结；心理上的收束感","example":"The ceremony gave the family a sense of closure.","exampleCN":"这场仪式给这个家庭带来了一种了结感。"},{"word":"clause","structure":"claudere + -a, through Medieval Latin clausa","meaning":"a closed unit of a sentence or a contract","meaningCN":"从句；（合同的）条款——一个被围起来的单位","example":"The third clause allows either party to end the deal.","exampleCN":"第三条条款允许任何一方终止交易。"}],"latinEntries":[{"word":"concludere","structure":"com- (together) + claudere (shut)","meaning":"to shut up, enclose; to bring to an end","meaningCN":"关闭；围住；使结束"},{"word":"claudere","structure":"PIE *klau- 'hook, peg, nail, lock'","meaning":"to shut, close","meaningCN":"关上；关闭"},{"word":"conclusio","structure":"concludere + -io (action noun)","meaning":"a closing; an inference; an ending","meaningCN":"关闭；推论；结尾"}]}},{"word":"concrete","ipa_uk":"/ˈkɒŋkriːt/","ipa_us":"/ˈkɑːnkriːt/","definition_zh":"具体的；有形的；实在的；混凝土（的）","definition_en":"existing as a particular physical thing that can be seen or touched, rather than as an idea or a general category; also the hard building material made from cement, sand, gravel and water","core_image":"一堆松散的砂石与水，慢慢凝结成一整块可以敲响的硬石头","scene":"The architect poured concrete over a steel frame and watched a drawing on paper become a wall you could knock on.","sceneCN":"这里 concrete 是「混凝土」（第 5 个义项：由水泥、砂、石与水拌合后凝固的建筑材料）；句意：建筑师把混凝土浇在钢架上，眼看着纸上的图变成一堵能敲出声的墙。场景要点：流动的浆体在模板里逐渐变硬、定型，最后成为实体。","pos":[{"tag":"adj.","zh":"具体的；有形的；确实的；混凝土制的"},{"tag":"n.","zh":"混凝土；（哲学中的）具体之物"}],"collocations":[{"phrase":"concrete evidence","zh":"确凿的证据；具体证据"},{"phrase":"a concrete example","zh":"具体的例子"},{"phrase":"concrete proposals","zh":"具体方案"},{"phrase":"reinforced concrete","zh":"钢筋混凝土"},{"phrase":"poured concrete","zh":"浇筑混凝土"},{"phrase":"set in concrete","zh":"（喻）板上钉钉、不可更改"}],"forms":[{"label":"比较级（多音节形容词用 more 构成）","form":"more concrete"},{"label":"复数（名词）","form":"concretes"}],"derivatives":[{"word":"concretely","pos":"adv.","zh":"具体地；有形地"},{"word":"concreteness","pos":"n.","zh":"具体性；有形性"},{"word":"concretion","pos":"n.","zh":"凝结；凝固物；结石"},{"word":"concretize","pos":"v.","zh":"使具体化；使成形"},{"word":"concretization","pos":"n.","zh":"具体化；落实为实体"},{"word":"abstract","pos":"adj./n.","zh":"抽象的；抽象概念（逻辑上的对立词）"}],"senses":[{"no":"01","title":"Hardened into one mass","titleCN":"凝成一块：从松散到坚硬","definition":"formed into a single solid mass by growing or setting together, instead of staying loose, soft or fluid","definitionCN":"通过一起生长或凝结而成为一个坚硬的整体，而不是保持松散、柔软或流动状态","example":"The lava had cooled into a concrete sheet of black rock along the slope.","exampleCN":"熔岩冷却后，在山坡上凝成了一整片黑色的岩板。","why":"Latin concrescere is com- 'together' plus crescere 'to grow'. The parts grow into one another until nothing separate is left, which is the physical picture the word still carries.","whyCN":"拉丁语 concrescere 是 com-“一起”加 crescere“生长”。各部分相互长进去，直到不再有分开的部分，这就是这个词至今携带的物理画面。"},{"no":"02","title":"Particular, not general","titleCN":"指个别：不是笼统类别","definition":"referring to one identifiable thing or instance rather than to a whole class or a general idea","definitionCN":"指向某一个可辨认的事物或实例，而不是指向整个类别或一般观念","example":"Instead of saying 'fruit', give me a concrete example: a peach, a pear, or a plum.","exampleCN":"别说“水果”，给我一个具体的例子：一个桃子、一只梨或一颗李子。","why":"A particular thing is something you can put your hand on. The image moves from a hardened mass to a single object that can be singled out and named.","whyCN":"个别的事物是你能伸手摸到的东西。意象从“凝成的块体”转到“可以被单独指出、单独命名的一个对象”。"},{"no":"03","title":"Definite enough to act on","titleCN":"明确可执行：能落地","definition":"expressed so clearly and precisely that it can be carried out, measured or checked","definitionCN":"表达得足够清楚、精确，可以被执行、被衡量或被核对","example":"The plan was concrete: three buses, a six o'clock start, and a printed list of stops.","exampleCN":"方案很具体：三辆巴士、六点出发，还有一份印好的停靠站清单。","why":"When a proposal 'sets', it is no longer a puddle of possibilities but a shape with edges. Definiteness is the mental version of that cured surface.","whyCN":"当方案“凝固”，它就不再是一摊可能性，而是一个有边界的形状。所谓明确，就是这种硬化表面在思维层面的版本。"},{"no":"04","title":"Backed by facts","titleCN":"有事实支撑：可核验","definition":"supported by real, checkable evidence rather than by opinion, guess or impression","definitionCN":"由真实的、可核查的证据支撑，而不是由看法、猜测或印象支撑","example":"The inquiry demanded concrete proof that the chemical had reached the river.","exampleCN":"调查组要求拿出确凿证据，证明那种化学品确实进入了河流。","why":"Proof is what you can stand on. The contrast with abstract reasoning is the same contrast as stone against vapour: one holds weight, the other drifts.","whyCN":"证据是你站得上去的东西。它与抽象推理的对立，就像石头与水汽的对立：一个承重，一个飘散。"},{"no":"05","title":"The building material","titleCN":"混凝土：拌合后凝固的石材","definition":"a building material made by mixing cement, sand, gravel and water, which sets into a hard stone-like mass","definitionCN":"把水泥、砂、碎石与水拌合，凝固成坚硬如石的材料","example":"The bridge deck was poured in concrete and left to cure under wet cloth for a week.","exampleCN":"桥面用混凝土浇筑，盖上湿布养护了一周。","why":"The material is named by the very process the Latin verb described: separate ingredients are brought together and grow into one artificial rock.","whyCN":"这种材料正是用那个拉丁动词描述的过程来命名的：分开的配料被聚到一起，长成一块人造的岩石。"},{"no":"06","title":"The material particular in philosophy","titleCN":"哲学：存在的具体个别物","definition":"in philosophy, a particular existing thing in the material world, as opposed to an abstract concept or a universal","definitionCN":"哲学中指物质世界中存在的个别事物，与抽象概念或共相相对","example":"The seminar argued over whether numbers are concrete objects or only abstract entities.","exampleCN":"研讨课上争论不休：数字究竟是具体对象，还是只是抽象实体。","why":"The 1520s noun meant 'that which is material or not abstract'. Philosophy kept that plain opposition and made it a technical label for particulars.","whyCN":"16 世纪 20 年代的名词义是“物质性的、非抽象的东西”。哲学沿用这一朴素对立，把它变成指称“个别物”的术语。"},{"no":"07","title":"Grammar: a concrete noun","titleCN":"语法：具体名词","definition":"in grammar, a noun naming something that can be perceived by the senses, such as a table, a dog or a bell","definitionCN":"语法中指命名可被感官感知之物的名词，如桌子、狗、铃铛","example":"Chair is a concrete noun; freedom is an abstract one, and the two behave differently in some tests.","exampleCN":"chair 是具体名词，freedom 是抽象名词，两者在某些测试中表现不同。","why":"Grammar borrowed the philosophical split and applied it to single words: a noun is concrete when its referent can be met in the world.","whyCN":"语法学借用了哲学上的二分，并把它用到单个词上：当一个名词所指之物能在现实中被遇见，它就是具体名词。"},{"no":"08","title":"Set in concrete: beyond change","titleCN":"浇筑定型：板上钉钉","definition":"fixed so firmly that changing it would mean breaking something apart","definitionCN":"固定得如此牢固，要改动就等于把东西砸开","example":"The timetable was set in concrete long before anyone asked the teachers.","exampleCN":"课程表早在有人征求教师意见之前就已经板上钉钉了。","why":"Cured concrete cannot be reshaped; it can only be demolished. The idiom borrows that permanence for rules, plans and decisions.","whyCN":"养护好的混凝土无法重新塑形，只能被拆除。这个习语把这分永久性借给了规则、计划和决定。"},{"no":"09","title":"Concrete music: sound treated as material","titleCN":"具体音乐：把声响当作实物","definition":"in music, describing pieces built from recorded everyday sounds used as raw material instead of composed notes","definitionCN":"在音乐中，指用录下的日常声响作为原材料、而非谱写音符来构建作品","example":"The composer made a concrete piece out of train brakes, rain and a door slamming.","exampleCN":"那位作曲家拿列车刹车声、雨声和一记关门声做了一首具体音乐作品。","why":"Musique concrète took sounds as given objects, solid chunks of the audible world, rather than as symbols on a staff. The word's 'thing-ness' is the point.","whyCN":"具体音乐把声音当作给定的实物，是可听世界的一块块硬料，而不是谱表上的符号。这个词的“物性”正是要点。"}],"etymology":{"intro":{"en":"Concrete is a Latin word that arrived almost intact: com- 'together' plus crescere 'to grow'. Its history runs from 'grown together' to 'solid thing' to 'building material'.","cn":"concrete 是一个几乎原样借入的拉丁词：com-“一起”加 crescere“生长”。它的历史从“长在一起”走到“固体之物”，再到“建筑材料”。"},"items":[{"era":"LATE 14C.","en":"First recorded as an adjective meaning 'actual, solid; particular; denoting a substance'. The opposite abstract was already waiting in the same scholarly vocabulary.","cn":"最早作为形容词记录于 14 世纪晚期，意为“实际的、固体的；个别的；指称实体的”。它的反义词 abstract 已等在同一个学术词汇表里。"},{"era":"LATIN concrescere","en":"The source is concrescere 'to grow together, harden, condense': com- 'together' plus crescere 'to grow, increase'. The image is separate parts growing into one body.","cn":"来源是 concrescere“一起生长、变硬、凝结”：com-“一起”加 crescere“生长、增加”。画面是分开的部分长成一个整体。"},{"era":"LATIN concretus","en":"Concretus, the past participle, meant 'condensed, hardened, grown together'. Latin already used it for material things as opposed to abstract ones, and English took both branches at once.","cn":"过去分词 concretus 意为“凝结的、变硬的、长在一起的”。拉丁语已用它指物质性的东西，与抽象相对；英语把两条分支一起借了进来。"},{"era":"PROTO-INDO-EUROPEAN","en":"Crescere goes back to PIE *ker- (2) 'to grow'. The same reconstructed root feeds crescent, increase, decrease and accretion.","cn":"crescere 可追溯到原始印欧语 *ker- (2)“生长”。同一重构词根也给出 crescent、increase、decrease、accretion。"},{"era":"1520S","en":"The noun appears, meaning 'that which is material or not abstract'. For two centuries the noun lives mainly in philosophy and logic, not on building sites.","cn":"名词出现，意为“物质性的、非抽象的东西”。此后两个世纪，这个名词主要活在哲学与逻辑里，而不是出现在工地上。"},{"era":"1834 · MODERN","en":"The building material is recorded under this name in the 1830s, after Portland cement made strong poured walls practical. Modern English keeps the old opposition with abstract and adds extensions such as reinforced concrete and concrete music.","cn":"19 世纪 30 年代，这种建筑材料以该名被记录下来，此前波特兰水泥已使坚固的浇筑墙体成为可能。现代英语保留了与 abstract 的古老对立，并扩展出钢筋混凝土、具体音乐等说法。"}]},"similar":{"note":{"en":"The first group separates look-alikes and the related material word cement; the second group collects adjectives that also mean 'not vague', each with a different centre of gravity.","cn":"第一组区分形近词以及相关的材料词 cement；第二组收集同样表示“不含糊”的形容词，但每个词的着力点不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"abstract","ipa":"/ˈæbstrækt/","tag":"antonym in logic","definition":"existing as an idea or quality rather than a physical thing. It is the logical opposite of concrete, built from abs- 'away' plus trahere 'to draw': meaning drawn away from the object.","definitionCN":"作为观念或性质而存在，而非作为实物存在。它是 concrete 在逻辑上的对立词，由 abs-“离开”加 trahere“抽、拉”构成：意思是从具体对象上抽离出来。"},{"word":"concretion","ipa":"/kənˈkriːʃn/","tag":"same root, noun","definition":"a rounded mass formed when particles are pressed or cemented together, as in geology or medicine. It names the product of growing together, not the quality of being specific.","definitionCN":"颗粒被压紧或胶结而成的团块，见于地质学或医学。它命名的是“长在一起”的产物，而不是“具体”这一性质。"},{"word":"concretely","ipa":"/kənˈkriːtli/","tag":"adverb form","definition":"in a specific, tangible or practical way. It is simply the adverb of concrete, not a separate root.","definitionCN":"以具体的、有形的方式。它只是 concrete 的副词形式，不是另一个词根。"},{"word":"cement","ipa":"/sɪˈment/","tag":"not a synonym","definition":"a fine grey powder that hardens when mixed with water and binds sand and gravel together. Cement is one ingredient; concrete is the finished mixture of cement, sand, gravel and water.","definitionCN":"一种灰色细粉，遇水硬化，把砂和碎石胶结起来。cement 是配料之一（水泥）；concrete 是水泥、砂、碎石与水拌合后的成品（混凝土）。两者不能互换。"}]},{"heading":"NEAR MEANING","entries":[{"word":"specific","ipa":"/spəˈsɪfɪk/","tag":"one identifiable item","definition":"clearly naming one particular thing rather than a broad class. It shares the 'not general' sense of concrete but says nothing about physical solidity.","definitionCN":"清楚地指出某一个特定事物，而不是宽泛的类别。它共享 concrete 的“非笼统”义，但不涉及物理上的固体性。"},{"word":"tangible","ipa":"/ˈtændʒəbl/","tag":"can be touched","definition":"able to be touched or clearly perceived, and often used of benefits and assets that can be measured. It stresses perceptibility rather than the absence of abstraction.","definitionCN":"能被触摸或清晰感知，常用于可衡量的利益与资产。它强调可感知性，而不是“非抽象”。"},{"word":"solid","ipa":"/ˈsɒlɪd/","tag":"physical firmness","definition":"firm and stable in shape, not liquid or hollow. Solid describes the state of matter or a structure; concrete also carries the logical sense of 'particular'.","definitionCN":"形状坚实稳定，不是液体或空心的。solid 描述物态或结构；concrete 还带有“个别、非抽象”的逻辑义。"},{"word":"palpable","ipa":"/ˈpælpəbl/","tag":"strong enough to be felt","definition":"so strong or obvious that it can almost be felt, often used of emotions, tension or evidence. It is more figurative and less technical than concrete.","definitionCN":"强烈或明显到几乎能被感觉到，常用于情绪、紧张气氛或证据。它比 concrete 更偏比喻、更少术语味。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: com- 'together', crescere 'grow', the noun concretion, and the logical pair concrete / abstract.","cn":"只用真实成分与真实同族词：com-“一起”、crescere“生长”、名词 concretion，以及逻辑上的成对概念 concrete／abstract。"},"normal":[{"en":"con- means 'together' and crescere means 'grow'. Concrete is what happens when separate parts grow into one solid body.","cn":"con- 是“一起”，crescere 是“生长”。concrete 就是分开的部分长成一个坚固整体的结果。"},{"en":"The same root gives increase and decrease: crescere is simply 'to grow', and con- adds the direction 'into one another'.","cn":"同一词根还给出 increase 与 decrease：crescere 就是“生长”，con- 只是加上“彼此长进去”的方向。"},{"en":"Concrete and abstract are a matched pair from logic: one points to a thing you can meet, the other to a meaning drawn away from things.","cn":"concrete 与 abstract 是逻辑学里的一对：一个指向你能遇见的具体事物，一个指向从事物上抽离出来的意义。"},{"en":"Concretion is the geological cousin: sand grains cemented into a rounded lump. Same process, different scale.","cn":"concretion 是地质学上的表亲：砂粒胶结成圆块。同一个过程，只是尺度不同。"},{"en":"Cement is not concrete. Cement is the powder that binds; concrete is cement plus sand, gravel and water after it cures.","cn":"cement 不是 concrete。水泥是起胶结作用的粉末；混凝土是水泥加砂、碎石和水并养护硬化后的成品。"}],"abstract":[{"en":"Picture a wet heap of sand and gravel. Add water, wait, and it locks into a slab you can stand on. That lock is the whole word.","cn":"想象一堆湿的砂与碎石。加水、等待，它锁成一块你能站上去的板。这个“锁住”的动作就是这个词的全部。"},{"en":"The slab then turns into an argument: a concrete example, concrete evidence, a concrete plan. Each is a piece of reality you can hand to someone.","cn":"这块板随后变成一个论证里的东西：具体的例子、确凿的证据、可执行的方案。每一样都是你能递到别人手里的现实碎片。"},{"en":"Push the image the other way and you get the idiom set in concrete: once cured, the shape can only be broken, not edited.","cn":"把意象往另一边推，就得到 set in concrete 这个说法：一旦养护完成，形状只能被砸开，不能被编辑。"}]},"examples":[{"en":"Give me something concrete: a date, a name and a number I can check.","cn":"给我点具体的东西：一个日期、一个名字、一个我能核对的数字。"},{"en":"The path was paved in concrete, and the heat coming off it at noon was unbearable.","cn":"小路是混凝土铺的，正午从地面升起来的热气让人受不了。"},{"en":"Her criticism was concrete rather than abstract, pointing to the second paragraph and the missing source.","cn":"她的批评很具体，不空泛，直接指向第二段和缺失的出处。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“肯快砌”——肯快地砌起来的那堵墙，用的正是混凝土 → concrete 混凝土；具体的","word":"concrete"},"root":"源自拉丁语 concrescere“一起生长、凝结”，由 com-“一起”+ crescere“生长”构成，核心是“散料长成一块坚硬的整体”。","sensesIntro":{"en":"Nine senses of concrete, all grown from one event: loose parts set into a single hard mass. From that mass come the physical object, the particular example, the checkable fact, the building material and even the cured, unchangeable plan.","cn":"concrete 的九个义项都从同一个事件长出来：松散的部分凝固成一个坚硬的整体。由这块整体衍生出实物、个别例子、可核验的事实、建筑材料，乃至已经定型、无法更改的计划。"},"semanticMap":{"core":{"en":"CORE IMAGE: loose parts grow together and set into one hard mass.","cn":"核心意象：松散的部分长在一起，凝固成一整块硬物。"},"chain":["GROW TOGETHER","HARDEN INTO ONE MASS","A PHYSICAL THING","A PARTICULAR INSTANCE","DEFINITE AND CHECKABLE","FIXED BEYOND CHANGE"],"branches":[{"senses":"S1 · S5","en":"MATTER: a hardened mass, and the building material that is named after the very process of setting.","cn":"物质：凝成的硬块，以及因“凝固”这一过程而得名的建筑材料。"},{"senses":"S2 · S3","en":"PRECISION: a single instance you can point to, and a plan with edges sharp enough to execute.","cn":"精确：一个能被指出的个别实例，以及一个边界清晰到可以执行的方案。"},{"senses":"S4","en":"PROOF: evidence with weight, standing against opinion the way stone stands against vapour.","cn":"证据：有分量的凭据，像石头对水汽一样对立于空口看法。"},{"senses":"S6 · S7","en":"CLASSIFICATION: the philosophical particular and the grammatical noun whose referent can be met.","cn":"归类：哲学上的个别物，以及所指之物能被遇见的语法具体名词。"},{"senses":"S8 · S9","en":"EXTENSIONS: a plan cured past editing, and recorded sound treated as solid raw material.","cn":"延伸：养护完成、无法再改的计划，以及被当作固体原料的录音声响。"}]},"affixes":{"intro":{"en":"Concrete is built from a live Latin prefix and a live Latin verb: con- 'together' plus crescere 'grow', with the past-participle ending -tus. English then adds only ordinary suffixes.","cn":"concrete 由两个仍然可读的拉丁成分构成：con-“一起”加 crescere“生长”，再加过去分词词尾 -tus。英语随后只加普通后缀。"},"latinIntro":{"en":"The Latin family runs from crescere 'to grow' through concrescere 'to grow together' to concretus 'hardened'. The same crescere also yields increase, decrease, crescent and accretion, so the root is unusually well populated.","cn":"这一拉丁词族从 crescere“生长”经 concrescere“一起生长”到 concretus“变硬的”。同一个 crescere 还给出 increase、decrease、crescent 与 accretion，因此这个词根的同族词格外多。"},"items":[{"word":"concretely","structure":"concrete + -ly (adverb)","meaning":"in a specific, tangible way","meaningCN":"具体地；有形地（-ly 构成副词）","example":"She described the problem concretely, with times and costs.","exampleCN":"她具体地描述了问题，带上了时间和成本。"},{"word":"concreteness","structure":"concrete + -ness (quality noun)","meaning":"the quality of being specific and tangible","meaningCN":"具体性；有形性（-ness 构成性质名词）","example":"The concreteness of the examples made the lecture easy to follow.","exampleCN":"例子具体，让讲座很容易跟上。"},{"word":"concretion","structure":"concret(us) + -ion (result noun)","meaning":"a mass formed by hardening or compaction","meaningCN":"凝结物；凝固而成的团块（-ion 构成结果名词）","example":"Geologists found small concretions of iron inside the sandstone.","exampleCN":"地质学家在砂岩里发现了小的铁质结核。"},{"word":"concretize","structure":"concret(e) + -ize (verb)","meaning":"to make an idea concrete or definite","meaningCN":"使具体化；把观念落实（-ize 构成动词）","example":"The team concretized the vision into a two-year budget.","exampleCN":"团队把愿景具体化为一份两年预算。"},{"word":"concretization","structure":"concretize + -ation (process noun)","meaning":"the act of giving an idea a definite form","meaningCN":"具体化；落实为实体的过程","example":"The concretization of the policy took three drafts.","exampleCN":"政策的具体化经过了三稿。"},{"word":"increase","structure":"in- (into) + crescere (grow)","meaning":"to become larger or more numerous","meaningCN":"增加；增长（in- 向内 + crescere 生长）","example":"Demand for the service increased sharply last year.","exampleCN":"去年对这项服务的需求急剧增加。"},{"word":"decrease","structure":"de- (down) + crescere (grow)","meaning":"to become smaller or fewer","meaningCN":"减少；下降（de- 向下 + crescere 生长）","example":"Rainfall decreased across the region for a decade.","exampleCN":"该地区的降雨量连续十年减少。"},{"word":"crescent","structure":"cresc(ere) + -ent (growing)","meaning":"the shape of a moon that is growing","meaningCN":"新月；月牙（字面为“正在生长的月”）","example":"A thin crescent hung above the harbour.","exampleCN":"一弯细月挂在港口上方。"},{"word":"accretion","structure":"ac- (to) + crescere (grow) + -ion","meaning":"growth by gradual addition of layers","meaningCN":"增生；堆积增长（一层层添上去的生长）","example":"The reef grows by the accretion of coral skeletons.","exampleCN":"珊瑚礁靠珊瑚骨骼的堆积而生长。"},{"word":"excrescence","structure":"ex- (out) + crescere (grow) + -ence","meaning":"an abnormal growth outward","meaningCN":"向外长出的赘生物；多余物","example":"The tree developed a woody excrescence near its base.","exampleCN":"树的基部生出了一个木质赘瘤。"}],"latinEntries":[{"word":"crescere","structure":"PIE *ker- (2) 'grow' + Latin verb stem","meaning":"to grow, increase, come into being","meaningCN":"生长；增加；生成"},{"word":"concrescere","structure":"con- (together) + crescere (grow)","meaning":"to grow together, harden, condense","meaningCN":"一起生长；变硬；凝结"},{"word":"concretus","structure":"concrescere + -tus (past participle)","meaning":"grown together, condensed, hardened","meaningCN":"长在一起的；凝结的；变硬的"}]}},{"word":"conduct","ipa_uk":"/kənˈdʌkt/","ipa_us":"/kənˈdʌkt/","definition_zh":"实施；进行；引导；指挥；传导；（名词）行为、举止","definition_en":"to lead or guide someone along a way, to carry out an activity, to direct a group or an orchestra, or to allow heat or electricity to pass through; as a noun, the way a person behaves","core_image":"一个人走在最前面，后面的人依次跟上，一路被带到终点","scene":"She conducted the experiment with such care that the whole lab followed her lead without a word.","sceneCN":"这里 conduct 是「实施、进行」（第 2 个义项：主持并完成一项活动）；句意：她做实验时极其细致，整个实验室一言不发地跟着她的节奏走。场景要点：一个人走在最前面，后面的人按她的步骤一步步跟上，直到整件事被带完。","pos":[{"tag":"v.","zh":"实施；进行；引导；指挥；传导"},{"tag":"n.","zh":"行为；举止；（事务的）处理、管理"}],"collocations":[{"phrase":"conduct an experiment","zh":"进行实验"},{"phrase":"conduct a survey","zh":"开展调查"},{"phrase":"conduct oneself","zh":"举止表现；为人行事"},{"phrase":"conduct electricity","zh":"导电"},{"phrase":"a code of conduct","zh":"行为准则"},{"phrase":"the conduct of the negotiations","zh":"谈判的进行与管理"}],"forms":[{"label":"第三人称单数","form":"conducts"},{"label":"过去式","form":"conducted"},{"label":"过去分词","form":"conducted"},{"label":"现在分词","form":"conducting"}],"derivatives":[{"word":"conductor","pos":"n.","zh":"指挥；导体；列车员"},{"word":"conduction","pos":"n.","zh":"传导；传导过程"},{"word":"conductive","pos":"adj.","zh":"导电的；导热的；有传导性的"},{"word":"conductivity","pos":"n.","zh":"传导率；导电性"},{"word":"misconduct","pos":"n./v.","zh":"不当行为；行为不端"},{"word":"conducive","pos":"adj.","zh":"有助于……的；有益于……的"}],"senses":[{"no":"01","title":"Walking someone along the way","titleCN":"带路：把人一路送到","definition":"to guide or escort a person from one place to another, literally walking or travelling with them","definitionCN":"引导或陪同某人从一处走到另一处，字面上是与其同行带路","example":"A steward conducted the passengers through the flooded corridor to the far exit.","exampleCN":"一名乘务员带着乘客穿过积水的走廊，一直送到另一端的出口。","why":"The earliest English sense is 'guide, accompany and show the way'. Latin conducere means 'lead together', which is exactly this picture: leader and follower moving as one line.","whyCN":"英语最早的义项就是“引导、陪同、指路”。拉丁语 conducere 意为“一起带领”，正是这幅画面：领路的人与跟随的人成一条线移动。"},{"no":"02","title":"Carrying an activity through","titleCN":"主持完成：把事带到底","definition":"to organize and carry out a planned activity such as an experiment, survey, inquiry or campaign","definitionCN":"组织并完成一项有计划的活动，如实验、调查、审讯或运动","example":"The team conducted a survey of four hundred households over three weeks.","exampleCN":"团队用三周时间对四百户人家开展了一次调查。","why":"A project is also something that must be led from start to finish. The same leading figure now walks the work, not a person, through its steps.","whyCN":"一个项目也是一样需要从开头领到结尾的东西。同一个“领路人”现在带的是工作而不是人，一步一步走到完成。"},{"no":"03","title":"Commanding troops in the field","titleCN":"统兵：战场上的指挥","definition":"in military use, to lead and direct a body of soldiers or a campaign","definitionCN":"在军事用法中，指率领并指挥一支部队或一场战役","example":"The colonel conducted the retreat in perfect order, with no unit left behind.","exampleCN":"上校井然有序地指挥了这次撤退，没有丢下任何一支部队。","why":"The military sense is recorded from the mid-15th century. An army on the march is literally a column being led along a road, so 'lead together' becomes 'command'.","whyCN":"军事义在 15 世纪中期已有记录。行军的军队字面上就是沿路被领着走的一支纵队，于是“一起带领”变成“指挥”。"},{"no":"04","title":"Directing an orchestra","titleCN":"执棒：用动作领着乐队","definition":"to direct a performance of music by signalling to the players with the hands or a baton","definitionCN":"用手势或指挥棒示意演奏者，从而指挥一场音乐演出","example":"She conducted the final movement from memory, eyes closed for the last bars.","exampleCN":"她凭记忆指挥了最后一个乐章，最后几小节闭着眼睛。","why":"The conductor does not play; the conductor leads. Gesture takes the place of the voice that once called out the way, and the orchestra follows as one body.","whyCN":"指挥并不演奏，指挥的是“带领”。手势取代了当年喊路的声音，乐队作为一个整体跟着走。"},{"no":"05","title":"Conduct oneself: behave","titleCN":"为人行事：把自己带好","definition":"to behave in a specified way, especially in public or under pressure","definitionCN":"以某种方式表现，尤指在公开场合或压力之下","example":"He conducted himself with a calm dignity that impressed even his opponents.","exampleCN":"他表现得沉着而有尊严，连对手都为之折服。","why":"The reflexive form turns the leader inward: you are the one being led, and your own behavior is the path you walk. The sense 'behave' dates from about 1710.","whyCN":"反身形式把“领路人”转向内部：被带领的人就是你自己，而你的举止就是你走的那条路。“为人行事”这一义约在 1710 年出现。"},{"no":"06","title":"Letting heat or current pass","titleCN":"传导：让能量穿过自身","definition":"to allow heat, electricity or sound to pass along or through a material","definitionCN":"让热、电或声音沿某种材料或穿过材料传递","example":"Copper conducts heat far better than iron, which is why the pan has a copper core.","exampleCN":"铜的导热性远好于铁，所以这只锅用了铜芯。","why":"The physical sense appears about 1740. The 'way' is now the material itself, and energy is what travels along it, led through the metal as a column is led along a road.","whyCN":"这一物理义约在 1740 年出现。此时“路”就是材料本身，行走的是能量，被领着穿过金属，像队伍被领着沿路前进。"},{"no":"07","title":"Noun: personal behavior","titleCN":"名词：一个人的行为举止","definition":"the way a person acts, especially as judged by standards of propriety or morality","definitionCN":"一个人的行事方式，尤指依据得体或道德标准加以评判时","example":"The code governs the conduct of every officer on duty.","exampleCN":"这份准则约束每一名执勤人员的行为。","why":"The noun sense 'personal behavior' is recorded from the 1670s. Your conduct is the line your life traces, the visible path you leave behind.","whyCN":"名词义“个人行为”记录于 17 世纪 70 年代。你的 conduct 就是人生划出的那条线，是你留在身后的可见路径。"},{"no":"08","title":"Noun: the managing of an affair","titleCN":"名词：事务的处理与主持","definition":"the carrying out or management of an activity, business or negotiation","definitionCN":"对一项活动、事务或谈判的执行与管理","example":"The conduct of the negotiations fell to the deputy minister after the first round failed.","exampleCN":"首轮谈判失败后，谈判的进行交由副部长负责。","why":"The noun first meant 'guidance' in the mid-15th century. Guidance of a process is management of it, so the word names both the act of leading and the handling of the thing led.","whyCN":"这个名词在 15 世纪中期最初意为“引导”。对一个过程的引导就是对它的管理，因此这个词同时命名“带领”的动作和被带之事的处理。"},{"no":"09","title":"Safe conduct: leave to pass","titleCN":"安全通行：准许通行的凭证","definition":"official permission, especially a document, allowing a person to travel through a country or past a checkpoint without being stopped","definitionCN":"准许某人穿越某地或通过检查站而不被阻拦的官方许可，尤指书面凭证","example":"The envoy was granted safe conduct to cross the frontier and return within ten days.","exampleCN":"那位使节获准安全通行，越过边境并在十天内返回。","why":"A safe-conduct is literally a 'lead safely': the document takes the bearer under its protection and leads them through hostile ground. The old noun survives mainly in this fixed phrase.","whyCN":"safe-conduct 字面就是“安全地带领”：文书把持件人置于自己的保护之下，领着其穿过敌意地带。这个古老名词主要活在这个固定短语里。"}],"etymology":{"intro":{"en":"Conduct came into English twice: first as a verb in the 15th century, later as a noun. Both rest on Latin conducere 'lead together', from com- 'together' plus ducere 'lead'.","cn":"conduct 两次进入英语：15 世纪先作动词，后来才作名词。两者都建立在拉丁语 conducere“一起带领”上，即 com-“一起”加 ducere“带领”。"},"items":[{"era":"EARLY 15C.","en":"The verb is first recorded meaning 'guide, accompany and show the way'. Its past participle conductus had already been used in Medieval Latin as a noun of escorting.","cn":"动词最早记录时意为“引导、陪同、指路”。它的过去分词 conductus 在中世纪拉丁语中已用作“护送”的名词。"},{"era":"LATIN conducere","en":"Conducere means 'lead or bring together, assemble; hire'. The parts are com- 'together' and ducere 'to lead, draw'. The core image is a column of people moving under one direction.","cn":"conducere 意为“带领或聚集、召集；雇用”。两部分是 com-“一起”和 ducere“带领、牵引”。核心意象是一队人在同一个方向下移动。"},{"era":"PROTO-INDO-EUROPEAN","en":"Ducere goes back to PIE *deuk- 'to lead'. The same root produces duke, duct, induce, deduce, produce and reduce, which makes ducere one of the most productive roots in English.","cn":"ducere 可追溯到原始印欧语 *deuk-“带领”。同一词根产生 duke、duct、induce、deduce、produce、reduce，使 ducere 成为英语中产量最高的词根之一。"},{"era":"MID-15C. TO 1740","en":"The senses branch steadily: 'lead, command' in military use (mid-15th c.), 'manage' (1630s), 'behave' (1710), and 'transmit' heat or electricity (1740).","cn":"义项稳步分叉：军事上的“率领、指挥”（15 世纪中期）、“管理”（1630 年代）、“为人行事”（1710 年），以及热或电的“传导”（1740 年）。"},{"era":"MID-15C. AND 1670S","en":"The noun appears in the mid-15th century meaning 'guidance', and by the 1670s it means 'personal behavior'. The two noun senses still sit side by side in modern English.","cn":"名词在 15 世纪中期出现，意为“引导”；到 17 世纪 70 年代又指“个人行为”。这两个名词义项在现代英语中仍并列存在。"},{"era":"DOUBLET","en":"Conduct and conduit are a doublet: both descend from Latin conductus, but conduit came through Old French and narrowed to a channel for water or wires. Same origin, different shape, different job.","cn":"conduct 与 conduit 是一组同源双式词：两者都出自拉丁 conductus，但 conduit 经古法语进入英语，词义收窄为水管或线管。同源、不同形、不同职守。"}]},"similar":{"note":{"en":"The first group gathers forms built on the same Latin ducere, including the doublet conduit; the second group separates the verbs that cover only one of conduct's many jobs.","cn":"第一组收同一拉丁词根 ducere 构成的词形，包括同源双式词 conduit；第二组区分只能覆盖 conduct 某一项职能的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conduit","ipa":"/ˈkɒndjuːɪt/","tag":"doublet","definition":"a pipe or channel that carries water, gas or cables. It is the same Latin conductus as conduct, but routed through Old French and narrowed to a physical channel.","definitionCN":"输送水、燃气或电缆的管道、导管。它与 conduct 同出拉丁 conductus，但经古法语进入英语，词义收窄为物理管道。"},{"word":"conductor","ipa":"/kənˈdʌktə/","tag":"agent noun","definition":"one who conducts: a music director, the person in charge of a train, or a material that carries heat or current. The -or suffix marks the doer or the thing that does.","definitionCN":"指挥者：乐队指挥、列车长，或导热导电的材料。-or 后缀标记动作的发出者或起作用之物。"},{"word":"conduction","ipa":"/kənˈdʌkʃn/","tag":"process noun","definition":"the process by which heat, electricity or sound passes through a material. It is the noun of the physical sense, not of guiding people.","definitionCN":"热、电或声通过材料的传导过程。它是物理义的名词，不是“带人”的名词。"},{"word":"conducive","ipa":"/kənˈdjuːsɪv/","tag":"same root, different suffix","definition":"tending to bring about a result, as in 'conducive to sleep'. It keeps the Latin sense 'lead to' but has lost the sense of leading a person.","definitionCN":"有助于引出某种结果的，如 conducive to sleep（有助于睡眠）。它保留拉丁语“引向”的意思，但已失去“带人”的含义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"lead","ipa":"/liːd/","tag":"general guiding","definition":"to go in front and show the way, or to be in charge of a group. It is the plain everyday word behind conduct's first sense and carries no hint of surveys or copper wire.","definitionCN":"走在前面引路，或负责带领一个群体。它是 conduct 第一义项背后朴素的日常词，不带调查、铜线等含义。"},{"word":"manage","ipa":"/ˈmænɪdʒ/","tag":"running an operation","definition":"to be in charge of a business, team or process and make it work. It matches conduct in the sense of carrying out an activity, but stresses control rather than guidance.","definitionCN":"负责管理企业、团队或流程并使其运转。它与 conduct“开展活动”一义相合，但强调控制而非引导。"},{"word":"behave","ipa":"/bɪˈheɪv/","tag":"conduct oneself","definition":"to act in a particular way, especially in social situations. It is the intransitive twin of conduct oneself and cannot take an object like 'an experiment'.","definitionCN":"以某种方式行事，尤指在社交场合。它是 conduct oneself 的不及物对应词，不能像 conduct 那样接 an experiment 这样的宾语。"},{"word":"transmit","ipa":"/trænzˈmɪt/","tag":"send through a medium","definition":"to send a signal, heat, sound or disease from one place to another. It focuses on the sending; conduct focuses on the material's ability to let it pass.","definitionCN":"把信号、热、声或疾病从一处送到另一处。它着眼于“发送”；conduct 着眼于材料“允许其通过”的能力。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: com- 'together', ducere 'lead', the doublet conduit, and the conductor family.","cn":"只用真实成分与真实同族词：com-“一起”、ducere“带领”、同源双式词 conduit，以及 conductor 词族。"},"normal":[{"en":"ducere means 'lead'. Conductor, conduit, induce, deduce and reduce all contain that same instruction: lead something somewhere.","cn":"ducere 意为“带领”。conductor、conduit、induce、deduce、reduce 都含同一条指令：把某物引向某处。"},{"en":"Conduct and conduit are doubles of one Latin word. The verb kept the action; the noun-shaped doublet kept only the pipe.","cn":"conduct 与 conduit 是同一个拉丁词的两个分身。动词形保留了动作；名词形的分身只留下了管道。"},{"en":"A conductor of an orchestra and a conductor of electricity do the same job in different materials: each leads something through a performance.","cn":"乐队指挥与导电体和做的是同一件事，只是材料不同：各自把某种东西领过一场“演出”。"},{"en":"The noun stress falls forward: CONduct for behavior, conDUCT for the verb. The same spelling splits by stress.","cn":"名词重音在前：CONduct 指行为；动词重音在后：conDUCT。同一个拼写靠重音分工。"},{"en":"Safe conduct is not 'safe behavior'. It is a document that leads its bearer safely through danger.","cn":"safe conduct 不是“安全的行为”，而是一份把持件人安全领过危险地带的文书。"}],"abstract":[{"en":"Picture one person walking in front down a narrow corridor, a whole line following in step. That line is conduct before it is anything else.","cn":"想象一个人走在狭窄走廊的最前面，一整队人踏着同样的步子跟着。这条线就是 conduct 最本来的样子。"},{"en":"The line can be made of people, of steps in an experiment, of soldiers, of players in an orchestra, of electrons in copper, or of years in a life.","cn":"这条线可以由人组成，也可以由实验步骤、士兵、乐队成员、铜中的电子，或一个人一生中的岁月组成。"},{"en":"Turn the line inward and it becomes behavior: the path you walk when nobody is leading you but yourself.","cn":"把这条线转向内部，它就成了行为：当没有人领你、只有你自己领自己时，你走出的那条路。"}]},"examples":[{"en":"The institute conducts a full safety check before any reactor is restarted.","cn":"任何反应堆重启之前，研究所都会做一次完整的安全检查。"},{"en":"He conducted himself so well under questioning that the panel changed its tone.","cn":"他在质询中表现得如此得体，以至于评审小组改变了语气。"},{"en":"The conduct of the election was criticized by observers from three countries.","cn":"这次选举的组织过程受到来自三个国家的观察员批评。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“肯搭客”——肯搭把手，把客人一路带到门口 → conduct 引导；实施","word":"conduct"},"root":"源自拉丁语 conducere“一起带领”，由 com-“一起”+ ducere“带领”构成，核心是“走在前面，把人或事一路带到终点”。","sensesIntro":{"en":"Nine senses of conduct, all built on one gesture: a leader walks in front and a line follows. The line may be people, a project, troops, an orchestra, a current, or a whole life.","cn":"conduct 的九个义项都建立在同一个动作上：领路者走在前面，一条线跟着。这条线可以是人、一个项目、军队、乐队、电流，也可以是一整个人生。"},"semanticMap":{"core":{"en":"CORE IMAGE: one leader walks in front and a line follows through to the end.","cn":"核心意象：一个领路者走在前面，一条线跟着走到终点。"},"chain":["LEAD THE WAY","BRING ALONG","TAKE CHARGE","CARRY IT THROUGH","PASS THROUGH A MEDIUM","BEHAVE BEFORE OTHERS"],"branches":[{"senses":"S1 · S3 · S9","en":"ESCORT AND COMMAND: a person or a column is led along a road, and a document can lead its bearer safely through danger.","cn":"护送与统率：一个人或一支纵队被领着沿路前进，一份文书则能把持件人安全领过险境。"},{"senses":"S2 · S8","en":"CARRYING OUT: a project replaces the person at the head of the line, and leading becomes managing.","cn":"执行：项目取代了队首的那个人，引导由此变成管理。"},{"senses":"S4","en":"DIRECTION BY GESTURE: the orchestra follows a hand instead of a voice, but the line is the same.","cn":"以手势指挥：乐队跟着一只手而不是一个声音走，但那条线没有变。"},{"senses":"S5 · S7","en":"SELF-DIRECTION: the line turns inward, and the path a person walks becomes their behavior.","cn":"自我引导：线转向内部，一个人走出的路径就成了他的行为举止。"},{"senses":"S6","en":"TRANSMISSION: the road is now a material, and heat or current is what travels along it.","cn":"传导：此时路变成了材料，沿它行走的是热或电流。"}]},"affixes":{"intro":{"en":"Conduct is transparently built: con- 'together' plus ducere 'lead'. English adds the usual verb endings, and the same root supplies a large family of learned words.","cn":"conduct 的构词完全透明：con-“一起”加 ducere“带领”。英语加上普通动词词尾，同一词根还供应了一大批学术词汇。"},"latinIntro":{"en":"The Latin family is conducere 'lead together', conductus 'escorted, hired', ducere 'lead' and ductus 'a leading, a channel'. Via French and directly, ducere also gives duke, duct, induce, deduce, produce and reduce.","cn":"这一拉丁词族包括 conducere“一起带领”、conductus“被护送、被雇用”、ducere“带领”和 ductus“带领、通道”。经法语或直接借入，ducere 还给出 duke、duct、induce、deduce、produce、reduce。"},"items":[{"word":"conductor","structure":"conduct + -or (doer)","meaning":"one who leads a performance; a material that carries current; a train official","meaningCN":"指挥；导体；列车长（-or 表示动作发出者）","example":"The conductor raised her baton and the hall went silent.","exampleCN":"指挥举起指挥棒，大厅安静下来。"},{"word":"conduction","structure":"conduct + -ion (process noun)","meaning":"the passing of heat, electricity or sound through a material","meaningCN":"传导；传导过程（-ion 构成过程名词）","example":"Conduction through the copper bar melted the wax at the far end.","exampleCN":"通过铜棒的传导把另一端的蜡熔化了。"},{"word":"conductive","structure":"conduct + -ive (adjective)","meaning":"able to carry heat or electricity","meaningCN":"导电的；导热的（-ive 构成形容词）","example":"The gel is conductive, so it links the sensor to the skin.","exampleCN":"这种凝胶导电，因此把传感器与皮肤连接起来。"},{"word":"conductivity","structure":"conductive + -ity (measure noun)","meaning":"the degree to which a material conducts","meaningCN":"传导率；导电性（-ity 构成度量名词）","example":"Salt raises the conductivity of water noticeably.","exampleCN":"盐会明显提高水的导电性。"},{"word":"conducive","structure":"con- + ducere + -ive","meaning":"tending to lead to a result; helpful","meaningCN":"有助于……的；有益于……的","example":"A quiet room is conducive to concentrated reading.","exampleCN":"安静的房间有助于专心阅读。"},{"word":"misconduct","structure":"mis- (wrongly) + conduct","meaning":"wrong or improper behavior, especially by a professional","meaningCN":"不当行为；失职行为（mis- 表示“错误地”）","example":"The referee was suspended for misconduct after the match.","exampleCN":"那名裁判因赛后行为不当被停职。"},{"word":"induce","structure":"in- (into) + ducere (lead)","meaning":"to lead someone into an action or a state","meaningCN":"诱导；引起（in- 向内 + ducere 带领）","example":"The drug induces sleep within twenty minutes.","exampleCN":"这种药在二十分钟内引起睡意。"},{"word":"deduce","structure":"de- (down, from) + ducere (lead)","meaning":"to lead a conclusion out of the evidence","meaningCN":"推论；演绎（de- 向下、从…… + ducere 引出）","example":"From the two dates we can deduce the length of the voyage.","exampleCN":"从这两个日期我们可以推算出航程的长短。"},{"word":"produce","structure":"pro- (forward) + ducere (lead)","meaning":"to lead or bring something forth","meaningCN":"生产；产生（pro- 向前 + ducere 引出）","example":"The region produces most of the country's tea.","exampleCN":"该国大部分茶叶由这个地区生产。"},{"word":"reduce","structure":"re- (back) + ducere (lead)","meaning":"to lead something back to a smaller or simpler state","meaningCN":"减少；使简化（re- 向后 + ducere 引回）","example":"The new rules reduce the amount of waste sent to landfill.","exampleCN":"新规减少了送往填埋场的垃圾量。"},{"word":"duct","structure":"ductus (a leading, a channel)","meaning":"a tube or passage for air, water or cables","meaningCN":"管道；通道（拉丁 ductus 直接进入英语）","example":"Warm air rises through a duct behind the wall.","exampleCN":"暖空气经墙后的管道上升。"}],"latinEntries":[{"word":"ducere","structure":"PIE *deuk- 'lead' + Latin verb stem","meaning":"to lead, draw, guide","meaningCN":"带领；牵引；引导"},{"word":"conducere","structure":"con- (together) + ducere (lead)","meaning":"to lead or bring together; to hire","meaningCN":"一起带领；聚集；雇用"},{"word":"conductus","structure":"conducere + -tus (past participle)","meaning":"escorted, led; also a body of escort","meaningCN":"被护送的；被带领的；也指护送队"},{"word":"ductus","structure":"ducere + -tus (action noun)","meaning":"a leading; a channel or conduit","meaningCN":"带领；通道、导管"}]}},{"word":"confer","ipa_uk":"/kənˈfɜː/","ipa_us":"/kənˈfɜːr/","definition_zh":"授予；赋予（称号、学位、权利）；协商；比较（cf.）","definition_en":"to give an honour, degree, right or quality to someone; to discuss something with others; or, in formal and scholarly use, to compare","core_image":"把两样东西并排端到同一张桌上，再决定把其中一样递出去","scene":"The university will confer an honorary degree on the retired surgeon at the spring ceremony.","sceneCN":"这里 confer 是「授予」（第 4 个义项：在仪式上把学位、称号或荣誉正式颁给某人）；句意：大学将在春季典礼上授予这位退休外科医生荣誉学位。场景要点：台上的人把一份正式的东西递到对方手里，全场见证。","pos":[{"tag":"v.","zh":"授予；赋予（荣誉、学位、权利、品质）"},{"tag":"v.","zh":"协商；商议；比较（多用于 confer with / cf.）"}],"collocations":[{"phrase":"confer a degree on someone","zh":"授予某人学位"},{"phrase":"confer an honour upon someone","zh":"授予某人荣誉"},{"phrase":"confer with colleagues","zh":"与同事商议"},{"phrase":"confer about the schedule","zh":"就日程进行磋商"},{"phrase":"confer a right on citizens","zh":"赋予公民一项权利"},{"phrase":"confer an advantage","zh":"带来／赋予一种优势"}],"forms":[{"label":"第三人称单数","form":"confers"},{"label":"过去式","form":"conferred"},{"label":"过去分词","form":"conferred"},{"label":"现在分词（双写 r）","form":"conferring"}],"derivatives":[{"word":"conference","pos":"n.","zh":"会议；协商；座谈会"},{"word":"conferment","pos":"n.","zh":"授予；颁授"},{"word":"conferral","pos":"n.","zh":"授予（学位、荣誉等）"},{"word":"conferrable","pos":"adj.","zh":"可授予的；可赋予的"},{"word":"conferring","pos":"n.","zh":"授予行为；商议"}],"senses":[{"no":"01","title":"Brought onto one table","titleCN":"并置一处：把东西带到同一张桌上","definition":"literally, to bring two or more things together into one place, which is the oldest Latin sense of the word","definitionCN":"字面上指把两样或更多的东西带到同一处，这是该词最古老的拉丁语含义","example":"In the Latin of the schools, to confer two manuscripts was to lay them side by side on the same table.","exampleCN":"在学校里的拉丁语用法中，confer 两份手稿就是把它们并排摊在同一张桌上。","why":"Conferre is com- 'together' plus ferre 'to carry'. Nothing else in the word's history matters until this simple act is pictured: carrying separate things to one spot.","whyCN":"conferre 是 com-“一起”加 ferre“携带”。在想象出这个简单动作之前，这个词的历史里没有别的更重要的东西：把分开的东西搬到同一处。"},{"no":"02","title":"Set side by side to compare","titleCN":"并排比对：以比较来审查","definition":"to examine two things by placing them together and noting their differences, a sense still kept in the scholarly abbreviation cf.","definitionCN":"把两样东西放在一起审视、指出其异同；这一义项仍保留在学术缩写 cf. 中","example":"Before accepting the translation, confer the second edition with the first.","exampleCN":"在接受这份译文之前，请把第二版与第一版比对一下。","why":"The first recorded English sense, from the 1530s, is 'examine by comparison'. Two objects carried to one table are automatically in view of each other, and comparison is what that view allows.","whyCN":"英语最早记录的义项（16 世纪 30 年代）就是“通过比较来审查”。两样东西被搬到同一张桌上，自然就彼此在视野之内，而比较正是这种同视所允许的事。"},{"no":"03","title":"Consulting together","titleCN":"共同商议：把意见带到一处","definition":"to discuss something with one or more people in order to exchange views or reach a decision","definitionCN":"与一个或多人讨论某事，以交换看法或作出决定","example":"The two ministers conferred for an hour before anyone spoke to the press.","exampleCN":"两位部长在有人面对媒体之前商议了一个小时。","why":"The intransitive sense 'consult together' arrives in the 1540s. Now the things carried to the table are not documents but opinions, and the table is a conversation.","whyCN":"不及物的“共同商议”义在 16 世纪 40 年代出现。此时被搬到桌上的不是文件而是意见，而桌子就是一场谈话。"},{"no":"04","title":"Bestowing a degree or honour","titleCN":"颁授：在仪式上正式给出","definition":"to give a degree, title, medal or honour to someone in a formal ceremony","definitionCN":"在正式仪式上把学位、称号、奖章或荣誉授予某人","example":"The college conferred its highest fellowship on the chemist who had trained half its staff.","exampleCN":"学院把最高级别的荣誉研究员称号授予了那位培养出一半教员的化学家。","why":"The sense 'bestow as a gift' is recorded from the 1560s. One object is carried to the table and then handed across it, so 'bring together' becomes 'hand over'.","whyCN":"“作为礼物赐予”这一义项记录于 16 世纪 60 年代。一样东西被带到桌边，然后越过桌面递过去，于是“带到一起”变成“递交出去”。"},{"no":"05","title":"Granting a legal power or right","titleCN":"法定赋予：以条文授权","definition":"of a law, contract or office, to give a right, power or jurisdiction to a person or body","definitionCN":"指法律、合同或职位把某项权利、权力或管辖权赋予某人或某机构","example":"The statute confers on the agency the power to inspect private records without notice.","exampleCN":"该法规赋予这个机构不经通知即可查阅私人记录的权力。","why":"A right is an abstract object that can still be handed over. Legal drafting keeps confer for grants that come from an authoritative source rather than from goodwill.","whyCN":"权利是一种仍然可以被“递交”的抽象物。法律文本保留 confer 来指由权威来源而非善意给出的授予。"},{"no":"06","title":"Lending a quality or advantage","titleCN":"赋予某种性质或优势","definition":"of a quality, status or circumstance, to give an advantage, value or character to something","definitionCN":"指某种性质、地位或情形给某物带来优势、价值或特征","example":"One early victory conferred on the small team a reputation it never lost.","exampleCN":"一场早期的胜利给这支小球队带来了一种再也没丢掉的声誉。","why":"Here the thing handed over is not a medal but a quality. Age can confer authority, and a view can confer value, because both add something to what was already there.","whyCN":"这里递出去的不是奖章，而是一种性质。年岁可以赋予权威，一处景观可以赋予价值，因为它们都给原本存在的东西添上了什么。"},{"no":"07","title":"Giving a blessing","titleCN":"施予祝福：宗教与仪式中的给予","definition":"in religious usage, to give a blessing, grace or spiritual gift","definitionCN":"在宗教用法中，指给予祝福、恩典或属灵的礼物","example":"The bishop conferred the blessing on the newly built chapel before it opened.","exampleCN":"新礼拜堂启用前，主教为其施予祝福。","why":"A blessing is the most literal kind of gift that can be conferred: it is spoken over a person or a place and travels from the speaker to the receiver.","whyCN":"祝福是最字面意义上的“可授予之物”：它被对着一个人或一处地方说出，从说话者传向接受者。"},{"no":"08","title":"Conferring a favour","titleCN":"施惠：以小恩小惠相待","definition":"to do someone a kindness or favour, often one that puts the receiver under a mild obligation","definitionCN":"对某人施以善意或恩惠，常使接受者略感亏欠","example":"He conferred on his old teacher the small favour of a quiet, unpublicized introduction.","exampleCN":"他给了老教师一个小小的恩惠：一次安静、不见诸报道的引见。","why":"A favour is a gift with a social price tag. The word's formal tone survives here: the giver is above the receiver, and the thing given is handed down rather than shared.","whyCN":"恩惠是一份带社交价签的礼物。这个词的正式语气在此保留：给予者地位高于接受者，给出的东西是自上而下递交的，而不是共享的。"}],"etymology":{"intro":{"en":"Confer entered English through Old French from Latin conferre 'bring together'. Its three modern branches, compare, consult and bestow, are three ways of carrying things to one place.","cn":"confer 经古法语从拉丁语 conferre“带到一起”进入英语。它现代的三条分支——比较、商议、授予——都是“把东西搬到一处”的三种方式。"},"items":[{"era":"1530S","en":"First recorded in English meaning 'examine by comparison'. The scholarly sense survives in the abbreviation cf., still printed in dictionaries and notes.","cn":"英语中最早记录于 16 世纪 30 年代，意为“通过比较来审查”。这一学术义仍活在缩写 cf. 中，至今印在词典与注释里。"},{"era":"OLD FRENCH","en":"The word came in through Old French conférer, which had already widened the Latin verb toward both 'compare' and 'talk together'.","cn":"这个词经古法语 conférer 传入，古法语已把拉丁动词向“比较”和“交谈”两个方向拓宽。"},{"era":"LATIN conferre","en":"Conferre means 'bring together, collect, compare, contribute': com- 'together' plus ferre 'to bear, carry'. The physical picture is carrying separate loads to one spot.","cn":"conferre 意为“带到一起、收集、比较、贡献”：com-“一起”加 ferre“承载、携带”。物理画面是把分开的担子搬到同一处。"},{"era":"PROTO-INDO-EUROPEAN","en":"Ferre goes back to PIE *bher- (1) 'to carry, bear a burden'. The same root gives bear, birth, burden, transfer, refer, infer and differ.","cn":"ferre 可追溯到原始印欧语 *bher- (1)“携带、承担重物”。同一词根给出 bear、birth、burden、transfer、refer、infer、differ。"},{"era":"1540S TO 1560S","en":"The intransitive sense 'consult together' appears in the 1540s, and 'bestow as a gift' in the 1560s. The meeting sense is fixed in the noun conference by the 1550s.","cn":"不及物的“共同商议”义在 16 世纪 40 年代出现，“作为礼物赐予”义在 16 世纪 60 年代出现。到 16 世纪 50 年代，“会议”义已固定在名词 conference 中。"},{"era":"MODERN ENGLISH","en":"Modern usage splits by object: you confer with people, confer a degree on a graduate, confer a power by statute, and confer a quality on a thing. The preposition usually tells you which branch is active.","cn":"现代用法按宾语分工：confer with 人、confer a degree on 毕业生、依法规 confer a power、给事物 confer a quality。介词通常提示走的是哪条分支。"}]},"similar":{"note":{"en":"The first group separates the noun forms and the abbreviation from the verb, and adds infer to show how far the ferre family spreads; the second group compares the three practical jobs confer does.","cn":"第一组区分动词的名词形式与缩写，并加入 infer 以显示 ferre 词族铺得多远；第二组比较 confer 实际承担的三种职能。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conference","ipa":"/ˈkɒnfərəns/","tag":"noun of the meeting sense","definition":"a large formal meeting for discussion, or the act of consulting. It is the noun of confer in its 'talk together' branch, not of the 'bestow' branch.","definitionCN":"大型正式讨论会，或商议的行为。它是 confer“共同商议”分支的名词，不是“授予”分支的名词。"},{"word":"cf.","ipa":"/ˌsiː ˈef/","tag":"abbreviation","definition":"the printed abbreviation of Latin confer, meaning 'compare'. It is read letter by letter in English and appears in dictionaries and academic notes, never as a spoken verb.","definitionCN":"拉丁语 confer 的印刷缩写，意为“比较”。英语中按字母读作 see-eff，出现在词典与学术注释里，从不作为口语动词使用。"},{"word":"conferment","ipa":"/kənˈfɜːmənt/","tag":"derived noun","definition":"the act of granting an honour, degree or right. It names the giving, while conference names the talking. Conferral means the same thing and is the more formal variant.","definitionCN":"授予荣誉、学位或权利的行为。它命名“给出”，而 conference 命名“谈话”。conferral 意思相同，是更正式的变体。"},{"word":"infer","ipa":"/ɪnˈfɜː/","tag":"same root, other prefix","definition":"to reach a conclusion by reasoning. It shares Latin ferre 'carry' but its prefix is in- 'into', so it means 'carry a conclusion into' a case, not 'carry things together'.","definitionCN":"通过推理得出结论。它共享拉丁 ferre“携带”，但前缀是 in-“进入”，意为把结论“带进”某个情形，而不是“带到一起”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"consult","ipa":"/kənˈsʌlt/","tag":"talk it over","definition":"to ask someone for advice or exchange views before deciding. It matches confer with but is more common in everyday speech and does not mean 'grant'.","definitionCN":"在决定前向人请教或交换看法。它与 confer with 相合，但更常用于日常口语，且没有“授予”之义。"},{"word":"grant","ipa":"/ɡrɑːnt/","tag":"formal giving","definition":"to give something formally, especially a right, request or privilege. It is the plain legal word where confer is the ceremonial one.","definitionCN":"正式给予，尤指权利、请求或特权。它是朴素的法律用词，而 confer 是仪式化的用词。"},{"word":"bestow","ipa":"/bɪˈstəʊ/","tag":"ceremonial giving","definition":"to give an honour, gift or quality in a formal and often gracious way. It is the closest synonym of confer in the 'award' sense, and slightly more literary.","definitionCN":"以正式而常带隆重的方式给予荣誉、礼物或品质。它是 confer“颁授”义最接近的同义词，且稍微更书面。"},{"word":"endow","ipa":"/ɪnˈdaʊ/","tag":"giving a lasting quality","definition":"to give a permanent quality, ability or fund to a person or institution. It stresses what remains after the giving, where confer stresses the act of handing over.","definitionCN":"给人或机构永久性的品质、能力或资金。它强调给予之后留存的东西，而 confer 强调递交的动作。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: com- 'together', ferre 'carry', the noun conference, and the ferre family in transfer and infer.","cn":"只用真实成分与真实同族词：com-“一起”、ferre“携带”、名词 conference，以及 transfer、infer 中的 ferre 词族。"},"normal":[{"en":"ferre means 'carry'. Conference, transfer, refer and infer all keep that instruction, but each with a different prefix telling where the carrying goes.","cn":"ferre 意为“携带”。conference、transfer、refer、infer 都保留这条指令，只是前缀不同，指明“带往哪里”。"},{"en":"The prepositions run the verb: confer WITH people, confer a degree ON a graduate, confer a power BY statute. Change the preposition and you change the branch.","cn":"介词决定走哪条义：confer WITH 人、confer a degree ON 毕业生、confer a power BY 法规。换介词就是换分支。"},{"en":"cf. is not a word you say; it is Latin confer printed small, and it means 'compare', the oldest English sense of the verb.","cn":"cf. 不是读出来的词；它是小写的拉丁语 confer，意为“比较”，也是这个动词最古老的英语义项。"},{"en":"Conference is people carrying opinions to one table. Conferment is one person carrying a degree across that table.","cn":"conference 是把意见搬到同一张桌子上的一群人；conferment 是一个人越过那张桌子递出一份学位。"},{"en":"Do not mix confer with infer or differ: all three contain ferre, but the prefixes in-, dis- and con- point in three different directions.","cn":"别把 confer 与 infer、differ 混为一谈：三者都含 ferre，但前缀 in-、dis-、con- 指向三个不同的方向。"}],"abstract":[{"en":"Picture a large table. Two documents are laid side by side; then two people sit down and speak; then one of them slides a sealed award across the wood.","cn":"想象一张大桌子。两份文件被并排摊开；然后两个人坐下来说话；接着其中一人把一份封好的奖状推过桌面。"},{"en":"Comparison, consultation and bestowal are the same journey made three times, with documents, opinions and gifts as the loads.","cn":"比较、商议、授予是同一趟路程走了三次，只是所载之物分别为文件、意见和礼物。"},{"en":"The word is formal because the table is formal: a court, a senate, a university hall. Nobody confers in a queue at a bus stop.","cn":"这个词之所以正式，是因为那张桌子正式：法庭、元老院、大学礼堂。没人会在公交站排队时 confer。"}]},"examples":[{"en":"The judges conferred briefly before announcing the winner.","cn":"评委们在宣布获胜者之前简短地商议了一下。"},{"en":"A government grant conferred on the town the means to rebuild its library.","cn":"一笔政府拨款使这个镇获得了重建图书馆的财力。"},{"en":"Confer this map with the older survey and you will see where the river moved.","cn":"把这张地图与较早的测量图比对，你就能看出河流改道的位置。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“肯福”——肯把福气分给别人，就是授予 → confer 授予；赋予","word":"confer"},"root":"源自拉丁语 conferre“带到一起”，由 com-“一起”+ ferre“携带”构成，核心是“把东西并排搬到同一处，再决定如何处置”。","sensesIntro":{"en":"Eight senses of confer, all performed at one table: things are carried there, compared, talked over, and finally one of them is handed across. The table is what keeps compare, consult and bestow in a single word.","cn":"confer 的八个义项都发生在同一张桌子上：东西被搬到那里、被比较、被谈论，最后其中一样被递过去。正是这张桌子把“比较”“商议”“授予”留在了同一个词里。"},"semanticMap":{"core":{"en":"CORE IMAGE: separate things are carried to one table, then one of them is handed across.","cn":"核心意象：分开的东西被搬到同一张桌上，随后其中一样被递过去。"},"chain":["CARRY TOGETHER","LAY SIDE BY SIDE","COMPARE AND EXAMINE","TALK IT OVER","HAND IT ACROSS","GRANT AND LEND"],"branches":[{"senses":"S1 · S2","en":"COMPARISON: two objects share one table, so each becomes visible against the other; cf. is the fossil of this sense.","cn":"比较：两样东西共享一张桌子，于是彼此映照而显形；cf. 就是这一义项的化石。"},{"senses":"S3","en":"CONSULTATION: the loads are opinions, and the table becomes a conversation with people you confer with.","cn":"商议：所载之物变成意见，桌子变成一场与你 confer with 的人的谈话。"},{"senses":"S4 · S7 · S8","en":"CEREMONIAL GIVING: a degree, a blessing or a favour travels across the table from a superior hand.","cn":"仪式性给予：学位、祝福或恩惠从上位者的手中越过桌面递出。"},{"senses":"S5","en":"AUTHORITATIVE GRANT: a statute or contract puts a right into someone's hands, and the source is the law, not goodwill.","cn":"权威授予：法规或合同把一项权利放进某人手里，来源是法律而非善意。"},{"senses":"S6","en":"QUALITY: what is handed over is no longer an object but a property, such as prestige, authority or value.","cn":"性质：递出的不再是物件，而是一种属性，如声望、权威或价值。"}]},"affixes":{"intro":{"en":"Confer is built from two live Latin pieces: con- 'together' and ferre 'carry'. English adds -ence, -ment and -al to make nouns, and the same ferre appears under many prefixes.","cn":"confer 由两个仍可读的拉丁成分构成：con-“一起”与 ferre“携带”。英语加 -ence、-ment、-al 构成名词，同一个 ferre 还在许多前缀下反复出现。"},"latinIntro":{"en":"The Latin family is conferre 'bring together', its supine stem collat- (seen in English collation), and ferre 'bear'. Ferre is irregular and supplies transfer, refer, infer, differ, prefer, offer and suffer.","cn":"这一拉丁词族包括 conferre“带到一起”、它的动名词词干 collat-（见于英语 collation），以及 ferre“承载”。ferre 是不规则动词，供应了 transfer、refer、infer、differ、prefer、offer、suffer。"},"items":[{"word":"conference","structure":"confer + -ence (noun of action)","meaning":"a formal meeting for discussion; the act of consulting","meaningCN":"正式讨论会；商议（-ence 构成行为名词）","example":"The conference brought forty researchers into one room.","exampleCN":"这次会议把四十位研究者聚进了一个房间。"},{"word":"conferment","structure":"confer + -ment (result noun)","meaning":"the act of granting an honour or degree","meaningCN":"授予；颁授（-ment 构成结果名词）","example":"The conferment of the degree took place in the old hall.","exampleCN":"学位授予仪式在那座老礼堂举行。"},{"word":"conferral","structure":"confer + -al (action noun)","meaning":"the granting of something, especially a right or title; a formal variant of conferment","meaningCN":"授予（权利、称号等）；conferment 的正式变体","example":"The conferral of citizenship followed a long review.","exampleCN":"公民身份的授予经过了一段漫长的审核。"},{"word":"transfer","structure":"trans- (across) + ferre (carry)","meaning":"to carry from one place or person to another","meaningCN":"转移；调动（trans- 越过 + ferre 携带）","example":"The files were transferred to a secure server.","exampleCN":"文件被转移到一台安全服务器上。"},{"word":"refer","structure":"re- (back) + ferre (carry)","meaning":"to send something back to a source or point it toward","meaningCN":"提及；转介；查阅（re- 回 + ferre 携带）","example":"The footnote refers the reader to an earlier chapter.","exampleCN":"这条脚注引导读者去查前面的一章。"},{"word":"infer","structure":"in- (into) + ferre (carry)","meaning":"to carry a conclusion into a case; to reason to a result","meaningCN":"推断；推论（把结论带进某个情形）","example":"We can infer from the empty shelves that the shop has closed.","exampleCN":"从空货架可以推断这家店已经关门。"},{"word":"differ","structure":"dis- (apart) + ferre (carry)","meaning":"to carry apart; to be unlike","meaningCN":"不同；相异（dis- 分开 + ferre 携带）","example":"The two accounts differ on one important date.","exampleCN":"两份记述在一个重要日期上不一致。"},{"word":"prefer","structure":"prae- (before) + ferre (carry)","meaning":"to carry something before others; to like it better","meaningCN":"更喜欢；宁愿（prae- 在前 + ferre 携带）","example":"I prefer the earlier design, before the extra windows were added.","exampleCN":"我更喜欢早些时候的设计，还没加那些额外窗户时。"},{"word":"offer","structure":"ob- (toward) + ferre (carry)","meaning":"to carry something toward someone; to present it","meaningCN":"提供；主动给予（ob- 朝向 + ferre 携带）","example":"She offered him a seat near the window.","exampleCN":"她给他提供了一个靠窗的座位。"},{"word":"suffer","structure":"sub- (under) + ferre (bear)","meaning":"to bear a load underneath; to undergo pain","meaningCN":"遭受；承受（sub- 在下 + ferre 承载）","example":"The village suffered a second flood that winter.","exampleCN":"那年冬天这个村子又遭了一次洪水。"}],"latinEntries":[{"word":"ferre","structure":"PIE *bher- (1) 'carry, bear' + Latin irregular verb","meaning":"to bear, carry, bring","meaningCN":"承载；携带；带来"},{"word":"conferre","structure":"con- (together) + ferre (carry)","meaning":"to bring together, collect, compare, contribute","meaningCN":"带到一起；收集；比较；贡献"},{"word":"collatio","structure":"con- + lat- (supine stem of ferre) + -io","meaning":"a bringing together; a comparison","meaningCN":"聚集；比较（英语 collation 的直接来源）"}]}},{"word":"confidence","ipa_uk":"/ˈkɒnfɪdəns/","ipa_us":"/ˈkɑːnfɪdəns/","definition_zh":"信心；自信；信任；确信；知心话（旧）","definition_en":"a feeling of trust in someone or something, belief in one's own abilities, or certainty that something is true","core_image":"把心交到另一个人手里，因此自己站得更稳","scene":"She stepped onto the stage with the quiet confidence of someone who had rehearsed until the words belonged to her.","sceneCN":"这里 confidence 是「自信」（第 2 个义项：对自己能力的信任）；句意：她走上舞台时带着一种安静的自信，那是反复排练到那些词句已经属于自己的人才会有的。场景要点：不需要大声证明，身体先稳住了，因为她知道自己做得到。","pos":[{"tag":"n.","zh":"信心；自信；信任；确信"},{"tag":"n.","zh":"知心话；私下托付的秘密（旧用法）"}],"collocations":[{"phrase":"gain confidence","zh":"获得信心；增强自信"},{"phrase":"lose confidence","zh":"失去信心"},{"phrase":"with confidence","zh":"有把握地；自信地"},{"phrase":"confidence in someone","zh":"对某人的信任"},{"phrase":"in confidence","zh":"私下地；秘密地"},{"phrase":"a vote of confidence","zh":"信任投票"}],"forms":[{"label":"复数","form":"confidences"}],"derivatives":[{"word":"confident","pos":"adj.","zh":"自信的；有把握的"},{"word":"confidently","pos":"adv.","zh":"自信地；有把握地"},{"word":"confidential","pos":"adj.","zh":"机密的；秘密的"},{"word":"confidentiality","pos":"n.","zh":"保密性；机密性"},{"word":"overconfidence","pos":"n.","zh":"过度自信"},{"word":"confide","pos":"v.","zh":"向……吐露（心事）；信赖"}],"senses":[{"no":"01","title":"Trust in another's good will","titleCN":"信任他人：相信对方不会害你","definition":"a belief that another person is reliable and means you no harm, so that you can rely on them","definitionCN":"相信另一个人可靠、不会伤害你，因此可以依靠他","example":"The child's confidence in her aunt was complete: she would go anywhere the woman led.","exampleCN":"孩子对姑姑的信任是彻底的：她愿意跟着她走到任何地方。","why":"The word is recorded around 1400 with exactly this sense, 'assurance or belief in another's good will'. Trust is the ground floor of confidence; everything else is built above it.","whyCN":"这个词约在 1400 年正以这个意义被记录：“对他人善意的确信”。信任是 confidence 的地基，其余义项都盖在它上面。"},{"no":"02","title":"Belief in one's own abilities","titleCN":"自信：相信自己撑得住","definition":"a settled belief that one can do something well or handle a situation","definitionCN":"对自己能做好某事或应对某种局面持有稳定的信念","example":"After three successful surgeries, the young doctor spoke with a new confidence.","exampleCN":"三台成功的手术后，那位年轻医生说话时带上了一种新的自信。","why":"Self-assurance appears in the mid-15th century: the trust you would give a reliable friend is now given to yourself. You become both the one who trusts and the one trusted.","whyCN":"“自信”义在 15 世纪中期出现：你原本给可靠朋友的信任，现在给了自己。你同时成为信任者与被信任者。"},{"no":"03","title":"Certainty that something is true","titleCN":"确信：对事实或结果的把握","definition":"the state of being sure that a fact is true or that an outcome will happen","definitionCN":"确信某一事实为真、或某一结果将会发生的状态","example":"There is little confidence now that the ferry will run tomorrow.","exampleCN":"现在几乎没人相信渡轮明天会开。","why":"From the 1550s the word also means 'certainty of a fact'. The feeling of trust is transferred from people to propositions: I trust the report, therefore I am confident it is true.","whyCN":"从 16 世纪 50 年代起，这个词也指“对事实的确信”。信任的感觉从人转到命题上：我信任这份报告，所以我确信它是真的。"},{"no":"04","title":"A secret held in trust","titleCN":"知心话：托付给你的秘密","definition":"a private matter told to someone on the understanding that it will not be repeated","definitionCN":"在对方承诺不再外传的前提下，向其吐露的私事","example":"She kept his confidence for forty years and never once repeated it.","exampleCN":"她替他守了四十年的秘密，一次也没有外传。","why":"By the 1590s confidence means 'a secret'. A secret is the thing you hand over when you trust someone; the abstract feeling and the concrete object share one name.","whyCN":"到 16 世纪 90 年代，confidence 又指“秘密”。秘密就是你信任某人时交出去的那件东西；抽象的感受与具体的物件共用一个名字。"},{"no":"05","title":"Trust in a system or a market","titleCN":"对机构与市场的信心","definition":"public trust in the stability and reliability of an institution, currency, market or service","definitionCN":"公众对某一机构、货币、市场或服务的稳定与可靠所抱的信任","example":"Consumer confidence fell for the third month as prices continued to rise.","exampleCN":"随着物价持续上涨，消费者信心连续第三个月下滑。","why":"Trust can be placed in something impersonal. When many people trust a system at once, that trust becomes a measurable public mood: confidence in the banks, in the currency, in the government.","whyCN":"信任可以被放在非人的东西上。当许多人同时信任一个系统，这种信任就变成可测量的公共情绪：对银行、对货币、对政府的信心。"},{"no":"06","title":"A vote of confidence","titleCN":"政治信任：投票决定去留","definition":"in parliamentary politics, a formal vote showing whether members still support a government or leader","definitionCN":"在议会政治中，用以表明议员是否仍支持某届政府或某位领导人的正式表决","example":"The cabinet lost a vote of confidence by eleven votes and resigned the next morning.","exampleCN":"内阁以十一票之差输掉信任投票，次日上午辞职。","why":"Here confidence is the count of trust in a room. The phrase turns an inner feeling into a public number that can be won or lost.","whyCN":"这里的 confidence 是一次计票，数的是屋子里有多少信任。这个说法把内心的感受变成一个可以赢也可以输的公开数字。"},{"no":"07","title":"The confidence trick","titleCN":"信任骗局：先把信任骗到手","definition":"a fraud in which the victim is first made to trust the swindler, who then takes their money","definitionCN":"先让受害者信任骗子、再骗走其钱财的诈术","example":"The investment scheme was a confidence trick, and the neat office was only a stage set.","exampleCN":"那个投资项目是一场信任骗局，那间整洁的办公室不过是布景。","why":"A confidence man, recorded in 1849 and later shortened to con man, trades on the very trust the word names. The victim's confidence is the raw material he steals.","whyCN":"confidence man 记录于 1849 年，后来缩略为 con man；这种人靠的正是这个词所命名的信任。受害者的“信心”就是他偷走的原料。"},{"no":"08","title":"Statistical confidence","titleCN":"统计置信：概率意义上的把握","definition":"in statistics, the degree of certainty that an estimate or interval would contain the true value if the study were repeated","definitionCN":"统计学中，指若重复研究、估计值或区间会包含真实值的确定程度","example":"The survey reports its margin of error at a ninety-five per cent confidence level.","exampleCN":"这份调查在 95% 的置信水平上报告其误差范围。","why":"Certainty has to be given a number when it is used in science. Statistical confidence is the old sense 'certainty of a fact' made calculable.","whyCN":"当“确信”被用于科学时，就必须给出一个数字。统计置信就是把古老的“对事实的确信”变成可计算的东西。"},{"no":"09","title":"Bold assurance, sometimes too much","titleCN":"大胆的底气：有时近乎放肆","definition":"a bold or presumptuous kind of assurance, sometimes more than the situation justifies","definitionCN":"一种大胆甚至唐突的把握，有时超出情形的允许","example":"He had the confidence to correct the professor's arithmetic in front of the whole seminar.","exampleCN":"他竟有那份底气，在全班面前纠正教授的算术。","why":"When self-trust grows past its evidence, confidence becomes audacity. English keeps the same noun and lets the tone do the judging.","whyCN":"当自我信任超出证据所能支撑的范围，confidence 就变成放肆。英语不另造词，仍用同一个名词，让语气去做评判。"}],"etymology":{"intro":{"en":"Confidence came from Latin confidentia, from confidere 'to trust completely'. Its history is the history of trust: first in others, then in oneself, then in facts, then in numbers.","cn":"confidence 来自拉丁语 confidentia，出自 confidere“完全信任”。它的历史就是信任的历史：先信任他人，再信任自己，再信任事实，最后信任数字。"},"items":[{"era":"C. 1400","en":"First recorded meaning 'assurance or belief in another's good will'. The word begins as a social feeling, not a private one.","cn":"最早记录时意为“对他人善意的确信”。这个词一开始是一种社会性的感受，而不是私人的感受。"},{"era":"LATIN confidere","en":"Confidere means 'to have full trust': com- here is intensive, 'completely', plus fidere 'to trust'. The picture is leaning one's whole weight on someone.","cn":"confidere 意为“完全信任”：这里的 com- 是加强义“完全”，加上 fidere“信任”。画面是把整个重量都靠在某人身上。"},{"era":"PROTO-INDO-EUROPEAN","en":"Fidere goes back to PIE *bheidh- 'to trust, confide'. The same root gives fidelity, fiduciary, affidavit and diffidence.","cn":"fidere 可追溯到原始印欧语 *bheidh-“信任、托付”。同一词根给出 fidelity、fiduciary、affidavit、diffidence。"},{"era":"MID-15C. TO 1590S","en":"The word turns inward: 'self-assurance' by the mid-15th century, 'certainty of a fact' by the 1550s, and 'a secret' by the 1590s.","cn":"这个词转向内部：15 世纪中期有“自信”，16 世纪 50 年代有“对事实的确信”，16 世纪 90 年代有“秘密”。"},{"era":"1849","en":"Confidence man appears in American English, naming a swindler who wins his victim's trust before robbing him. It is shortened to con man, and confidence trick follows.","cn":"confidence man 出现在美式英语中，指先骗取受害者信任再行骗的人。它缩略为 con man，随后又有 confidence trick 的说法。"},{"era":"20C. TO TODAY","en":"The word spreads into politics and science: vote of confidence, consumer confidence, confidence interval. Modern English keeps the old feeling but measures it.","cn":"这个词扩展到政治与科学：信任投票、消费者信心、置信区间。现代英语保留了古老的感觉，却开始对它进行测量。"}]},"similar":{"note":{"en":"The first group separates the adjective, the adjective of secrecy, the noun of excess, and the near-homophone confidant; the second group compares four words for trusting and for feeling sure.","cn":"第一组区分形容词、表“机密”的形容词、表“过度”的名词，以及近音的 confidant；第二组比较四个表示“信任”与“有把握”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"confident","ipa":"/ˈkɒnfɪdənt/","tag":"adjective","definition":"sure of oneself or of a result. It is the adjective of confidence, and it describes the person, while confidence names the feeling.","definitionCN":"对自己或对结果有把握。它是 confidence 的形容词，形容人，而 confidence 命名那种感受本身。"},{"word":"confidential","ipa":"/kənˌfɪˈdenʃl/","tag":"secrecy, not self-belief","definition":"meant to be kept secret and shared only with a few people. It grows out of the 'secret' sense, not the 'self-assurance' sense, so a confidential report has nothing to do with being confident.","definitionCN":"应当保密、只在少数人之间传阅的。它由“秘密”义长出，而非“自信”义，因此 confidential report 与“自信”毫无关系。"},{"word":"overconfidence","ipa":"/ˌəʊvəˈkɒnfɪdəns/","tag":"excess","definition":"confidence beyond what the evidence supports, usually leading to mistakes. The prefix over- marks the point where self-trust stops being useful.","definitionCN":"超出证据所能支撑的自信，通常导致失误。前缀 over- 标出自信心开始变得有害的那条界线。"},{"word":"confidant","ipa":"/ˈkɒnfɪdænt/","tag":"near-homophone, different word","definition":"a person to whom one tells private matters; the feminine form is confidante. It is spelled with -ant, not -ent, and names the keeper of a secret rather than a feeling.","definitionCN":"可向其吐露私事的人；阴性形式为 confidante。它拼作 -ant 而非 -ent，命名的是秘密的保管者，而不是一种感受。"}]},{"heading":"NEAR MEANING","entries":[{"word":"trust","ipa":"/trʌst/","tag":"reliance on another","definition":"firm belief that someone is honest and reliable. Trust is usually placed in a person or an institution; confidence can also be placed in oneself or in a forecast.","definitionCN":"坚信某人诚实可靠。trust 通常放在人或机构上；confidence 还可以放在自己身上或一份预测上。"},{"word":"assurance","ipa":"/əˈʃʊərəns/","tag":"stated certainty","definition":"a confident statement or a feeling of certainty, often one given to someone else to calm them. It is more formal and more often spoken aloud than confidence.","definitionCN":"有把握的陈述或确定感，常是说来安抚别人的。它比 confidence 更正式，也更常被说出口。"},{"word":"faith","ipa":"/feɪθ/","tag":"belief without proof","definition":"belief that does not rest on proof, often religious. Faith accepts the absence of evidence; confidence normally expects the evidence to be there.","definitionCN":"不依赖证据的相信，常指宗教信仰。faith 接受证据的缺席；confidence 通常期待证据在场。"},{"word":"self-esteem","ipa":"/ˌself ɪˈstiːm/","tag":"self-worth","definition":"the overall value a person places on themselves. Self-esteem is a judgment of worth; confidence is a judgment about what one can do.","definitionCN":"一个人对自身价值的总体评价。self-esteem 是对“我值多少”的判断；confidence 是对“我能做到什么”的判断。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: com- 'completely', fidere 'trust', and the family confide, fidelity, diffidence.","cn":"只用真实成分与真实同族词：com-“完全”、fidere“信任”，以及 confide、fidelity、diffidence 这一族。"},"normal":[{"en":"fidere means 'trust'. Confidence is not 'having no doubt' in general; it is trusting something enough to lean on it.","cn":"fidere 意为“信任”。confidence 不是泛泛的“毫不怀疑”，而是信任到可以把重量靠上去。"},{"en":"Confident is the adjective, confidence the noun, and confide the verb: the feeling, the name of the feeling, and the act of handing a secret over.","cn":"confident 是形容词，confidence 是名词，confide 是动词：感受、感受的名称，以及把秘密交出去的动作。"},{"en":"Diffidence uses dis- plus fidere and means the opposite: a lack of trust in oneself.","cn":"diffidence 用 dis- 加 fidere，意义正相反：对自己缺乏信任。"},{"en":"Fidelity, fiduciary and affidavit all keep fidere: faithfulness, a relationship built on trust, and a sworn statement. Same root, three worlds.","cn":"fidelity、fiduciary、affidavit 都保留 fidere：忠诚、建立在信任上的受托关系、宣誓书。同一词根，三个世界。"},{"en":"Confidential is about secrets, not self-belief. A confidential envelope and a confident speaker share letters, not meaning.","cn":"confidential 说的是秘密，不是自信。一个机密信封和一位自信的演讲者只是共享字母，并不共享意义。"}],"abstract":[{"en":"Picture a person handing their heart over to another pair of hands, then standing straighter because it is held safely.","cn":"想象一个人把自己的心交到另一双手里，然后因为被稳稳接住而站得更直。"},{"en":"Then hand it to yourself: that is self-confidence. Hand it to a bank, a government or a forecast: that is public confidence.","cn":"然后把它交给自己：这就是自信。把它交给银行、政府或一份预测：这就是公共信心。"},{"en":"There is a dark twin. The confidence man asks for your trust first, and the thing he steals is exactly the thing the word names.","cn":"还有一个阴暗的孪生义。骗子先向你要信任，而他偷走的东西，正是这个词所命名的那样东西。"}]},"examples":[{"en":"Years of practice gave her the confidence to speak without notes.","cn":"多年的练习给了她不用讲稿也能讲话的自信。"},{"en":"He told me in confidence that the merger had already been signed.","cn":"他私下告诉我，那桩合并已经签了。"},{"en":"Investors' confidence returned only after the central bank changed its tone.","cn":"直到央行改变口风，投资者的信心才回来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“肯费等事”——肯为一件还没发生的事费心等待，是因为心里有底 → confidence 信心；把握","word":"confidence"},"root":"源自拉丁语 confidere“完全信任”，由 com-（加强）+ fidere“信任”构成，核心是“把心交托出去，因而站得稳”。","sensesIntro":{"en":"Nine senses of confidence, all versions of one act: handing your weight to something and finding that it holds. The holder may be a person, yourself, a fact, a market, a parliament, or a number.","cn":"confidence 的九个义项都是同一个动作的变体：把重量交给某样东西，并发现它接得住。承接者可以是某个人、你自己、一个事实、一个市场、一个议会，或一个数字。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person hands their weight to something and finds that it holds.","cn":"核心意象：一个人把重量交给某样东西，并发现它接得住。"},"chain":["TRUST FULLY","PLACE ONE'S HEART","FEEL SECURE","BELIEVE WITHOUT DOUBT","KEEP A SECRET","MEASURE THE CERTAINTY"],"branches":[{"senses":"S1 · S5","en":"TRUST IN OTHERS: trust placed in a person, and trust placed by many people at once in a bank, a currency or a service.","cn":"对他者的信任：放在一个人身上的信任，以及许多人同时放在银行、货币或服务上的信任。"},{"senses":"S2 · S9","en":"SELF-TRUST: the same leaning, now toward oneself, which can grow into audacity when the ground gives way.","cn":"自我信任：同一个倚靠动作转向自己，当地基不牢时就长成放肆。"},{"senses":"S3 · S8","en":"CERTAINTY: trust in a fact, then trust given a number in a confidence interval.","cn":"确信：对事实的信任，随后是被赋予数字的置信区间。"},{"senses":"S4","en":"THE SECRET: the object handed over when trust is given, and the reason confidentiality is a separate word.","cn":"秘密：给出信任时交出的那件东西，也是 confidentiality 另立一词的原因。"},{"senses":"S6 · S7","en":"TRUST PUT TO WORK: a parliament counts it, and a con man steals it.","cn":"被利用的信任：议会去数它，骗子去偷它。"}]},"affixes":{"intro":{"en":"Confidence is built from Latin pieces that are still readable: com- 'completely' plus fidere 'trust', with the noun ending -entia. English adds -ial, -ality and over-.","cn":"confidence 由仍可读的拉丁成分构成：com-“完全”加 fidere“信任”，再加名词词尾 -entia。英语又加上 -ial、-ality 和 over-。"},"latinIntro":{"en":"The Latin family is confidere 'trust fully', confidentia 'confidence', fidere 'trust' and fides 'faith'. English also took fidere through French shapes such as fidelity and fiduciary.","cn":"这一拉丁词族包括 confidere“完全信任”、confidentia“信心”、fidere“信任”和 fides“信义”。英语还通过法语词形借入 fidelity、fiduciary 等词。"},"items":[{"word":"confidently","structure":"confident + -ly (adverb)","meaning":"in a sure, self-assured way","meaningCN":"自信地；有把握地（-ly 构成副词）","example":"She confidently predicted that the vote would pass.","exampleCN":"她自信地预测表决会通过。"},{"word":"confidential","structure":"confidence + -ial (adjective)","meaning":"intended to be kept secret","meaningCN":"机密的；保密的（-ial 构成形容词）","example":"The report was marked confidential and locked in a drawer.","exampleCN":"报告被标为机密，锁进了抽屉。"},{"word":"confidentiality","structure":"confidential + -ity (quality noun)","meaning":"the state of being kept secret","meaningCN":"保密性；机密性","example":"Doctors are bound by confidentiality even after a patient dies.","exampleCN":"即使病人去世，医生仍受保密义务约束。"},{"word":"confide","structure":"con- (completely) + fidere (trust)","meaning":"to tell a secret to someone you trust","meaningCN":"向信任的人吐露秘密；托付","example":"He confided his plans to no one but his brother.","exampleCN":"除了弟弟，他没向任何人吐露自己的计划。"},{"word":"confidant","structure":"con- + fidere + -ant (person)","meaning":"a person trusted with private matters","meaningCN":"知心人；可托付秘密的人（-ant 表示人）","example":"The president's confidant sat outside the meeting room.","exampleCN":"总统的知心人坐在会议室门外。"},{"word":"overconfidence","structure":"over- (too much) + confidence","meaning":"excessive belief in one's own ability","meaningCN":"过度自信（over- 表示“过分”）","example":"Overconfidence before the final exam cost him the scholarship.","exampleCN":"期末考前过度自信让他丢掉了奖学金。"},{"word":"diffidence","structure":"dis- (away) + fidere (trust) + -ence","meaning":"a lack of trust in oneself; shyness","meaningCN":"缺乏自信；羞怯（dis- 表示“离开”）","example":"His diffidence made it hard for him to ask for help.","exampleCN":"缺乏自信让他很难开口求助。"},{"word":"fidelity","structure":"fides (faith) + -ity","meaning":"faithfulness; exactness of a copy","meaningCN":"忠诚；（复制、录音的）保真度","example":"The recording reproduces the piano with remarkable fidelity.","exampleCN":"这段录音以惊人的保真度还原了钢琴声。"},{"word":"fiduciary","structure":"fidere + -ary (person or relation)","meaning":"relating to a relationship of trust, as between a trustee and a beneficiary","meaningCN":"受托的；信托的（建立在信任关系上）","example":"A bank has a fiduciary duty to act in the client's interest.","exampleCN":"银行负有受托责任，须按客户利益行事。"},{"word":"affidavit","structure":"af- (to) + fidere (trust) + -avit (he has sworn)","meaning":"a written statement confirmed by oath","meaningCN":"宣誓书；书面誓词（字面为“他已宣誓”）","example":"She signed an affidavit describing what she had seen.","exampleCN":"她签署了一份宣誓书，描述她所见的一切。"}],"latinEntries":[{"word":"fidere","structure":"PIE *bheidh- 'trust' + Latin verb stem","meaning":"to trust, have confidence in","meaningCN":"信任；信赖"},{"word":"fides","structure":"same root as fidere, noun","meaning":"faith, trust, faithfulness","meaningCN":"信义；信任；忠诚"},{"word":"confidere","structure":"con- (completely) + fidere (trust)","meaning":"to trust fully, rely on","meaningCN":"完全信任；倚靠"},{"word":"confidentia","structure":"confidere + -entia (state noun)","meaning":"confidence, assurance","meaningCN":"信心；确信"}]}},{"word":"confirm","ipa_uk":"/kənˈfɜːm/","ipa_us":"/kənˈfɜːrm/","definition_zh":"确认；证实；批准；使坚定；施坚振礼","definition_en":"to establish that something is true or definite, to give formal approval to something, or to make someone firmer in a belief or a decision","core_image":"把一根已经立起来的柱子再钉牢，让它晃不动","scene":"A second blood test confirmed the diagnosis that the first had only suggested.","sceneCN":"这里 confirm 是「证实、确认」（第 2 个义项：把一件尚未确定的事变成确定的事实）；句意：第二次验血证实了第一次只是提示出的诊断。场景要点：同一结论被第二次证据钉牢，从此不再是猜测。","pos":[{"tag":"v.","zh":"确认；证实；证明"},{"tag":"v.","zh":"批准；认可；使坚定"}],"collocations":[{"phrase":"confirm a booking","zh":"确认预订"},{"phrase":"confirm a diagnosis","zh":"确诊；证实诊断"},{"phrase":"confirm suspicions","zh":"证实猜疑"},{"phrase":"confirm that the report is accurate","zh":"确认报告准确无误"},{"phrase":"confirm someone in office","zh":"批准某人就职"},{"phrase":"confirm a theory","zh":"证实一种理论"}],"forms":[{"label":"第三人称单数","form":"confirms"},{"label":"过去式","form":"confirmed"},{"label":"过去分词","form":"confirmed"},{"label":"现在分词","form":"confirming"}],"derivatives":[{"word":"confirmation","pos":"n.","zh":"确认；证实；批准；（宗教）坚振礼"},{"word":"confirmed","pos":"adj.","zh":"已确认的；顽固的、根深蒂固的"},{"word":"confirmatory","pos":"adj.","zh":"证实性的；起确认作用的"},{"word":"confirmable","pos":"adj.","zh":"可确认的；可证实的"},{"word":"unconfirmed","pos":"adj.","zh":"未经证实的"},{"word":"disconfirm","pos":"v.","zh":"证伪；否定（某一假设）"}],"senses":[{"no":"01","title":"Making valid by a legal act","titleCN":"依法批准：使正式生效","definition":"to give formal or legal validity to an agreement, treaty or act, so that it is binding","definitionCN":"使协议、条约或行为获得正式或法律上的效力，从而具有约束力","example":"The senate confirmed the treaty by a narrow majority after two days of debate.","exampleCN":"经过两天辩论，参议院以微弱多数批准了这项条约。","why":"The earliest English sense, from the mid-13th century, is 'ratify, make valid by legal act'. Latin confirmare is 'make firm', and a ratified treaty is one that can no longer be shaken.","whyCN":"英语最早的义项（13 世纪中期）就是“批准、以法律行为使之生效”。拉丁语 confirmare 意为“使坚固”，被批准的条约就是一份再也晃不动的文件。"},{"no":"02","title":"Making a fact certain","titleCN":"把事实钉死：证实","definition":"to establish that something is true by providing further evidence","definitionCN":"通过提供进一步的证据，确立某事为真","example":"A second blood test confirmed the diagnosis that the first had only suggested.","exampleCN":"第二次验血证实了第一次只是提示出的诊断。","why":"By the late 14th century the word also means 'make certain, verify'. A suspicion standing on one leg is given a second leg, and then it stands.","whyCN":"到 14 世纪晚期，这个词也指“使之确定、核实”。一条腿站着的猜测被装上第二条腿，于是它站稳了。"},{"no":"03","title":"Proving a suspicion right","titleCN":"坐实猜疑：担心的事被证实","definition":"to show that something already suspected or feared is in fact true","definitionCN":"表明原本已被怀疑或担心的事确实为真","example":"The footprints confirmed what the rangers had feared since the first snowfall.","exampleCN":"那些脚印坐实了护林员自初雪以来一直担心的事。","why":"Confirm usually follows a suspicion rather than creates one. The evidence does not open a question; it closes one that was already half open, and that is why the verb so often collocates with fears and suspicions.","whyCN":"confirm 通常是跟着猜疑走，而不是制造猜疑。证据不是打开一个问题，而是合上一个已经半开的问题——这也是为什么这个动词常与担忧、猜疑搭配。"},{"no":"04","title":"Approving an appointment","titleCN":"批准任命：让职位正式落定","definition":"to formally approve a person for an office, post or position","definitionCN":"正式认可某人担任某项职务、职位或岗位","example":"The council confirmed her as the new director in a closed session.","exampleCN":"理事会在闭门会议中批准她出任新所长。","why":"An appointment is valid only when the proper body makes it firm. Here the thing being steadied is not a fact but a person's standing in an office.","whyCN":"任命只有在主管机构把它“钉牢”之后才有效。这里被稳住的东西不是一个事实，而是某人在职位上的地位。"},{"no":"05","title":"The religious rite of confirmation","titleCN":"宗教：坚振礼与信仰的确认","definition":"in Christian practice, to admit a baptised person into full membership through the rite of confirmation","definitionCN":"在基督教实践中，通过坚振礼接纳已受洗者成为正式成员","example":"She was confirmed at fourteen and has kept the promise seriously ever since.","exampleCN":"她十四岁受坚振礼，此后一直认真守着那个承诺。","why":"Confirmation as a rite is recorded around 1300. The bishop strengthens what baptism began: the faith is already there, and the rite makes it firm.","whyCN":"作为仪式的 confirmation 约在 1300 年有记录。主教把洗礼所开始的事加固：信仰本已存在，仪式使它坚固。"},{"no":"06","title":"Strengthening someone in a belief","titleCN":"使某人更坚定：把决心压实","definition":"to make a person firmer in an opinion, belief or course of action","definitionCN":"使某人在某种看法、信念或行动路线上更加坚定","example":"The rejection confirmed him in his decision to leave the firm.","exampleCN":"那次拒绝让他更坚定了离开公司的决定。","why":"The Latin verb could strengthen a person, not only a fact. When evidence confirms you in a view, it presses down on a resolve that already exists and makes it harder to move.","whyCN":"这个拉丁动词也能加固一个人，而不只是加固一个事实。当证据 confirm you in a view，它压在一个已经存在的决心上，使其更难动摇。"},{"no":"07","title":"Confirming a booking","titleCN":"确认预订：把约定锁定","definition":"in commercial use, to state officially that a reservation, order or arrangement is definitely going ahead","definitionCN":"在商业用法中，正式说明预订、订单或安排确定会进行","example":"Please confirm your reservation by email within seven days, or the room will be released.","exampleCN":"请在七天内用邮件确认预订，否则房间将被释放。","why":"A booking is a verbal arrangement until someone makes it firm in writing. The modern commercial sense is the old 'make valid' applied to a hotel room instead of a treaty.","whyCN":"预订在有人以书面形式把它钉牢之前，只是口头安排。这一现代商业义就是把古老的“使之有效”用在酒店房间上，而不是用在条约上。"},{"no":"08","title":"Confirming a hypothesis","titleCN":"实验证实：假设获得支持","definition":"in science, to show by observation or experiment that a prediction holds","definitionCN":"在科学中，通过观察或实验表明某一预测成立","example":"The second run of the experiment confirmed the first result under different conditions.","exampleCN":"第二次实验在不同条件下证实了第一次的结果。","why":"Science prefers 'support' to 'prove', but confirm remains the everyday verb for a prediction that survives a test. The result makes the hypothesis firm enough to build on.","whyCN":"科学界更爱说“支持”而不是“证明”，但 confirm 仍是描述“预测通过了检验”的日常动词。结果使假设坚固到足以在上面继续搭建。"},{"no":"09","title":"Corroborating a witness","titleCN":"印证证词：让第二个声音对上","definition":"in legal use, to support a witness's account with independent evidence","definitionCN":"在法律用法中，用独立证据支持某位证人的陈述","example":"A second witness confirmed her account of the night of the fire.","exampleCN":"第二位证人印证了她对火灾那一夜的陈述。","why":"Two voices saying the same thing is firmer than one. In court the word marks the moment when testimony stops being one person's word and becomes a supported account.","whyCN":"两个声音说同一件事，比一个声音更牢。在法庭上，这个词标记的是证词不再只是一个人的话、而成为有支持的陈述的那一刻。"}],"etymology":{"intro":{"en":"Confirm came from Latin confirmare 'make firm', through Old French. Its two oldest jobs, ratifying and verifying, are both ways of making something steady.","cn":"confirm 经古法语来自拉丁语 confirmare“使坚固”。它最古老的两项职能——批准与证实——都是让某样东西变稳的方式。"},"items":[{"era":"MID-13C.","en":"First recorded meaning 'ratify, make valid by legal act'. The word enters through Old French confermer, already carrying the legal sense.","cn":"最早记录时意为“批准、以法律行为使之生效”。这个词经古法语 confermer 进入英语，已带着法律义。"},{"era":"LATIN confirmare","en":"Confirmare means 'make firm, strengthen': com- is intensive, plus firmare 'to make firm', from firmus 'strong, steady'. The image is a post driven deeper into the ground.","cn":"confirmare 意为“使坚固、加强”：com- 是加强义，加上 firmare“使坚固”，后者出自 firmus“强壮、稳固”。画面是一根被钉得更深的柱子。"},{"era":"PROTO-INDO-EUROPEAN","en":"Firmus goes back to PIE *dher- 'to hold firmly, support'. The same reconstructed root underlies firm, firmament, affirm and infirm.","cn":"firmus 可追溯到原始印欧语 *dher-“牢牢握住、支撑”。同一重构词根也是 firm、firmament、affirm、infirm 的来源。"},{"era":"LATE 14C.","en":"A second sense appears: 'make certain, verify'. From here grow the modern uses in diagnosis, science and everyday arrangement.","cn":"第二个义项出现：“使之确定、核实”。现代用法中的诊断、科研与日常约定都从这里长出来。"},{"era":"C. 1300","en":"Confirmation is recorded as the name of the religious rite. The noun is older than many of the verb's modern senses and keeps its own ceremonial life.","cn":"confirmation 约在 1300 年被记录为宗教仪式的名称。这个名词比动词的许多现代义项都更老，并保有自己的仪式生命。"},{"era":"MODERN ENGLISH","en":"Modern English confirms facts, bookings, appointments and hypotheses. Keep it apart from conform, which comes from forma 'shape' and means 'fit the shape of'.","cn":"现代英语确认事实、预订、任命与假设。要把它与 conform 分开：后者来自 forma“形状”，意为“与某形状相符”。"}]},"similar":{"note":{"en":"The first group exists mainly to stop one confusion: confirm is firmus 'firm', while conform is forma 'shape'. The second group lines up the four verbs closest in meaning.","cn":"第一组的存在主要是为了防止一个混淆：confirm 的词根是 firmus“坚固”，而 conform 的词根是 forma“形状”。第二组排列四个意义最接近的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conform","ipa":"/kənˈfɔːm/","tag":"different root: forma","definition":"to behave according to a rule, standard or expectation. Its root is Latin forma 'shape, form', not firmus 'firm', so conform means 'take the same shape as', not 'make firm'. The two words look like twins and are not even cousins.","definitionCN":"按照规则、标准或期望行事。它的词根是拉丁语 forma“形状、形式”，不是 firmus“坚固”，因此 conform 意为“与……取同一形状”，而不是“使坚固”。这两个词看着像双胞胎，其实连表亲都不是。"},{"word":"confirmation","ipa":"/ˌkɒnfəˈmeɪʃn/","tag":"derived noun","definition":"the act of confirming, or a statement that proves something. It also names the religious rite, a sense fixed by about 1300.","definitionCN":"确认的行为，或证明某事的陈述。它还指宗教上的坚振礼，这一义项约在 1300 年固定下来。"},{"word":"confirmed","ipa":"/kənˈfɜːmd/","tag":"past participle as adjective","definition":"proved to be true, or long established in a habit, as in 'a confirmed bachelor'. The second use has drifted from 'verified' toward 'fixed and unlikely to change'.","definitionCN":"已被证明为真的，或长期固定于某种习惯的，如 a confirmed bachelor（抱定独身的人）。第二种用法已从“被证实”漂移到“已定型、不易改变”。"},{"word":"affirm","ipa":"/əˈfɜːm/","tag":"same root, other prefix","definition":"to state something as true or to uphold it formally. It shares firmus with confirm but its prefix ad- 'to' gives the sense of speaking toward a claim, not of making it firm.","definitionCN":"宣称某事为真，或正式予以维护。它与 confirm 共享 firmus，但前缀 ad-“朝向”给出的是“对着一个主张说话”，而不是“使之坚固”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"verify","ipa":"/ˈverɪfaɪ/","tag":"check against evidence","definition":"to check something carefully to see whether it is true. It stresses the checking procedure, while confirm stresses the resulting certainty.","definitionCN":"仔细核查某事是否真实。它强调核查的程序，而 confirm 强调由此得到的确定。"},{"word":"corroborate","ipa":"/kəˈrɒbəreɪt/","tag":"second source","definition":"to support a statement with additional independent evidence. It is narrower and more formal than confirm and almost always implies a second source.","definitionCN":"用额外的独立证据支持某项陈述。它比 confirm 更窄、更正式，几乎总意味着有第二个来源。"},{"word":"ratify","ipa":"/ˈrætɪfaɪ/","tag":"legal approval only","definition":"to give formal legal approval to an agreement so that it becomes binding. It covers only the legal branch of confirm, never the 'check a fact' branch.","definitionCN":"对协议给予正式法律批准，使其具有约束力。它只覆盖 confirm 的法律分支，绝不覆盖“核对事实”的分支。"},{"word":"validate","ipa":"/ˈvælɪdeɪt/","tag":"make officially acceptable","definition":"to prove or declare something valid, often by an authority or a test. It looks at whether something meets a standard; confirm looks at whether it is true.","definitionCN":"证明或宣布某事有效，常由权威机构或检验来完成。它关心的是“是否达标”，confirm 关心的是“是否属实”。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: com- 'completely', firmus 'firm', and the pair affirm / infirm. Conform is the false friend to keep out.","cn":"只用真实成分与真实同族词：com-“完全”、firmus“坚固”，以及 affirm／infirm 这对同根词。conform 是要挡在门外的假朋友。"},"normal":[{"en":"firmus means 'firm'. Confirm is to make firm: a fact, a booking, an appointment or a person's resolve.","cn":"firmus 意为“坚固”。confirm 就是使坚固：一个事实、一次预订、一项任命，或一个人的决心。"},{"en":"Affirm and infirm use the same root with different prefixes: to speak a claim forward, or to be not firm.","cn":"affirm 与 infirm 用同一词根配不同前缀：把主张朝前说出来，或者“不坚固”。"},{"en":"Conform is from forma 'shape'. It means 'take the same shape as a rule', so it belongs in a different family and a different meaning.","cn":"conform 来自 forma“形状”。它意为“取与规则相同的形状”，因此属于另一个词族、另一个意义。"},{"en":"Confirmation is both a certificate and a church rite: one makes a fact firm, the other makes a faith firm.","cn":"confirmation 既是证书也是教堂仪式：一个把事实钉牢，一个把信仰加固。"},{"en":"Unconfirmed means the second leg has not arrived yet. The claim is still standing on one leg.","cn":"unconfirmed 意味着第二条腿还没到。那个说法仍然只有一条腿站着。"}],"abstract":[{"en":"Picture a wooden post standing in soft ground. Someone drives it deeper with a mallet. Confirm is that last blow.","cn":"想象一根木柱立在松软的地里。有人用木槌把它钉得更深。confirm 就是最后那一击。"},{"en":"The post can be a fact, a booking, a treaty, a bishop's appointment, or a person's decision to leave. The blow is the same.","cn":"这根柱子可以是一个事实、一次预订、一份条约、主教的任命，或一个人离开的决定。那一击是一样的。"},{"en":"Keep the image away from conform: one word drives a post into the ground, the other pours material into a mould. Firm versus shape.","cn":"把意象与 conform 分开：一个词把柱子钉进地里，另一个词把材料倒进模子。坚固对形状。"}]},"examples":[{"en":"The airline confirmed the flight would leave two hours late.","cn":"航空公司确认航班将晚点两小时起飞。"},{"en":"New evidence confirmed the theory that the site had been a Roman fort.","cn":"新证据证实了这处遗址曾是罗马堡垒的推测。"},{"en":"Her appointment was confirmed by the board on Friday morning.","cn":"她的任命在周五上午获得董事会批准。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“肯费木”——肯费木料把门框钉牢，钉子一进去才算确认 → confirm 确认；使牢固","word":"confirm"},"root":"源自拉丁语 confirmare“使坚固”，由 com-（加强）+ firmare < firmus“坚固”构成，核心是“把已立起来的东西再钉牢”。","sensesIntro":{"en":"Nine senses of confirm, all one action: a post is made firm. What the post is changes by context, a treaty, a fact, a suspicion, an appointment, a faith, a resolve, a booking, a hypothesis or a witness.","cn":"confirm 的九个义项都是同一个动作：把柱子钉牢。柱子是什么随语境而变——条约、事实、猜疑、任命、信仰、决心、预订、假设，或一位证人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a standing post is driven deeper until it cannot wobble.","cn":"核心意象：一根立着的柱子被钉得更深，直到晃不动。"},"chain":["MAKE FIRM","HOLD STEADY","PROVE TRUE","GIVE FORMAL ASSENT","STRENGTHEN IN BELIEF","SETTLED BEYOND DOUBT"],"branches":[{"senses":"S1 · S4 · S7","en":"FORMAL ASSENT: a treaty, an appointment or a booking becomes binding because an authority makes it firm.","cn":"正式认可：条约、任命或预订因权威使之坚固而具有约束力。"},{"senses":"S2 · S8 · S9","en":"VERIFICATION: a diagnosis, a hypothesis or a witness is supported by a second line of evidence and then stands.","cn":"核实：诊断、假设或证词得到第二条证据线的支撑，于是站住。"},{"senses":"S3","en":"FEAR CONFIRMED: the evidence does not open a question but closes one that was already half open.","cn":"担忧被坐实：证据不是打开一个问题，而是合上一个已经半开的问题。"},{"senses":"S5","en":"RITE: baptism began the faith, and confirmation makes it firm in the church's presence.","cn":"仪式：洗礼开始了信仰，坚振礼在教会面前把它加固。"},{"senses":"S6","en":"RESOLVE: the post is a person, and the blow makes a decision harder to undo.","cn":"决心：柱子是一个人，那一击让一个决定更难撤销。"}]},"affixes":{"intro":{"en":"Confirm is built from com- 'completely' plus firmare 'make firm', from firmus. English adds -ation, -ed, -atory and the negative prefixes un- and dis-.","cn":"confirm 由 com-“完全”加 firmare“使坚固”（出自 firmus）构成。英语再加 -ation、-ed、-atory，以及否定前缀 un- 和 dis-。"},"latinIntro":{"en":"The Latin family is firmus 'firm', firmare 'make firm', confirmare 'strengthen' and affirmare 'assert'. English also keeps firmament, the 'firm' vault of the sky.","cn":"这一拉丁词族包括 firmus“坚固”、firmare“使坚固”、confirmare“加强”和 affirmare“断言”。英语还保留了 firmament，即天空那层“坚固”的穹顶。"},"items":[{"word":"confirmation","structure":"confirm + -ation (action noun)","meaning":"the act of confirming; a proof; also the religious rite","meaningCN":"确认；证实；证明；（宗教）坚振礼","example":"We are still waiting for confirmation of the room number.","exampleCN":"我们仍在等待房间号的确认。"},{"word":"confirmed","structure":"confirm + -ed (past participle)","meaning":"proved true; also fixed in a habit","meaningCN":"已确认的；已定型的、根深蒂固的","example":"The confirmed schedule leaves no room for a second speaker.","exampleCN":"已确认的日程里没有第二位发言人的位置。"},{"word":"confirmatory","structure":"confirm + -atory (adjective)","meaning":"serving to confirm or support","meaningCN":"证实性的；起确认作用的（-atory 构成形容词）","example":"A confirmatory test is run before any result is announced.","exampleCN":"任何结果公布前都要做一次验证性检测。"},{"word":"confirmable","structure":"confirm + -able (able to be)","meaning":"able to be checked and shown to be true","meaningCN":"可确认的；可证实的","example":"The claim is confirmable with a single phone call.","exampleCN":"这个说法打一个电话就能核实。"},{"word":"unconfirmed","structure":"un- (not) + confirmed","meaning":"not yet verified","meaningCN":"未经证实的（un- 表示否定）","example":"Reports of a second delay remain unconfirmed.","exampleCN":"关于再次延期的报道仍未获证实。"},{"word":"disconfirm","structure":"dis- (apart, opposite) + confirm","meaning":"to show that a hypothesis is false","meaningCN":"证伪；否定某一假设（dis- 表示相反）","example":"One failed prediction is enough to disconfirm the rule.","exampleCN":"一次失败的预测就足以证伪这条规则。"},{"word":"affirm","structure":"af- (to) + firmare (make firm)","meaning":"to state a claim firmly","meaningCN":"断言；坚定地声明（同一 firmus 词根，前缀不同）","example":"The court affirmed the earlier ruling.","exampleCN":"法院维持了先前的裁决。"},{"word":"affirmative","structure":"affirm + -ative (adjective)","meaning":"expressing agreement or a yes","meaningCN":"肯定的；赞同的","example":"She gave an affirmative nod and wrote the number down.","exampleCN":"她肯定地点了下头，把号码记了下来。"},{"word":"firm","structure":"firmus (strong, steady)","meaning":"solid, steady, not likely to move","meaningCN":"坚固的；稳固的；坚定的","example":"Plant the stake on firm ground, not in the sand.","exampleCN":"把桩子插在坚实的地上，别插在沙里。"},{"word":"firmness","structure":"firm + -ness (quality noun)","meaning":"the quality of being steady or unyielding","meaningCN":"坚固；坚定（-ness 构成性质名词）","example":"The firmness of the mattress surprised him.","exampleCN":"床垫的硬度让他吃了一惊。"},{"word":"infirm","structure":"in- (not) + firmus (firm)","meaning":"weak, especially through age or illness","meaningCN":"虚弱的（in- 否定 + firmus 坚固）","example":"The infirm passengers boarded first.","exampleCN":"体弱的乘客先登机。"},{"word":"conform","structure":"con- (together) + formare, from forma (shape)","meaning":"to take the same shape as a rule or group; to comply","meaningCN":"遵从；与……一致（词根是 forma“形状”，与 firmus 无关）","example":"All new buildings must conform to the fire code.","exampleCN":"所有新建筑都必须符合消防规范。"}],"latinEntries":[{"word":"firmus","structure":"PIE *dher- 'hold firmly' + Latin adjective","meaning":"strong, steady, solid","meaningCN":"坚固的；稳固的；结实的"},{"word":"firmare","structure":"firmus + -are (verb)","meaning":"to make firm, strengthen, secure","meaningCN":"使坚固；加强；固定"},{"word":"confirmare","structure":"con- (completely) + firmare (make firm)","meaning":"to make firm, strengthen, ratify","meaningCN":"使坚固；加强；批准"},{"word":"affirmare","structure":"ad- (to) + firmare (make firm)","meaning":"to assert, declare firmly","meaningCN":"断言；坚定地宣布"}]}},{"word":"conflict","ipa_uk":"/ˈkɒnflɪkt/","ipa_us":"/ˈkɑːnflɪkt/","definition_zh":"冲突；抵触；矛盾；争斗（动词：相冲突、相抵触）","definition_en":"a serious disagreement or state of opposition between people, ideas or forces; also, to be in opposition or to clash","core_image":"两股力量在同一处迎面撞上，金属相击、火花四溅","scene":"The two meetings were in direct conflict, and the manager had to decide which one to attend.","sceneCN":"这里 conflict 是「（时间安排上的）冲突、撞车」（第 5 个义项：两件事无法同时兼顾）；句意：两个会议时间直接冲突，经理必须决定参加哪一个。场景要点：同一个下午、两场会议、同一个经理，只能去一处。","pos":[{"tag":"n.","zh":"冲突；抵触；矛盾；争斗"},{"tag":"v.","zh":"相冲突；相抵触；与……不一致"}],"collocations":[{"phrase":"armed conflict","zh":"武装冲突"},{"phrase":"come into conflict with","zh":"与……发生冲突"},{"phrase":"a conflict of interest","zh":"利益冲突"},{"phrase":"resolve a conflict","zh":"化解冲突"},{"phrase":"be in conflict with","zh":"与……相抵触、相矛盾"},{"phrase":"a conflict over resources","zh":"关于资源的争执"}],"forms":[{"label":"名词复数","form":"conflicts"},{"label":"动词第三人称单数","form":"conflicts"},{"label":"动词过去式","form":"conflicted"},{"label":"动词过去分词","form":"conflicted"},{"label":"动词现在分词","form":"conflicting"}],"derivatives":[{"word":"conflicting","pos":"adj.","zh":"相互矛盾的；相抵触的"},{"word":"conflicted","pos":"adj.","zh":"内心矛盾的；左右为难的"},{"word":"conflictual","pos":"adj.","zh":"冲突性的；充满对立的"},{"word":"conflictive","pos":"adj.","zh":"易引起冲突的；对抗性的"},{"word":"conflict-free","pos":"adj.","zh":"无冲突的；不涉及争端的"}],"senses":[{"no":"01","title":"Two forces meet in battle","titleCN":"两军相接：武装遭遇","definition":"a fight or armed encounter between opposing forces","definitionCN":"敌对双方之间的一场交战或武装遭遇","example":"The border conflict lasted three days and displaced thousands of villagers.","exampleCN":"那场边境冲突持续了三天，使数千村民流离失所。","why":"Latin conflictus was literally 'a striking together'. Two bodies driven at each other make one sound at the moment of impact, and early English used the word for exactly that battlefield meeting.","whyCN":"拉丁语 conflictus 字面就是“撞在一起”。两股力量迎面对撞，在接触的一瞬间发出同一个声响；早期英语正是用这个词指战场上那次相遇。"},{"no":"02","title":"A serious disagreement between people","titleCN":"人与人之间的严重分歧","definition":"a serious argument or disagreement between individuals or groups","definitionCN":"个人或群体之间的严重争吵或分歧","example":"The conflict between the two departments began over a single shared budget line.","exampleCN":"两个部门之间的冲突，起因只是预算表上同一行数字。","why":"When the impact is verbal instead of physical, the same collision shows up as two people pushing opposite claims at each other until neither can move forward.","whyCN":"当撞击从身体转向言语，同一场相撞就表现为两个人各推着一套相反的主张顶在一起，谁也前进不了。"},{"no":"03","title":"Ideas that cannot both be true","titleCN":"观念相斥：两者无法并存","definition":"an incompatibility between principles, statements, or accounts that cannot all hold at once","definitionCN":"原则、说法或叙述之间无法同时成立的互斥状态","example":"There is a conflict between the report's promise of privacy and its demand for total data access.","exampleCN":"报告一边承诺保护隐私，一边要求获取全部数据，二者存在冲突。","why":"Two principles driven at each other cannot occupy the same sentence: the word marks the exact point where they refuse to fit together. English recorded this as 'discord of principles' in 1875.","whyCN":"两条原则迎面顶住，就无法占据同一个句子：这个词标记的正是它们无法嵌合的那一点。英语在 1875 年把它记作“原则上的不合”。"},{"no":"04","title":"Inner conflict: incompatible urges","titleCN":"内心冲突：彼此不容的冲动","definition":"a struggle inside one person between desires, duties, or beliefs that cannot both be satisfied","definitionCN":"一个人内心在欲望、责任或信念之间的挣扎，两者无法同时满足","example":"He felt a conflict between wanting to speak and fearing the answer.","exampleCN":"他既想开口，又害怕听到答案，内心十分冲突。","why":"The battlefield is moved indoors: two forces still strike together, but now both of them are inside one chest, so there is no outside enemy to blame.","whyCN":"战场被搬进了室内：两股力量依然撞在一起，只是现在都装在同一个胸腔里，因此没有外面的敌人可以归咎。"},{"no":"05","title":"Clash of schedules or demands","titleCN":"安排撞车：时间与需求相冲突","definition":"a situation in which two events, appointments, or demands fall on the same time or resource","definitionCN":"两件事、两个约会或两项需求落在同一时间或同一资源上的情形","example":"The conference date is in conflict with the final exam.","exampleCN":"会议日期与期末考试时间冲突。","why":"A calendar is a small field of forces: two appointments that land in the same hour collide, and no arrangement can make both stand in one slot.","whyCN":"日历就是一片小小的力场：两个约会落在同一个小时里就会相撞，再怎么安排也无法让两者站在同一个格子里。"},{"no":"06","title":"Conflict of interest: two roles in one decision","titleCN":"利益冲突：一个决定里坐着两个角色","definition":"a situation in which a person's private interest could improperly influence a public or professional duty","definitionCN":"某人的私人利益可能不当影响其公共或职业职责的情形","example":"The judge stepped down because of a conflict of interest: her brother owned the company on trial.","exampleCN":"那位法官因利益冲突而回避：受审公司的老板是她的兄弟。","why":"Here two loyalties are driven toward a single decision, and the collision is between roles rather than bodies. English fixed the phrase 'conflict of interest' in 1743.","whyCN":"这里被赶向同一个决定的是两份忠诚，撞在一起的是角色而不是身体。英语在 1743 年固定下了 conflict of interest 这一说法。"},{"no":"07","title":"Standing in opposition","titleCN":"处于对立：持续相抵的状态","definition":"a continuing state in which two things are opposed to each other and cannot be reconciled","definitionCN":"两件事持续对立、无法调和的稳定状态","example":"The new housing plan is in conflict with the city's flood-control rules.","exampleCN":"新的住房计划与该市的防洪规定相抵触。","why":"This is not one blow but a standing relation: the two things stay pressed against each other, and the verb sense 'be in opposition', recorded in the 1640s, names that pressure.","whyCN":"这不是一次撞击，而是一种持续的对峙：两件事一直顶在一起；1640 年代记录的动词义“处于对立”命名的正是这种压力。"},{"no":"08","title":"Dramatic conflict: the force a story pushes against","titleCN":"戏剧冲突：故事所对抗的力量","definition":"in literature and drama, the opposition between characters or between a character and a larger force that drives the plot","definitionCN":"文学与戏剧中推动情节的人物对立，或人物与更大力量之间的对抗","example":"Every story needs a conflict, or the characters have nothing to push against.","exampleCN":"每个故事都需要冲突，否则人物就没有可对抗的东西。","why":"The collision is kept deliberately, because a struggle that never resolves is what keeps a plot moving. The word here names the engine, not a failure.","whyCN":"这种相撞是被有意保留的，因为始终未解决的对抗才会推动情节。此处这个词指的是引擎，而不是故障。"},{"no":"09","title":"Sustained armed conflict","titleCN":"长期武装冲突：一场变成一种处境","definition":"prolonged hostilities between states or armed groups, lasting long enough to become a condition of life","definitionCN":"国家或武装团体之间的长期敌对，持续到成为一种生活处境","example":"The region has been in armed conflict for a decade, with no agreed border.","exampleCN":"该地区已处于武装冲突十年之久，边界始终没有谈定。","why":"The single impact of sense 01 is stretched into duration: a battle becomes a condition that a whole society lives inside, and the word stops naming an event and starts naming an era.","whyCN":"第 1 个义项里的一次撞击被拉长成一段时间：一场战斗变成整个社会生活在其中的处境，这个词也就不再命名一个事件，而开始命名一个时代。"}],"etymology":{"intro":{"en":"Conflict entered English in the early 15th century through Old French, and its Latin parts still describe a physical collision: com- 'together' plus fligere 'to strike'.","cn":"conflict 在 15 世纪初经古法语进入英语，它的拉丁成分至今仍在描述一次物理撞击：com-“一起”加 fligere“打击”。"},"items":[{"era":"EARLY 15C.","en":"The noun is first recorded meaning 'armed encounter, battle', and the verb appears at about the same time meaning 'to contend, fight'.","cn":"名词最早记录时意为“武装遭遇、战斗”；动词几乎同时出现，意为“争斗、作战”。"},{"era":"OLD FRENCH conflit","en":"English took the word through Old French conflit, which already carried both the battlefield sense and the sense of a dispute.","cn":"英语经由古法语 conflit 借入，这个词在法语里已经同时带有战场义与争执义。"},{"era":"LATIN conflictus","en":"Latin conflictus was 'a striking together, collision', formed from the past participle of confligere.","cn":"拉丁语 conflictus 意为“撞在一起、碰撞”，由 confligere 的过去分词构成。"},{"era":"LATIN confligere","en":"Confligere joins com- 'together' and fligere 'to strike, dash down'. The image is not two things near each other but two things driven into one impact.","cn":"confligere 由 com-“一起”和 fligere“打击、击倒”组成。它的画面不是两样东西靠得很近，而是两样东西被赶着撞成一次冲击。"},{"era":"PROTO-INDO-EUROPEAN","en":"Fligere goes back to PIE *bhlig- 'to strike', the same reconstructed root that gives afflict and inflict. Reconstructed roots are inferred, not attested in writing.","cn":"fligere 可追溯到原始印欧语 *bhlig-“打击”，同一重构词根也给出 afflict 与 inflict。重构词根是推演出来的，没有书面文献直接证实。"},{"era":"1640S – 1875","en":"The verb gained 'be in opposition' in the 1640s, and by 1875 the noun covered 'discord of principles'. In 1859 psychology adopted the word for incompatible urges, and 'conflict of interest' is dated to 1743.","cn":"动词在 1640 年代获得“处于对立”之义，到 1875 年名词已覆盖“原则上的不合”。1859 年心理学用它指彼此不容的冲动，而 conflict of interest 可追溯到 1743 年。"}]},"similar":{"note":{"en":"The first group separates the adjectives and the rare derived forms built on conflict itself; the second group collects verbs and nouns that also describe a collision.","cn":"第一组区分由 conflict 本身构成的形容词与罕见派生形；第二组收集同样表示“相撞”的动词和名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conflicted","ipa":"/kənˈflɪktɪd/","tag":"past participle as adjective","definition":"torn between opposing feelings or loyalties. It describes a person's inner state, while conflict itself names the opposition.","definitionCN":"被对立的情感或忠诚撕扯的。它描述人的内在状态，而 conflict 本身指的是那种对立。"},{"word":"conflicting","ipa":"/kənˈflɪktɪŋ/","tag":"present participle as adjective","definition":"of two or more things, unable to be true or valid at the same time, as in conflicting reports. It modifies the things that clash, not the person who feels the clash.","definitionCN":"指两件或更多事物无法同时成立，如 conflicting reports（相互矛盾的报道）。它修饰相撞的事物，而不是感受冲突的人。"},{"word":"conflictual","ipa":"/kənˈflɪktʃuəl/","tag":"formal adjective","definition":"marked by conflict or full of opposition, often used in psychology and sociology for relationships and structures. It is a technical, bookish word, not a everyday substitute for conflict.","definitionCN":"充满冲突的、以对立为特征的，常用于心理学与社会学描述关系与结构。它是技术性的书面词，不是 conflict 的日常替代。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dispute","ipa":"/dɪˈspjuːt/","tag":"argument over a claim","definition":"a disagreement, especially one argued in public or in law. A dispute is usually about a specific claim or right, while a conflict can be wider and need not be spoken.","definitionCN":"分歧，尤指公开或法律上的争辩。dispute 通常围绕某一具体主张或权利，而 conflict 范围可以更宽，也不一定要说出口。"},{"word":"clash","ipa":"/klæʃ/","tag":"sharp, brief collision","definition":"a short sharp fight or a strong disagreement between people or ideas. Clash stresses the noise and suddenness of the impact; conflict can be quiet and long-lasting.","definitionCN":"短暂激烈的打斗，或人与观念之间的强烈碰撞。clash 强调撞击的声响与突然；conflict 可以是安静而长期的。"},{"word":"struggle","ipa":"/ˈstrʌɡl/","tag":"effort against resistance","definition":"a long effort against a difficulty or an opponent. Struggle stresses the effort of the party resisting, while conflict stresses the opposition between two parties.","definitionCN":"长期对抗困难或对手的努力。struggle 强调抵抗一方所付出的力气，conflict 强调双方之间的对立。"},{"word":"friction","ipa":"/ˈfrɪkʃn/","tag":"ongoing rubbing tension","definition":"continuous slight disagreement or tension between people who must work together. Friction is low-level and persistent; conflict can be open and decisive.","definitionCN":"必须合作的人之间持续不断的轻微分歧或摩擦。friction 程度低而持久；conflict 可以是公开而决断的。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: com- 'together', fligere 'strike', the same root family as afflict, and the derivatives conflicted and conflicting.","cn":"只用真实的构词成分与真实同族词：com-“一起”、fligere“打击”、与 afflict 同源的词族，以及派生词 conflicted、conflicting。"},"normal":[{"en":"com- means 'together' and fligere means 'strike'. A conflict is two things struck together, so the word begins with a physical impact.","cn":"com- 是“一起”，fligere 是“打击”。conflict 就是两样东西被撞在一起，所以这个词的起点是一次物理冲击。"},{"en":"The noun is stressed on the first syllable: CON-flict. The verb is stressed on the second: con-FLICT. The stress shift is real and follows the usual English noun/verb pattern.","cn":"名词重音在第一音节：CON-flict；动词重音在第二音节：con-FLICT。这个重音转移是真实的，符合英语名词／动词的常见模式。"},{"en":"Afflict and inflict share the same fligere 'strike' root, so their family resemblance is real, not a coincidence of spelling.","cn":"afflict 和 inflict 共享同一个 fligere“打击”词根，因此它们的相似是真实的，不是拼写巧合。"},{"en":"Conflicted describes a person pulled two ways; conflicting describes two things that cannot both stand. One is inside you, the other is between them.","cn":"conflicted 形容一个人被拉向两边；conflicting 形容两件事无法同时成立。一个在人的心里，一个在两者之间。"},{"en":"Armed conflict is a fixed phrase: it names a sustained state of war, not a single battle.","cn":"armed conflict 是固定搭配：它指的是一场持续的战争状态，不是一次战斗。"}],"abstract":[{"en":"Picture two trains entering the same tunnel from opposite ends. Conflict is the instant before either can stop.","cn":"想象两列火车从隧道两端同时驶入。conflict 就是任何一方还来不及刹住的那一瞬间。"},{"en":"The collision can happen between armies, colleagues, principles, appointments, roles, or two urges inside one chest. The shape stays the same; only the things colliding change.","cn":"这场相撞可以发生在军队、同事、原则、日程、角色之间，也可以发生在同一个胸腔里的两股冲动之间。形状不变，变的只是撞在一起的东西。"},{"en":"Conflict is not always a fault. In a story it is the engine, and in a design review it is the signal that two requirements were never reconciled.","cn":"冲突并不总是错误。在故事里它是引擎，在设计评审里它是信号——说明有两条需求从来没有被调和。"}]},"examples":[{"en":"The conflict over the water rights has kept the two towns apart for generations.","cn":"围绕水权的冲突让这两个镇几代人互不往来。"},{"en":"His account of the accident conflicts with the version given by the driver.","cn":"他对事故的叙述与司机给出的说法相冲突。"},{"en":"She resigned from the board to avoid any conflict of interest.","cn":"她从董事会辞职，以避免任何利益冲突。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康弗利克特”——康弗和利克特抢同一间办公室，一进门就撞在一起 → conflict 冲突、抵触","word":"conflict"},"root":"源自拉丁语 confligere“相撞、交战”，由 com-“一起”+ fligere“打击”构成，核心是“两股力量撞在一起”。","sensesIntro":{"en":"Nine senses of conflict, all grown from one physical event: two forces driven into the same point. What changes is only what is colliding — armies, people, principles, urges, schedules, roles, or the forces inside a story.","cn":"conflict 的九个义项都从同一个物理事件长出来：两股力量被驱赶到同一点。变化的只是撞在一起的东西——军队、人、原则、冲动、日程、角色，或故事内部的力量。"},"semanticMap":{"core":{"en":"CORE IMAGE: two forces driven into one point of impact.","cn":"核心意象：两股力量被驱赶到同一个撞击点。"},"chain":["TWO FORCES APPROACH","STRIKE TOGETHER","NEITHER CAN YIELD","WORDS AND IDEAS COLLIDE","INNER PULL","STANDING OPPOSITION"],"branches":[{"senses":"S1 · S9","en":"ARMED: a single battlefield impact, and the long war that a single impact can turn into.","cn":"武装：战场上的一次撞击，以及一次撞击可能演变成的长期战争。"},{"senses":"S2 · S7","en":"PEOPLE: an argument between people, and the settled hostility that remains after the argument ends.","cn":"人：人与人之间的一场争执，以及争执结束后留下来的稳定敌意。"},{"senses":"S3 · S8","en":"STRUCTURE: principles that cannot both stand, and dramatic forces that must keep pushing against each other.","cn":"结构：无法同时成立的原则，以及必须持续互推的戏剧力量。"},{"senses":"S4 · S6","en":"INNER AND ROLE: incompatible urges inside one person, and incompatible duties inside one position.","cn":"内心与角色：一个人内部彼此不容的冲动，以及一个职位内部彼此不容的职责。"},{"senses":"S5","en":"PRACTICAL CLASH: two appointments in one hour, two demands on one budget or one road.","cn":"实际撞车：同一个小时里的两个约会，同一份预算或同一条路上的两项需求。"}]},"affixes":{"intro":{"en":"English does not build conflict from a live prefix. Com- and fligere are frozen inside the Latin word; English adds only ordinary inflections and suffixes, plus a compound and a technical verb.","cn":"英语并不是用活的前缀来造 conflict 的。com- 与 fligere 凝固在拉丁词里；英语只添加普通的屈折与后缀，再加一个复合词和一个技术动词。"},"latinIntro":{"en":"The Latin family is built on confligere 'to strike together': conflictus 'a collision', conflictio 'a contest', and fligere itself 'to strike'. The same fligere also produced afflict and inflict.","cn":"这一拉丁词族建立在 confligere“撞在一起”上：conflictus“碰撞”、conflictio“争斗”，以及 fligere 本身“打击”。同一个 fligere 还产生了 afflict 与 inflict。"},"items":[{"word":"conflicts","structure":"conflict + -s (plural or third-person singular)","meaning":"more than one conflict, or 'it conflicts'","meaningCN":"多场冲突；或动词第三人称单数“它相冲突”（-s 表示复数或三单）","example":"The report lists three unresolved conflicts along the border.","exampleCN":"报告列出了边境上三处尚未解决的冲突。"},{"word":"conflicted","structure":"conflict + -ed (past tense, past participle, adjective)","meaning":"having experienced conflict; torn between opposing feelings","meaningCN":"经历过冲突的；（内心）矛盾的、左右为难的（-ed 构成过去式、过去分词与形容词）","example":"She felt conflicted about accepting the promotion.","exampleCN":"她对是否接受这次升职感到内心矛盾。"},{"word":"conflicting","structure":"conflict + -ing (present participle, adjective)","meaning":"being in opposition; unable to be true at the same time","meaningCN":"相冲突的；相互矛盾的（-ing 构成现在分词与形容词）","example":"The two witnesses gave conflicting accounts of the night.","exampleCN":"两名目击者对那晚的情况给出了相互矛盾的叙述。"},{"word":"conflictual","structure":"conflict + -ual (adjective)","meaning":"characterized by conflict","meaningCN":"以冲突为特征的；冲突性的（-ual 构成形容词）","example":"The study examines conflictual relationships between neighbouring states.","exampleCN":"这项研究考察邻国之间的冲突性关系。"},{"word":"conflictive","structure":"conflict + -ive (adjective)","meaning":"likely to produce conflict","meaningCN":"易引发冲突的；对抗性的（-ive 构成形容词）","example":"The proposal proved conflictive within the committee.","exampleCN":"该提案在委员会内部证明是容易引发冲突的。"},{"word":"conflictively","structure":"conflictive + -ly (adverb)","meaning":"in a way that produces conflict","meaningCN":"以引发冲突的方式（-ly 构成副词）","example":"He raised the issue conflictively, and the meeting broke up.","exampleCN":"他带着对抗的姿态提出这个问题，会议不欢而散。"},{"word":"conflict-free","structure":"conflict + free (compound adjective)","meaning":"without conflict, as of minerals, scheduling, or data","meaningCN":"无冲突的；不涉及争端的（conflict + free 构成的复合形容词）","example":"The jeweller certifies that the stones are conflict-free.","exampleCN":"珠宝商证明这些宝石不涉及冲突矿产。"},{"word":"deconflict","structure":"de- (remove) + conflict (verb)","meaning":"to remove or prevent conflicts, especially of schedules or airspace","meaningCN":"消除冲突；对日程或空域进行去冲突（de- 表示去除）","example":"The two airlines had to deconflict their departure slots.","exampleCN":"两家航空公司必须协调去除起飞时段的冲突。"}],"latinEntries":[{"word":"confligere","structure":"com- (together) + fligere (strike)","meaning":"to strike together, clash, contend","meaningCN":"撞在一起；交战；争斗"},{"word":"conflictus","structure":"confligere + -tus (past participle, used as noun)","meaning":"a striking together, collision, contest","meaningCN":"相撞；碰撞；争斗"},{"word":"fligere","structure":"root verb","meaning":"to strike, dash down","meaningCN":"打击；击倒"}]}},{"word":"conform","ipa_uk":"/kənˈfɔːm/","ipa_us":"/kənˈfɔːrm/","definition_zh":"遵守；符合；顺从（规则、习俗）；与……一致","definition_en":"to act according to a rule, standard, or expectation, or to match a pattern, shape, or model","core_image":"一块湿泥被按进同一个模子里，边角与模子严丝合缝","scene":"In his first week at the bank, he shaved his beard and bought three grey suits to conform.","sceneCN":"这里 conform 是「从众、照着大家的样子做」（第 3 个义项：迎合群体的做法与品味）；句意：进银行的第一周，他就刮掉胡子、买了三套灰西装，以便和大家一样。场景要点：一间办公室、一片灰色西装、一个新来的人把自己调进同一个模子。","pos":[{"tag":"v.","zh":"遵守；顺从；符合；与……一致"},{"tag":"v.","zh":"使一致；使符合（较正式）"}],"collocations":[{"phrase":"conform to the rules","zh":"遵守规则"},{"phrase":"conform to a standard","zh":"符合标准"},{"phrase":"conform with the law","zh":"与法律一致"},{"phrase":"refuse to conform","zh":"拒绝从众；不肯顺从"},{"phrase":"conform to expectations","zh":"符合预期"},{"phrase":"conform to local customs","zh":"遵从当地习俗"}],"forms":[{"label":"动词第三人称单数","form":"conforms"},{"label":"动词过去式","form":"conformed"},{"label":"动词过去分词","form":"conformed"},{"label":"动词现在分词","form":"conforming"}],"derivatives":[{"word":"conformity","pos":"n.","zh":"遵从；符合；一致性"},{"word":"conformance","pos":"n.","zh":"（对标准、规格的）符合；一致性"},{"word":"conformist","pos":"n./adj.","zh":"顺从者；墨守成规的人／顺从的"},{"word":"nonconformist","pos":"n./adj.","zh":"不遵奉常规的人；不从众的"},{"word":"conformable","pos":"adj.","zh":"顺从的；符合的；可使之一致的"},{"word":"nonconformity","pos":"n.","zh":"不遵从；不一致；不从众"}],"senses":[{"no":"01","title":"Be obedient to a higher authority","titleCN":"服从更高的权威","definition":"to submit one's behaviour to the command of God, a superior, or an accepted authority","definitionCN":"使自己的行为服从上帝、上级或公认权威的命令","example":"The monks conformed to the rule of silence from the first bell.","exampleCN":"从第一声钟响起，修士们就遵守静默的规定。","why":"Latin conformare meant 'to fashion, shape'. To obey was originally to let a higher authority press you into its mould, so obedience and shaping were one act.","whyCN":"拉丁语 conformare 本义是“塑造、做成形状”。服从最初就是让更高的权威把你按进它的模子，因此服从与塑形曾是同一个动作。"},{"no":"02","title":"Act in accordance with an example","titleCN":"照着范例行事","definition":"to behave in the way that a model, example, or established practice prescribes","definitionCN":"按照范本、例证或既定做法所规定的方式行事","example":"The new branch conformed to the parent company's accounting format.","exampleCN":"新分公司照搬了母公司的会计格式。","why":"Late 14th-century English added 'bring into harmony; act in accordance with an example'. The mould is now an example rather than a person, but the copy is still exact.","whyCN":"14 世纪晚期英语又添上“使之和谐、依照范例行事”一义。模子此时从一个人变成一份范例，但复制仍然要求严丝合缝。"},{"no":"03","title":"Social conformity: fitting in with the group","titleCN":"社会从众：与群体对齐","definition":"to adopt the dress, habits, or opinions of a group in order to belong to it","definitionCN":"为了融入群体而采用该群体的穿着、习惯或观点","example":"Teenagers often conform to the group's taste in music before they ever question it.","exampleCN":"青少年往往在质疑之前，就已经顺从了群体的音乐品味。","why":"If the mould belongs to a group, fitting it means giving up whatever shape was yours. The word keeps the pressure of the mould and loses none of its discomfort.","whyCN":"如果模子属于一个群体，嵌进去就意味着放弃你原本的形状。这个词保留了模子的压力，也保留了其中全部的不适。"},{"no":"04","title":"Religious conformity to an established church","titleCN":"宗教上遵奉国教","definition":"in English history, to accept the doctrines and forms of worship of the established church","definitionCN":"在英国历史上，指接受国教的教义与礼拜形式","example":"In the 1630s, clergymen who refused to conform to the prayer book lost their posts.","exampleCN":"在 17 世纪 30 年代，拒绝遵奉祈祷书的教士被免职。","why":"From the 1610s the word named acceptance of the Church of England's forms. A form of worship is literally a shape, so the original metaphor and the religious usage meet again.","whyCN":"从 17 世纪 10 年代起，这个词指接受英格兰教会的礼拜形式。礼拜的 form 字面就是“形状”，因此原初的比喻与宗教用法在这里重新重合。"},{"no":"05","title":"Match a shape or specification","titleCN":"形状或规格吻合","definition":"of an object, to have exactly the shape, size, or specification required","definitionCN":"指物体具有完全符合要求的形状、尺寸或规格","example":"The replacement part conforms to the original thread size.","exampleCN":"替换零件的尺寸与原装螺纹规格完全吻合。","why":"This is the mould image at its most literal: the metal part must take precisely the shape left by the specification, with no room for individual variation.","whyCN":"这是模子意象最字面的一次：金属件必须精确地嵌进规格留下的形状，不留任何个体差异的余地。"},{"no":"06","title":"Comply with a law or regulation","titleCN":"遵守法律或规章","definition":"to meet the requirements of a law, code, or official rule","definitionCN":"满足法律、规范或官方规则的要求","example":"All shipments must conform with the new labelling rules.","exampleCN":"所有货物都必须遵守新的标签规定。","why":"A regulation is a mould drawn by a legislature: a product or procedure conforms when it can pass through that outline without forcing it open.","whyCN":"法规是立法者画出的模子：产品或流程能顺着这个轮廓通过而不把它撑开，就是 conform。"},{"no":"07","title":"Fit a model or prediction","titleCN":"符合模型或预测","definition":"of data or behaviour, to agree with what a theory, model, or prediction says should happen","definitionCN":"指数据或行为与理论、模型或预测所说的应当发生的情况相符合","example":"The results conformed to the model's prediction within two percent.","exampleCN":"结果与模型的预测误差在百分之二以内。","why":"Here the mould is a theory. Observing that the data take its shape is what lets a scientist say the model holds; the word marks agreement between pattern and instance.","whyCN":"这里的模子是理论。观察到数据长成它的形状，科学家才能说这个模型成立；这个词标记的是模式与个例之间的一致。"},{"no":"08","title":"Adapt to local custom","titleCN":"入乡随俗","definition":"to adjust one's behaviour to the unwritten expectations of a place or culture","definitionCN":"使自己的行为适应某一地方或文化中不成文的期待","example":"She conformed to local dining customs without abandoning her own.","exampleCN":"她遵从了当地的餐桌习俗，但也没有丢掉自己的。","why":"The shaping is now voluntary and temporary: a traveller bends to a local outline for a while, then keeps the original shape underneath.","whyCN":"这里的塑形是自愿而暂时的：旅人暂时弯进当地的轮廓，但底下仍保留原来的形状。"},{"no":"09","title":"Bring one thing into harmony with another","titleCN":"使一物与另一物相协调","definition":"to make something consistent with or fitted to something else, often in a formal or technical context","definitionCN":"使某物与另一物一致或相嵌合，常用于正式或技术语境","example":"The architect conformed the new wing to the slope of the old roof.","exampleCN":"建筑师让新侧翼与旧屋顶的坡度相协调。","why":"The transitive use goes back to 'bring into harmony' in the late 14th century: instead of being pressed into a mould, the maker presses one thing into the outline of another.","whyCN":"及物用法可追溯到 14 世纪晚期的“使之和谐”：不是自己被按进模子，而是制造者把一件东西按进另一件东西的轮廓里。"}],"etymology":{"intro":{"en":"Conform comes from Latin conformare 'to fashion, shape', built on forma 'form, shape'. Its whole history is the history of being fitted to a mould.","cn":"conform 来自拉丁语 conformare“塑造、做成形状”，建立在 forma“形状、形式”之上。它的全部历史，就是“被嵌进一个模子”的历史。"},"items":[{"era":"MID-14C.","en":"First recorded in English meaning 'be obedient (to God), comply'. The earliest sense is religious and moral, not technical.","cn":"英语中最早记录于 14 世纪中叶，意为“（对上帝）服从、遵从”。最早的义项是宗教与道德性的，而不是技术性的。"},{"era":"LATE 14C.","en":"A second branch appears: 'bring into harmony; act in accordance with an example'. The transitive 'make consistent' and the intransitive 'follow a model' grow side by side.","cn":"第二条分支出现：“使之和谐；依照范例行事”。及物的“使一致”与不及物的“照范本做”并排生长。"},{"era":"OLD FRENCH conformer","en":"English borrowed the verb through Old French conformer, which had already narrowed the Latin word toward obedience and agreement.","cn":"英语经由古法语 conformer 借入这个动词，法语已把拉丁词义收窄到“服从”和“一致”。"},{"era":"LATIN conformare","en":"Conformare joins com- 'together' (here intensive, 'completely') and formare 'to form, shape', from forma 'form, shape, mould'.","cn":"conformare 由 com-“一起”（此处为加强义“完全”）和 formare“使成形、塑造”组成，后者来自 forma“形状、形式、模子”。"},{"era":"1610S – 1630S","en":"In the 1610s the word was applied to accepting the forms of the Church of England; conformist, the label for one who does so, is dated to the 1630s.","cn":"17 世纪 10 年代，这个词被用来指接受英格兰教会的礼拜形式；指称这样做的人的 conformist 可追溯到 17 世纪 30 年代。"},{"era":"NOT CONFIRM","en":"Conform must not be confused with confirm. Conform rests on forma 'shape'; confirm rests on Latin firmus 'firm, strong', from confirmare 'to strengthen, establish'. The two words are not related, despite their near-identical spelling.","cn":"conform 不可与 confirm 混淆。conform 的根基是 forma“形状”；confirm 的根基是拉丁语 firmus“坚固、牢固”，来自 confirmare“使坚固、确立”。尽管拼写几乎一样，二者并非同源词。"}]},"similar":{"note":{"en":"The first group is the dangerous one: three words that look almost like conform but come from a different root or a different suffix. The second group collects verbs of following a rule.","cn":"第一组最危险：三个词看起来几乎和 conform 一样，却来自不同词根或不同后缀。第二组收集表示“按规则行事”的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"confirm","ipa":"/kənˈfɜːm/","tag":"different root: firmus","definition":"to prove or establish that something is true; to ratify. It looks like conform and sounds close to it, but its root is Latin firmus 'firm, strong', from confirmare 'strengthen'. Forma 'shape' plays no part in it.","definitionCN":"证实或确认某事为真；批准。它看起来、听起来都近似 conform，但词根是拉丁语 firmus“坚固、牢固”，来自 confirmare“使坚固”。forma“形状”与它毫无关系。"},{"word":"conformist","ipa":"/kənˈfɔːmɪst/","tag":"-ist person noun","definition":"a person who behaves according to accepted standards, often used with disapproval. The -ist suffix turns the verb into the person who does it.","definitionCN":"按公认标准行事的人，常带贬义。后缀 -ist 把动词变成“做这件事的人”。"},{"word":"nonconformist","ipa":"/ˌnɒnkənˈfɔːmɪst/","tag":"non- negation","definition":"a person who refuses to follow established customs or doctrines; also a member of a Protestant church outside the Church of England. The non- prefix reverses the fitting.","definitionCN":"拒绝遵循既定习俗或教义的人；也指英格兰教会之外的新教教徒。前缀 non- 把“嵌合”反转过来。"},{"word":"conformance","ipa":"/kənˈfɔːməns/","tag":"-ance noun","definition":"the fact of meeting a standard or specification, common in industry and testing. It is close to conformity but more technical and countable in quality-control contexts.","definitionCN":"符合标准或规格的事实，常用于工业与检测。它与 conformity 相近，但在质量控制语境中更技术化。"}]},{"heading":"NEAR MEANING","entries":[{"word":"comply","ipa":"/kəmˈplaɪ/","tag":"follow an order or rule","definition":"to act in accordance with an order, rule, or request. Comply stresses doing what is required; conform stresses taking the required shape.","definitionCN":"按命令、规则或请求行事。comply 强调做出被要求的行为；conform 强调变成被要求的形状。"},{"word":"obey","ipa":"/əˈbeɪ/","tag":"submit to authority","definition":"to do what a person in authority tells you to do. Obey is personal and direct, while conform can be impersonal, driven only by a norm or a pattern.","definitionCN":"听从有权威者的指令。obey 是人对人的、直接的；conform 可以是非人称的，只由规范或模式驱动。"},{"word":"adapt","ipa":"/əˈdæpt/","tag":"change to fit","definition":"to change oneself or something else so that it fits a new situation. Adapt stresses change and adjustment; conform stresses matching a fixed outline.","definitionCN":"改变自己或他物以适应新情况。adapt 强调改变与调整；conform 强调与一个固定轮廓相吻合。"},{"word":"adhere","ipa":"/əˈdɪə/","tag":"stick to a rule","definition":"to follow a rule, agreement, or belief closely; literally, to stick to a surface. Adhere is about loyalty to a commitment, conform about shape-matching.","definitionCN":"严格遵守规则、协议或信念；字面义为“黏附在表面”。adhere 强调对承诺的忠诚，conform 强调形状上的吻合。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: com- 'together', forma 'shape', and the living pair conformity / conformist. The confirm contrast is spelling only, not etymology.","cn":"只用真实的构词成分与真实同族词：com-“一起”、forma“形状”，以及常用成对的 conformity／conformist。与 confirm 的区别只在拼写，不在词源。"},"normal":[{"en":"con- means 'together' and forma means 'shape'. To conform is to take the same shape as everyone else in the group.","cn":"con- 是“一起”，forma 是“形状”。conform 就是长成和群体中其他人一样的形状。"},{"en":"The suffix -form appears in many real words: form, format, formula, uniform, transform. All of them carry the idea of shape, which is the true core here.","cn":"后缀 -form 出现在许多真实单词里：form、format、formula、uniform、transform。它们都带着“形状”这个观念，而形状正是这个词真正的核心。"},{"en":"Conform is not confirm. Conform = take the shape (forma); confirm = make firm (firmus). Remember 'forma' when you see the o in conform.","cn":"conform 不是 confirm。conform = 取形状（forma）；confirm = 使坚固（firmus）。看到 conform 里的 o，就想起 forma。"},{"en":"A conformist takes the group's shape; a nonconformist refuses it. The non- prefix does not change the root, only the decision.","cn":"conformist 接受群体的形状；nonconformist 拒绝它。non- 前缀改变的不是词根，只是那个决定。"},{"en":"In manufacturing, conformance is a measurable thing: the part either fits the specification or it does not. That is the mould image made testable.","cn":"在制造业，conformance 是可测量的事情：零件要么符合规格，要么不符合。这就是模子意象被做成了可检验的东西。"}],"abstract":[{"en":"Picture a single iron mould and a queue of soft clay blocks. Each block loses its own edges as it enters, and comes out identical to the others.","cn":"想象一个铁模子和一队软泥块。每一块在进入时失去自己的边角，出来时和其余的一模一样。"},{"en":"The mould can be a god, a school, a company, a law, a theory, or a local custom. The pressure is the same; only the authority holding the mould changes.","cn":"模子可以是神、学校、公司、法律、理论，也可以是当地习俗。压力是一样的，变的只是握着模子的那个权威。"},{"en":"Conformity is comfortable and costly at the same time: you gain belonging, and you give up the edges that made you recognisable.","cn":"从众同时是舒适和昂贵的：你得到了归属，也交出了那些让人认得出你的边角。"}]},"examples":[{"en":"The packaging must conform to the safety standard before it can be sold.","cn":"包装必须符合安全标准才能销售。"},{"en":"He refused to conform to the office's unspoken rule about working late.","cn":"他拒绝遵从办公室那条关于加班的潜规则。"},{"en":"The village church was built to conform with the older chapel beside it.","cn":"这座村庄教堂的建造方式与旁边那座更古老的礼拜堂相协调。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“肯仿”——肯照着别人的样子仿，大家最后都长成一个模子 → conform 遵从、符合","word":"conform"},"root":"源自拉丁语 conformare“塑造、做成形状”，由 com-“一起”+ forma“形状”构成，核心是“把自己嵌进同一个模子”。","sensesIntro":{"en":"Nine senses of conform, all grown from one action: something takes the shape of a mould. The mould may be God, a rule, a group, a church, a specification, a law, a theory, a local custom, or another object.","cn":"conform 的九个义项都从同一个动作长出来：某物嵌进一个模子的形状。模子可以是神、规则、群体、教会、规格、法律、理论、当地习俗，也可以是另一件东西。"},"semanticMap":{"core":{"en":"CORE IMAGE: soft material pressed into a fixed mould and coming out in its shape.","cn":"核心意象：软材料被按进固定模子，出来时是模子的形状。"},"chain":["A MOULD EXISTS","MATERIAL IS PRESSED IN","EDGES ARE GIVEN UP","SHAPE MATCHES","THE GROUP ACCEPTS IT","THE FIT BECOMES A RULE"],"branches":[{"senses":"S1 · S4","en":"AUTHORITY: God, a superior, or an established church holds the mould, and obedience is the act of entering it.","cn":"权威：上帝、上级或国教握着模子，服从就是走进去的动作。"},{"senses":"S2 · S3","en":"SOCIETY: an example or a group supplies the outline, and the individual gives up personal edges to fit it.","cn":"社会：范例或群体提供轮廓，个人交出个人的边角以嵌进去。"},{"senses":"S5 · S6","en":"SPECIFICATION: a part, a product, or a procedure must pass through the outline drawn by a standard or a law.","cn":"规格：零件、产品或流程必须顺着标准或法律画出的轮廓通过。"},{"senses":"S7","en":"MODEL: data takes the shape a theory predicts, and that agreement is what confirms the model.","cn":"模型：数据长成理论预测的形状，这种一致正是模型得到确认的依据。"},{"senses":"S8 · S9","en":"ADJUSTMENT: a traveller bends to local custom, or a maker presses one thing into the outline of another.","cn":"调整：旅人暂时弯进当地习俗，或制造者把一件东西按进另一件东西的轮廓。"}]},"affixes":{"intro":{"en":"Conform is one of the few words in this batch whose Latin parts are still fully transparent in English: con- plus forma, and the suffix -form survives in dozens of everyday words.","cn":"conform 是本批少数几个拉丁成分在英语里仍然完全透明的词：con- 加 forma，而且 -form 这个成分在几十个日常单词里存活下来。"},"latinIntro":{"en":"The Latin family is built on forma 'shape': formare 'to shape', conformare 'to shape together', and conformis 'similar in shape'. English also borrowed forma through French as form, and built conformable and conformance on the same stem.","cn":"这一拉丁词族建立在 forma“形状”上：formare“使成形”、conformare“一起塑形”、conformis“形状相似的”。英语还经法语借入 forma 作 form，并在同一词干上造出 conformable 与 conformance。"},"items":[{"word":"conformity","structure":"conform + -ity (state noun)","meaning":"the state of matching a rule or of behaving like others","meaningCN":"符合；遵从；一致性（-ity 构成状态名词）","example":"The audit checks conformity with the accounting standard.","exampleCN":"审计检查是否符合会计准则。"},{"word":"conformance","structure":"conform + -ance (state noun)","meaning":"the fact of meeting a specification","meaningCN":"（对规格的）符合；一致性（-ance 构成状态名词）","example":"The factory issued a certificate of conformance.","exampleCN":"工厂出具了一份符合性证书。"},{"word":"conformist","structure":"conform + -ist (person noun)","meaning":"a person who follows accepted standards","meaningCN":"顺从者；墨守成规的人（-ist 构成人称名词）","example":"He was too much of a conformist to challenge the manager.","exampleCN":"他太顺从了，不敢质疑经理。"},{"word":"nonconformist","structure":"non- (not) + conformist","meaning":"a person who refuses established customs or doctrines","meaningCN":"不遵奉常规的人；不从众者（non- 表示否定）","example":"As a nonconformist, she wore red to the all-black party.","exampleCN":"她一向不从众，在所有人都穿黑衣的聚会上穿了红色。"},{"word":"nonconformity","structure":"non- (not) + conformity","meaning":"failure or refusal to conform","meaningCN":"不遵从；不一致；不从众（non- + -ity）","example":"The report noted repeated nonconformity with the safety code.","exampleCN":"报告指出多次不符合安全规范的情况。"},{"word":"conformable","structure":"conform + -able (able to be)","meaning":"able to be made to fit or to agree","meaningCN":"可使之符合的；顺从的（-able 表示“能够被”）","example":"The old rules are conformable to the new treaty.","exampleCN":"旧规则可以调整到与新条约一致。"},{"word":"conformably","structure":"conformable + -ly (adverb)","meaning":"in a way that matches a rule or standard","meaningCN":"以符合的方式（-ly 构成副词）","example":"The site was built conformably with the zoning plan.","exampleCN":"该场地是按分区规划建造的。"},{"word":"conforming","structure":"conform + -ing (participle adjective)","meaning":"meeting a standard; also the act of matching","meaningCN":"符合的；遵从的（-ing 构成分词形容词）","example":"Only conforming products may carry the safety mark.","exampleCN":"只有符合标准的产品才能加贴安全标志。"}],"latinEntries":[{"word":"conformare","structure":"com- (together, completely) + formare (to shape)","meaning":"to fashion, form, shape; to make consistent","meaningCN":"塑造；做成形状；使一致"},{"word":"forma","structure":"noun","meaning":"form, shape, mould, figure","meaningCN":"形状；形式；模子；外形"},{"word":"confirmare","structure":"con- + firmare (to strengthen), from firmus (firm)","meaning":"to strengthen, establish, confirm; the source of English confirm, NOT of conform","meaningCN":"使坚固、确立、确认；这是英语 confirm 的来源，与 conform 无关"}]}},{"word":"consequence","ipa_uk":"/ˈkɒnsɪkwəns/","ipa_us":"/ˈkɑːnsəkwens/","definition_zh":"结果；后果；重要性；推论","definition_en":"a result or effect that follows from an action or condition; also, importance or a logical conclusion","core_image":"一颗石子落水，波纹一圈一圈追着它后面荡开","scene":"The company ignored the corrosion report, and the consequence arrived two years later as a burst pipeline.","sceneCN":"这里 consequence 是「（某一行动带来的）结果、后果」（第 1 个义项：由某个行为随之而来的事）；句意：公司无视了那份腐蚀报告，两年后作为一条爆裂的管道，后果终于到来。场景要点：一份被搁置的报告、一条生锈的管道、两年后的一地积水。","pos":[{"tag":"n.","zh":"结果；后果；重要性"},{"tag":"n.","zh":"推论；逻辑结论"}],"collocations":[{"phrase":"as a consequence","zh":"因此；结果"},{"phrase":"in consequence of","zh":"由于……；作为……的结果"},{"phrase":"face the consequences","zh":"承担后果"},{"phrase":"suffer the consequences","zh":"承受后果"},{"phrase":"serious consequences","zh":"严重后果"},{"phrase":"unintended consequences","zh":"意外后果；非本意的连带影响"},{"phrase":"of little consequence","zh":"无关紧要的"}],"forms":[{"label":"名词复数","form":"consequences"}],"derivatives":[{"word":"consequent","pos":"adj./n.","zh":"随之发生的；作为结果的／推断出的结论"},{"word":"consequently","pos":"adv.","zh":"因此；所以"},{"word":"consequential","pos":"adj.","zh":"重大的；引起重大后果的；自大的"},{"word":"inconsequential","pos":"adj.","zh":"微不足道的；不重要的"},{"word":"consequentially","pos":"adv.","zh":"随之；因而；在后果上"}],"senses":[{"no":"01","title":"What follows from an action","titleCN":"行为之后随之而来的事","definition":"an outcome that comes after and is caused by an earlier action or condition","definitionCN":"在较早的行为或状况之后发生、并由其导致的结果","example":"Every subsidy has a consequence, and this one was a rush of cheap imports.","exampleCN":"每项补贴都会带来结果，这一次的结果是廉价进口商品大量涌入。","why":"Latin consequi means 'to follow after'. A consequence is not merely a later event; it is a later event that follows from the earlier one, the way a ripple follows the stone.","whyCN":"拉丁语 consequi 意为“跟在后面”。consequence 不只是“后来发生的事”，而是“从前面那件事跟出来的事”——就像波纹跟着石子出现。"},{"no":"02","title":"The penalty you must answer for","titleCN":"必须承担的代价","definition":"usually in the plural, the unpleasant results that someone must accept responsibility for","definitionCN":"通常用复数，指某人必须为其承担责任的、令人不快的结果","example":"If the firm keeps cutting inspections, it will face the consequences in court.","exampleCN":"如果公司继续削减检查，它将在法庭上承担后果。","why":"When the following event hurts, the neutral 'outcome' becomes a bill. The plural turns a single result into a set of things that arrive together and must be paid.","whyCN":"当跟着来的事件带有伤害，“中性的结果”就成了一张账单。复数形式把单一结果变成一并到来、必须偿付的一串代价。"},{"no":"03","title":"Importance: a matter of consequence","titleCN":"重要性：有分量的事","definition":"importance or significance, especially in the phrase 'of consequence'","definitionCN":"重要或具有意义，尤其见于 of consequence 这一说法","example":"The committee spent the morning on details of little consequence.","exampleCN":"委员会一上午都在处理无关紧要的细节。","why":"From the 1590s the word meant 'importance, significance'. The link is that something full of consequences is heavy: what can change later events deserves attention now.","whyCN":"从 16 世纪 90 年代起，这个词表示“重要性、意义”。联系在于：充满后果的东西是重的——能改变后来事件的事物，现在就值得被重视。"},{"no":"04","title":"Logical conclusion","titleCN":"逻辑推论","definition":"a conclusion reached by reasoning from premises, the word's oldest recorded sense","definitionCN":"由前提经推理得出的结论，也是这个词最早的记录义","example":"From those two premises the consequence is unavoidable: the witness saw someone else.","exampleCN":"由那两个前提可以必然推出结论：证人看到的是另一个人。","why":"In logic the follower is a proposition: it follows from the premises as firmly as a ripple follows the stone. English recorded this sense in the late 14th century, before it recorded the everyday 'result'.","whyCN":"在逻辑里，跟着来的是一个命题：它从前提出发，就像波纹跟着石子一样确定。英语在 14 世纪晚期就记录了此义，早于日常的“结果”义。"},{"no":"05","title":"Unintended consequences","titleCN":"意外后果","definition":"effects of an action that were not foreseen or intended by those who took it","definitionCN":"行动带来的、行动者既未预见也非本意的效果","example":"The rent cap had an unintended consequence: landlords stopped building new flats.","exampleCN":"租金上限产生了一个意外后果：房东不再建新公寓。","why":"The ripple keeps travelling after the thrower has stopped looking. The word does not require that anyone planned the outcome, only that it followed.","whyCN":"扔石子的人早已不看水面，波纹却还在往外走。这个词并不要求有谁计划过这个结果，只要求它确实跟着来了。"},{"no":"06","title":"'In consequence': a formal link","titleCN":"“因此”：正式的连接语","definition":"in the phrases 'in consequence' and 'as a consequence', used to introduce a result in formal writing","definitionCN":"在 in consequence、as a consequence 等短语中，用于在正式写作里引出结果","example":"The bridge was closed for repairs; in consequence, the school bus now takes twenty minutes longer.","exampleCN":"桥因维修封闭；因此，校车现在要多走二十分钟。","why":"The noun is turned into a signpost: instead of naming a result, the phrase points at the next sentence and says 'what follows is the follower.'","whyCN":"名词变成了路标：这个短语不再命名某个结果，而是指向下一句，说“接下来这句就是那个跟着来的东西”。"},{"no":"07","title":"Long-range aftermath","titleCN":"长期余波","definition":"the distant social, historical, or environmental effects that continue after the original event","definitionCN":"原初事件结束之后仍持续存在的社会、历史或环境层面的远期影响","example":"The consequences of the dam are still reshaping the river forty years later.","exampleCN":"四十年后，大坝的后果仍在改变这条河。","why":"The ripple image works in time as well as space: an event keeps sending effects outward long after the moment of impact, so the word can name a slow aftermath rather than a single ending.","whyCN":"波纹意象在时间上和空间上同样成立：一个事件在撞击之后很久还在向外发送影响，因此这个词可以命名缓慢的余波，而不是一个单一的结局。"},{"no":"08","title":"A person of consequence","titleCN":"有身份地位的人","definition":"in older usage, social importance or standing, as in 'a man of consequence'","definitionCN":"在较早用法中，指社会上的重要性或地位，如 a man of consequence（有身份的人）","example":"He arrived at the assembly as a man of consequence, with two servants behind him.","exampleCN":"他作为有身份的人来到集会，身后跟着两名仆人。","why":"Importance was once measured by what one's actions could set in motion. A person of consequence is someone whose choices ripple outward across other people's lives.","whyCN":"重要性曾经是以“一个人的行动能带动多少东西”来衡量的。有身份的人，就是他的选择会在别人生活里荡开波纹的人。"}],"etymology":{"intro":{"en":"Consequence came through French from Latin consequi 'to follow after'. The oldest sense in English is logical, and the everyday 'result' sense came soon after.","cn":"consequence 经法语来自拉丁语 consequi“跟在后面”。英语中最古老的义项是逻辑上的，日常的“结果”义紧随其后出现。"},"items":[{"era":"LATE 14C.","en":"First recorded meaning 'logical inference, conclusion'. The word enters English as a term of reasoning before it becomes a term of everyday causes.","cn":"最早记录时意为“逻辑推论、结论”。这个词先作为推理术语进入英语，之后才成为日常因果的用语。"},{"era":"OLD FRENCH consequence","en":"English took the form from Old French consequence, which carried the Latin sense of a conclusion that follows from premises.","cn":"英语从古法语 consequence 取来这个词形，法语保留了拉丁语中“由前提推出的结论”这一含义。"},{"era":"LATIN consequentia","en":"Latin consequentia meant 'a following, consequence', formed on the present participle stem of consequi.","cn":"拉丁语 consequentia 意为“跟随、随之而来的结果”，由 consequi 的现在分词词干构成。"},{"era":"LATIN consequi","en":"Consequi joins com- 'together' (here intensive) and sequi 'to follow'. The picture is something moving behind something else and going where it goes.","cn":"consequi 由 com-“一起”（此处为加强义）和 sequi“跟随”组成。画面是某物跟在另一物后面，它走到哪里，后面那个就跟到哪里。"},{"era":"PROTO-INDO-EUROPEAN","en":"Sequi goes back to PIE *sekw- (1) 'to follow', the reconstructed root behind sequence, sequel, sect, and second. Reconstructed roots are inferred rather than attested.","cn":"sequi 可追溯到原始印欧语 *sekw- (1)“跟随”，这一重构词根也是 sequence、sequel、sect、second 的来源。重构词根是推演出来的，没有直接文献证实。"},{"era":"C.1400 – 1590S","en":"Around 1400 the word gained 'that which follows from an act or course'; by the 1590s it also meant 'importance, significance', because what is heavy with consequences matters. The family then grew: consequent, consequently, consequential, inconsequential.","cn":"约 1400 年，这个词获得“由某一行为或进程随之而来的事”一义；到 16 世纪 90 年代又表示“重要性、意义”，因为充满后果的东西自然有分量。随后词族扩展出 consequent、consequently、consequential、inconsequential。"}]},"similar":{"note":{"en":"The first group is the same Latin family with different endings, so each word is a different part of speech rather than a synonym. The second group collects ordinary nouns for what comes after.","cn":"第一组是同一个拉丁词族的不同词尾，每个词属于不同词性，而不是同义词。第二组收集日常表示“后来发生的事”的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"consequent","ipa":"/ˈkɒnsɪkwənt/","tag":"adjective form","definition":"following as a result; in logic, the second part of a conditional. It is the adjective, while consequence is the noun, so 'the consequent delay' is correct but 'a consequent' is not the usual noun.","definitionCN":"作为结果随之而来的；逻辑中条件句的后件。它是形容词，而 consequence 是名词，因此可以说 the consequent delay，但不能用 a consequent 作常用名词。"},{"word":"consequently","ipa":"/ˈkɒnsɪkwəntli/","tag":"adverb","definition":"as a result; therefore. It is the adverbial signpost, doing the job that 'as a consequence' does in three words.","definitionCN":"因此；结果。它是副词性的路标，用一个词完成 as a consequence 三个词的工作。"},{"word":"consequential","ipa":"/ˌkɒnsɪˈkwenʃl/","tag":"-ial adjective","definition":"important or resulting in significant effects; also, in older use, self-important. It stresses the weight of the effects rather than the bare fact of following.","definitionCN":"重大的，或引起重大后果的；较早用法中还指自以为了不起。它强调后果的分量，而不只是“跟着发生”这一事实。"},{"word":"inconsequential","ipa":"/ɪnˌkɒnsɪˈkwenʃl/","tag":"in- negation","definition":"not important; too trivial to produce meaningful effects. The in- prefix removes the weight, not the sequence.","definitionCN":"不重要的；琐碎到不会产生有意义的影响。前缀 in- 去掉的是分量，而不是先后顺序。"}]},{"heading":"NEAR MEANING","entries":[{"word":"result","ipa":"/rɪˈzʌlt/","tag":"neutral outcome","definition":"something that happens because of an action or event. Result is the most neutral and general word; consequence often carries a warning or a moral weight.","definitionCN":"因某个行动或事件而发生的事。result 最中性、最通用；consequence 常带警告或道德分量。"},{"word":"effect","ipa":"/ɪˈfekt/","tag":"produced change","definition":"a change that one thing produces in another. Effect points at the change itself, while consequence points at the later event that follows.","definitionCN":"一事物在另一事物上造成的改变。effect 指向改变本身，consequence 指向随之而来的后续事件。"},{"word":"outcome","ipa":"/ˈaʊtkʌm/","tag":"final result","definition":"the final result of a process, decision, or contest. Outcome looks at where something ends; consequence looks at what follows from what.","definitionCN":"过程、决定或竞赛的最终结果。outcome 看的是事情在哪里结束；consequence 看的是从什么跟出了什么。"},{"word":"repercussion","ipa":"/ˌriːpəˈkʌʃn/","tag":"indirect echo","definition":"an unexpected and usually bad effect that spreads indirectly from an event. It is the ripple image made explicit, and it is stronger and more negative than consequence.","definitionCN":"由某一事件间接扩散开的、通常不好的意外影响。它把波纹意象说得最明白，也比 consequence 更强、更负面。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: com- 'together' plus sequi 'follow', and the living family consequent / consequently / consequential / inconsequential.","cn":"只用真实的构词成分与真实同族词：com-“一起”加 sequi“跟随”，以及常用词族 consequent／consequently／consequential／inconsequential。"},"normal":[{"en":"sequi means 'to follow'. A consequence is literally the thing that follows, so the word is a chase, not a punishment by itself.","cn":"sequi 意为“跟随”。consequence 字面就是“跟在后面的那个东西”，所以这个词本身是一场追逐，而不是惩罚。"},{"en":"Sequence, sequel, second and sect all come from the same 'follow' root. Sequence is the plainest relative: things arranged one after another.","cn":"sequence、sequel、second、sect 都来自同一个“跟随”词根。sequence 是最直白的亲属：一件接一件排好的东西。"},{"en":"Consequently is the adverb signpost: it announces that the next clause follows from the last one.","cn":"consequently 是副词路标：它宣告下一个分句是从上一个分句跟出来的。"},{"en":"Consequential means heavy with effects; inconsequential means the effects weigh nothing. The prefix changes the weight, not the order.","cn":"consequential 意为“后果很重”；inconsequential 意为“后果没有分量”。前缀改变的是重量，不是顺序。"},{"en":"'Of little consequence' is a formal way to say 'not important'. The 1590s sense of importance is still alive in exactly this phrase.","cn":"of little consequence 是“不重要”的正式说法。16 世纪 90 年代那个“重要性”义项，正是在这个短语里活到今天。"}],"abstract":[{"en":"Throw one stone into still water. The stone is the act; the rings that keep widening are the consequences, and they outlast the splash.","cn":"往静水里扔一颗石子。石子是行为；不断扩大的圈是后果，它们比那声水响活得久。"},{"en":"The rings do not stop because the thrower has left. That is why the word can name unintended, long-range and historical effects.","cn":"扔石子的人走了，圈也不会停。正因如此，这个词才能命名意外的、远期的和历史性的影响。"},{"en":"The same image flips into importance: something that will send many rings outward is, right now, a matter of consequence.","cn":"同一个意象还能翻转成“重要性”：一件将来会荡出很多圈的事，此刻就是一件有分量的事。"}]},"examples":[{"en":"The decision to drain the marsh had consequences no one had modelled.","cn":"排干沼泽的决定带来了没有人建模预测过的后果。"},{"en":"He was late three times and, in consequence, lost the contract.","cn":"他迟到了三次，结果失去了那份合同。"},{"en":"In formal logic, the consequence follows from the premises whether or not anyone believes it.","cn":"在形式逻辑中，结论是否被人相信，都不影响它从前提出发成立。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“康西宽斯”——康西宽斯扔下一块石头，水面宽宽地荡开一圈又一圈 → consequence 结果、后果","word":"consequence"},"root":"源自拉丁语 consequi“跟在后面”，由 com-“一起”+ sequi“跟随”构成，核心是“一件事跟着另一件事来”。","sensesIntro":{"en":"Eight senses of consequence, all grown from one movement: something follows behind something else. The follower can be an event, a penalty, a logical proposition, an importance, or a whole historical aftermath.","cn":"consequence 的八个义项都从同一个运动长出来：某物跟在另一物后面。跟着来的可以是事件、代价、逻辑命题、重要性，也可以是一整段历史余波。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stone drops, and rings of water follow outward behind it.","cn":"核心意象：一颗石子落下，水纹在它身后一圈圈向外跟去。"},"chain":["SOMETHING HAPPENS","SOMETHING FOLLOWS","THE FOLLOWER IS CAUSED","THE FOLLOWER CAN HURT","THE FOLLOWER CARRIES WEIGHT","THE FOLLOWER OUTLASTS THE ACT"],"branches":[{"senses":"S1 · S2","en":"RESULT: a later event follows from an act, and when it hurts it becomes a debt the actor must pay.","cn":"结果：后来的事件从行为跟出；当它带来伤害时，就变成行为者必须偿付的债。"},{"senses":"S3 · S8","en":"WEIGHT: something heavy with effects is important, and a person whose acts move many lives has standing.","cn":"分量：后果很重的东西就是重要的；一个人的行为能带动许多人的生活，他就有身份地位。"},{"senses":"S4","en":"REASONING: a proposition follows from premises, which is the word's oldest recorded sense.","cn":"推理：一个命题从前提出发，这是这个词最早被记录的义项。"},{"senses":"S5 · S7","en":"OUTWARD AND ONWARD: effects that no one planned keep spreading, and can outlast the original event by decades.","cn":"向外与向前：没人计划过的影响持续扩散，并且能比原初事件多活几十年。"},{"senses":"S6","en":"SIGNPOST: the noun becomes a linking phrase that points to the next clause as the follower.","cn":"路标：名词变成连接短语，把下一个分句指认为那个跟着来的东西。"}]},"affixes":{"intro":{"en":"Consequence is a borrowed noun to which English adds only ordinary suffixes. The Latin stem consequ- carries the 'follow' idea, and -ence marks a state or result.","cn":"consequence 是借入的名词，英语只在它上面加普通后缀。拉丁词干 consequ- 携带“跟随”的观念，-ence 标记状态或结果。"},"latinIntro":{"en":"The Latin family is built on sequi 'to follow': consequi 'follow after', consequentia 'a following', and consequens 'following'. English took the noun and then built consequent, consequence's adjective, and the whole -ial branch.","cn":"这一拉丁词族建立在 sequi“跟随”上：consequi“跟在后面”、consequentia“跟随”、consequens“跟随的”。英语借入名词，再据其造出形容词 consequent 以及整条 -ial 分支。"},"items":[{"word":"consequences","structure":"consequence + -s (plural)","meaning":"more than one result, often a set of penalties","meaningCN":"多个结果；常指一连串代价（-s 构成复数）","example":"The delays had knock-on consequences for every later shipment.","exampleCN":"这些延误对之后每一批货运都产生了连锁后果。"},{"word":"consequent","structure":"consequ(ent) + -ent (adjective)","meaning":"following as a result","meaningCN":"随之发生的；作为结果的（-ent 构成形容词）","example":"Heavy rain and the consequent closure of the road stranded us.","exampleCN":"大雨以及随之而来的封路把我们困住了。"},{"word":"consequently","structure":"consequent + -ly (adverb)","meaning":"as a result; therefore","meaningCN":"因此；所以（-ly 构成副词）","example":"The grant was cut, and consequently the lab lost two staff.","exampleCN":"拨款被削减，实验室因此少了两名员工。"},{"word":"consequential","structure":"consequent + -ial (adjective)","meaning":"important; producing significant effects","meaningCN":"重大的；引起重大后果的（-ial 构成形容词）","example":"The ruling was consequential for every small landlord in the city.","exampleCN":"这项裁决对城里每个小房东都影响重大。"},{"word":"consequentially","structure":"consequential + -ly (adverb)","meaning":"in a way that follows as a result; with important effects","meaningCN":"随之；因而；在后果上（-ly 构成副词）","example":"The two clauses are consequentially linked, not merely adjacent.","exampleCN":"这两个分句在后果上相连，而不仅仅是相邻。"},{"word":"inconsequential","structure":"in- (not) + consequential","meaning":"not important; producing no meaningful effect","meaningCN":"微不足道的；不重要的（in- 表示否定）","example":"The typo was inconsequential; the figures were correct.","exampleCN":"那个错字无关紧要，数字是对的。"},{"word":"inconsequentially","structure":"in- + consequential + -ly","meaning":"in a way that has no important effect","meaningCN":"无关紧要地；不产生重要影响地","example":"The meeting ended inconsequentially, with no decision recorded.","exampleCN":"会议毫无结果地结束，没有记录任何决定。"},{"word":"sequence","structure":"sequi + -ence (state or result noun)","meaning":"a set of things arranged one after another","meaningCN":"序列；一连串按顺序排列的事物（同一词根 + -ence）","example":"The sequence of events is clear from the timestamps.","exampleCN":"从时间戳可以看清事件的先后顺序。"},{"word":"subsequent","structure":"sub- (after) + sequi + -ent","meaning":"coming after something else in time","meaningCN":"随后的；后来的（sub- 表示“在后”）","example":"Subsequent reports confirmed the first finding.","exampleCN":"随后的报告证实了最初的发现。"}],"latinEntries":[{"word":"sequi","structure":"root verb","meaning":"to follow","meaningCN":"跟随"},{"word":"consequi","structure":"com- (together, completely) + sequi (follow)","meaning":"to follow after, come after, result","meaningCN":"跟在后面；随之而来；导致"},{"word":"consequentia","structure":"consequi + -entia (state noun)","meaning":"a following, consequence, inference","meaningCN":"跟随；后果；推论"}]}},{"word":"considerable","ipa_uk":"/kənˈsɪdərəbl/","ipa_us":"/kənˈsɪdərəbl/","definition_zh":"相当大的；可观的；重要的；值得认真考虑的","definition_en":"large in amount, size, or degree; important enough to deserve serious attention","core_image":"天平上一块必须认真掂量的砝码，重得让指针明显偏移","scene":"The bridge repair will cost a considerable sum, far more than the council had budgeted.","sceneCN":"这里 considerable 是「（金额）相当大的、可观的」（第 6 个义项：在钱数或价值上很大）；句意：这座桥的维修将花掉一笔相当可观的款项，远远超出市议会的预算。场景要点：一份预算表、一个多出来的零、一笔必须认真掂量的钱。","pos":[{"tag":"adj.","zh":"相当大的；可观的；大量的"},{"tag":"adj.","zh":"重要的；值得重视的"}],"collocations":[{"phrase":"a considerable amount","zh":"相当大的数量"},{"phrase":"considerable influence","zh":"相当大的影响力"},{"phrase":"considerable progress","zh":"长足的进展"},{"phrase":"considerable attention","zh":"相当多的关注"},{"phrase":"a considerable period","zh":"相当长的一段时间"},{"phrase":"considerable expense","zh":"可观的开支"}],"forms":[{"label":"比较级（多音节形容词用 more 构成）","form":"more considerable"}],"derivatives":[{"word":"considerably","pos":"adv.","zh":"相当大地；在很大程度上"},{"word":"consider","pos":"v.","zh":"考虑；认为；顾及"},{"word":"consideration","pos":"n.","zh":"考虑；考量；体贴；报酬"},{"word":"considerate","pos":"adj.","zh":"体贴的；为他人着想的"},{"word":"inconsiderable","pos":"adj.","zh":"微不足道的；不值一提的"}],"senses":[{"no":"01","title":"Large in amount or degree","titleCN":"数量或程度上很大","definition":"great in amount, quantity, or degree, especially of something abstract","definitionCN":"在数量或程度上很大，尤用于抽象事物","example":"The study found a considerable difference in reading speed between the two groups.","exampleCN":"研究发现两组之间的阅读速度存在相当大的差异。","why":"Considerable began as 'worth considering'. Something heavy enough to shift a measurement is exactly what deserves a second look, so 'worth weighing' slides into 'weighing a lot'.","whyCN":"considerable 起先是“值得考虑的”。重到能让测量指针偏移的东西，正值得再看一眼，于是“值得掂量”滑向了“分量很大”。"},{"no":"02","title":"Large in size or extent","titleCN":"体积或范围上很大","definition":"great in physical size, area, or extent","definitionCN":"在物理体积、面积或范围上很大","example":"A considerable part of the old town was rebuilt after the earthquake.","exampleCN":"老城相当大的一部分在地震之后重建了。","why":"The same scale is applied to space instead of quantity: an area large enough to matter is one you cannot walk past without noticing.","whyCN":"同一把尺子从数量挪到空间上：大到有分量的面积，是你走过去不可能不注意到的面积。"},{"no":"03","title":"Long in duration","titleCN":"时间上相当长","definition":"lasting a long time, especially longer than expected","definitionCN":"持续很长时间，尤其指比预期更久","example":"The manuscript lay unread for a considerable period before anyone catalogued it.","exampleCN":"那份手稿在相当长的一段时间里无人阅读，直到有人给它编目。","why":"Time is measured on the same scale: a span long enough to change something is a considerable span, whether the unit is money, area, or years.","whyCN":"时间也用同一把尺子量：长到足以改变某些东西的一段时间，就是 considerable 的一段时间——无论单位是钱、面积还是年。"},{"no":"04","title":"Important enough to matter","titleCN":"重要到有分量","definition":"important, serious, or worth serious attention","definitionCN":"重要的、严重的，或值得认真重视的","example":"The court treated the missing file as a considerable problem, not a clerical slip.","exampleCN":"法院把那份缺失的档案视为一个相当重要的问题，而不是文书小错。","why":"This is the oldest layer of the word made visible: if something is considerable, it is literally worth considering, and so no one may wave it aside.","whyCN":"这是这个词最古老的一层含义显形：如果某件事是 considerable，它字面上就“值得考虑”，因此谁也不能把它挥手打发。"},{"no":"05","title":"Notable in ability or achievement","titleCN":"才华或成就上不容忽视","definition":"of a person or work, having noticeable ability, merit, or reputation","definitionCN":"指人或作品具有引人注目的能力、价值或声望","example":"She built a considerable reputation as a translator of poetry.","exampleCN":"她作为诗歌译者建立了相当大的声誉。","why":"A reputation is an amount of standing, and standing is weighed like any other quantity. A considerable reputation is one heavy enough that people mention it without being asked.","whyCN":"声誉是一份“分量”，而分量和其他数量一样可以被称量。considerable 的声誉，就是重到别人不用你问也会提起的程度。"},{"no":"06","title":"Large in money or value","titleCN":"金额或价值上可观","definition":"of a sum of money or a value, large enough to affect decisions","definitionCN":"指金额或价值大到足以影响决策","example":"A considerable share of the budget goes to maintenance, not to new buildings.","exampleCN":"预算中相当可观的一部分用于维护，而不是新建大楼。","why":"Money is the most countable form of weight: a sum either tips the balance of a decision or it does not, and the word marks the first case.","whyCN":"钱是最可称量的一种重量：一笔钱要么压动决策的天平，要么不能；这个词标记的是前一种情况。"},{"no":"07","title":"Formal understatement for 'quite a lot'","titleCN":"正式文体中的委婉含蓄","definition":"used in formal or careful writing as a restrained way of saying 'a lot', often to avoid overstatement","definitionCN":"在正式或谨慎的写作中用来克制地表示“很多”，常为避免夸张","example":"The proposal met with considerable resistance from the residents' association.","exampleCN":"该提案遭到了居民协会相当大的抵制。","why":"A word that once meant 'worth weighing' makes a natural hedge: it reports real weight without committing the speaker to a dramatic adjective.","whyCN":"一个原本意为“值得掂量”的词，天然适合做缓冲：它报告了真实的分量，又不让说话人背上夸张的形容。"},{"no":"08","title":"Older literal sense: fit to be considered","titleCN":"较早的字面义：值得被考虑","definition":"in older usage, capable of or worthy of being considered; now largely replaced by the quantity senses","definitionCN":"在较早用法中，指可以被考虑或值得被考虑；现多被数量义取代","example":"The proposal was considerable by the whole board before any vote was taken.","exampleCN":"在投票之前，整个董事会就已经把这份提案纳入考虑。","why":"The suffix -able first meant 'able to be', so considerable once meant 'able to be considered'. The modern 'large' sense grew out of that judgement, not the other way round.","whyCN":"后缀 -able 最初表示“能够被”，因此 considerable 曾经就是“能够被考虑的”。现代“很大”的义项是从这个判断长出来的，而不是反过来。"}],"etymology":{"intro":{"en":"Considerable is an English construction: consider plus -able. The verb consider is Latin, but the deeper origin of considerare is disputed, and the date of the 'large' sense is not precisely known.","cn":"considerable 是英语自己构成的词：consider 加 -able。动词 consider 源自拉丁语，但 considerare 更深一层的来源存在争议，“很大”这一义项出现的年代也没有精确记载。"},"items":[{"era":"LATE 14C.","en":"Consider is first recorded with the sense 'fix the mind upon for careful examination', borrowed through Old French considerer.","cn":"consider 最早记录时意为“把心思定在某事上以便仔细察看”，经由古法语 considerer 借入。"},{"era":"LATIN considerare","en":"Latin considerare meant 'to look at closely, observe'. It is traditionally explained as com- 'with, thoroughly' plus sidus 'heavenly body, star', literally 'to observe the stars'.","cn":"拉丁语 considerare 意为“仔细看、观察”。传统上把它解释为 com-“一起、彻底”加 sidus“天体、星辰”，字面即“观察星象”。"},{"era":"UNCERTAIN ORIGIN","en":"That 'observe the stars' reading is generally assumed, not proved. De Vaan's etymological dictionary does not endorse any of the proposed alternatives, and Tucker suggested a possible link with side 'extend'. The deeper origin of consider must therefore be marked as uncertain.","cn":"“观察星象”这一读法只是“一般认为”，并未得到证实。De Vaan 的词源词典没有认可任何一种替代解释，Tucker 还提出可能与 side“延伸”有关。因此 consider 更深一层的来源必须标注为“不确定”。"},{"era":"CONSIDER + -ABLE","en":"English formed considerable from consider and the suffix -able, whose first sense is 'able to be'. The earliest meaning was therefore 'able to be considered, worth consideration'.","cn":"英语用 consider 加后缀 -able 构成 considerable，而 -able 的第一义是“能够被……的”。因此最早的含义是“能够被考虑、值得考虑的”。"},{"era":"SEMANTIC SHIFT","en":"The move from 'worth considering' to 'important' and then to 'large in amount' is generally assumed, but no exact dating is established. The change runs from judgement to weight to sheer quantity.","cn":"从“值得考虑”到“重要”，再到“数量很大”的演变是“一般认为”的路径，但并没有确立精确年代。这条路径从判断走向分量，再走向纯粹的数量。"},{"era":"MODERN ENGLISH","en":"Modern English keeps the quantity senses as the main ones and builds considerably, consideration and considerate beside it. Considerate has a different suffix and means 'thoughtful of others', not 'large'.","cn":"现代英语以数量义为主，并在旁边发展出 considerably、consideration、considerate。considerate 用的是另一个后缀，意为“为他人着想的、体贴的”，而不是“很大”。"}]},"similar":{"note":{"en":"The first group is built on the same verb consider with different suffixes; the second group collects adjectives that also measure size or importance. The first group is where the real traps are.","cn":"第一组由同一个动词 consider 加不同后缀构成；第二组收集同样表示“大小或重要性”的形容词。真正的陷阱在第一组。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"considerate","ipa":"/kənˈsɪdərət/","tag":"different suffix: -ate","definition":"thoughtful of other people's feelings and needs. It differs from considerable only in its ending, but -ate points to a habit of mind, not to size: considerate does NOT mean 'large'.","definitionCN":"体贴的，能顾及他人感受与需要的。它与 considerable 只差词尾，但 -ate 指向的是一种心性，而不是大小：considerate 绝不表示“很大”。"},{"word":"consideration","ipa":"/kənˌsɪdəˈreɪʃn/","tag":"noun form","definition":"the act of thinking carefully about something; also thoughtfulness, or a payment exchanged for a promise. It is the noun of consider, and it keeps both the mental and the commercial branches.","definitionCN":"仔细考虑的行为；也指体贴，或为承诺支付的报酬。它是 consider 的名词，同时保留了心智与商业两条分支。"},{"word":"considerably","ipa":"/kənˈsɪdərəbli/","tag":"adverb form","definition":"by a large amount; to a great degree. It modifies verbs and comparatives ('considerably better'), while considerable modifies nouns.","definitionCN":"相当大地；在很大程度上。它修饰动词和比较级（considerably better），而 considerable 修饰名词。"},{"word":"consider","ipa":"/kənˈsɪdə/","tag":"base verb","definition":"to think about something carefully, or to regard it in a particular way. It is the base from which considerable is built, and its history is the disputed part of the family.","definitionCN":"仔细思考某事，或以某种方式看待它。它是 considerable 赖以构成的动词，它的历史正是这个词族中有争议的部分。"}]},{"heading":"NEAR MEANING","entries":[{"word":"substantial","ipa":"/səbˈstænʃl/","tag":"solid weight","definition":"large in amount or importance, and also solid, real, not merely nominal. Substantial often suggests something you can build on; considerable only measures size.","definitionCN":"在数量或重要性上很大，同时含有“实在、非名义上的”意味。substantial 常暗示可以依靠；considerable 只衡量大小。"},{"word":"significant","ipa":"/sɪɡˈnɪfɪkənt/","tag":"meaningful, not just big","definition":"large or important enough to be noticed and to matter, especially in statistics. Significant adds the idea of meaning or effect; considerable may be large without changing anything.","definitionCN":"大到或重要到值得注意、起作用的，尤用于统计。significant 还带“有意义、有影响”的意思；considerable 可以只是量大而不改变什么。"},{"word":"sizeable","ipa":"/ˈsaɪzəbl/","tag":"physical scale","definition":"fairly large in size or amount. It is more informal and more physical than considerable, and it does not carry the 'important' branch.","definitionCN":"在体积或数量上相当大。它比 considerable 更口语、更偏物理，也没有“重要”这条分支。"},{"word":"appreciable","ipa":"/əˈpriːʃəbl/","tag":"enough to be measured","definition":"large enough to be noticed or measured. Appreciable is technical and rarely means 'important'; it asks whether an effect clears the threshold of detection.","definitionCN":"大到可以被注意或测量。appreciable 偏技术，很少表示“重要”；它问的是某个效果是否越过了可察觉的门槛。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: consider plus -able 'able to be', and the living family considerably, consideration, considerate. The deeper origin of consider is uncertain and is not used here as a fact.","cn":"只用真实的构词成分与真实同族词：consider 加 -able“能够被”，以及常用词族 considerably、consideration、considerate。consider 更深的来源不确定，这里不当作事实使用。"},"normal":[{"en":"-able means 'able to be'. Considerable first meant 'able to be considered', and only later came to mean large: the size is the weight of the consideration.","cn":"-able 表示“能够被”。considerable 最早是“能够被考虑的”，后来才表示“很大”：大小就是那份考虑的分量。"},{"en":"Considerable measures a noun; considerably measures a verb or a comparative. 'A considerable cost' is right; 'a considerably cost' is not.","cn":"considerable 修饰名词；considerably 修饰动词或比较级。可以说 a considerable cost，不能说 a considerably cost。"},{"en":"Considerate and considerable differ by one suffix but point in opposite directions: -ate is thoughtfulness toward people, -able is a measurable quantity.","cn":"considerate 与 considerable 只差一个后缀，方向却相反：-ate 是对人的体贴，-able 是可测量的数量。"},{"en":"The 'observe the stars' story about consider is generally assumed, not proven. De Vaan's dictionary accepts none of the proposed deeper origins, so treat it as a picture, not a fact.","cn":"关于 consider 的“观察星象”故事只是“一般认为”，并未被证实。De Vaan 的词源词典不接受任何一种更深的来源，所以把它当画面，不要当事实。"},{"en":"Inconsiderable is the negative: not 'not thoughtful', but 'too small to matter'. The in- removes the weight, not the politeness.","cn":"inconsiderable 是其否定形式：不是“不体贴”，而是“小到不值一提”。in- 去掉的是分量，不是礼貌。"}],"abstract":[{"en":"Picture a scale with a weight heavy enough to move the needle. The act of looking at it twice and the fact that it is heavy are the same moment.","cn":"想象一杆天平，砝码重到能让指针明显移动。你多看它一眼的动作，和它本身很重这个事实，是同一个瞬间。"},{"en":"The scale works for money, area, time, influence and reputation. Anything that can tip a decision can be called considerable.","cn":"这杆天平可以称钱、面积、时间、影响力与声誉。任何能压动一个决定的东西，都可以叫 considerable。"},{"en":"Notice how a word about careful looking turned into a word about size. The judgement did not disappear; it became the weight behind the number.","cn":"注意一个关于“仔细看”的词如何变成了关于“大小”的词。那份判断并没有消失，它变成了数字背后的重量。"}]},"examples":[{"en":"The delay caused considerable inconvenience to commuters on the northern line.","cn":"这次延误给北线的通勤者造成了相当大的不便。"},{"en":"She spent a considerable part of her career documenting minority languages.","cn":"她把职业生涯中相当大的一部分用于记录少数民族语言。"},{"en":"The committee gave the proposal considerable attention before rejecting it.","cn":"委员会在否决该提案之前，对它给予了相当多的关注。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“看稀得萝卜”——地里看着稀稀拉拉几根萝卜，可每一根都大得相当可观 → considerable 相当大的、可观的","word":"considerable"},"root":"由 consider + -able 构成；consider 源自拉丁语 considerare“仔细端详、观察”，一般认为字面是“观察星象”（com- + sidus“星”），但更深来源不确定。","sensesIntro":{"en":"Eight senses of considerable, all built on one gesture: something is heavy enough to make you stop and weigh it. That weight can be counted, measured, timed, trusted, or simply respected.","cn":"considerable 的八个义项都建立在同一个动作上：某样东西重到让你停下来掂一掂。这份重量可以被计数、被丈量、被计时、被信任，也可以只是被尊重。"},"semanticMap":{"core":{"en":"CORE IMAGE: a weight heavy enough to move the needle and force a second look.","cn":"核心意象：一块重到能让指针偏移、逼人多看一眼的砝码。"},"chain":["WORTH CONSIDERING","WORTH NOTICING","IMPORTANT","LARGE IN AMOUNT","LARGE IN SCALE","QUITE A LOT"],"branches":[{"senses":"S1 · S6","en":"QUANTITY: an amount, a degree, or a sum of money large enough to change a decision.","cn":"数量：大到足以改变决定的数量、程度或一笔钱。"},{"senses":"S2 · S3","en":"MEASURE: the same scale applied to space and to time, so an area or a period can be called considerable.","cn":"度量：同一把尺子用到空间与时间上，因此一片面积或一段时间也可以叫 considerable。"},{"senses":"S4 · S5","en":"WEIGHT: importance, seriousness, and the standing a person or a work has earned.","cn":"分量：重要性、严重性，以及一个人或一部作品赢得的声望。"},{"senses":"S7","en":"TONE: a restrained formal way of saying 'a lot', which reports weight without overstating it.","cn":"语气：克制而正式地说“很多”，报告了分量，又不夸张。"},{"senses":"S8","en":"ORIGIN: the oldest literal sense, 'able to be considered', still visible behind all the others.","cn":"源头：最古老的字面义“能够被考虑”，在其后所有义项背后仍然可见。"}]},"affixes":{"intro":{"en":"Considerable is an English suffix construction, not a Latin borrowing: consider plus -able. English then builds adverbs and nouns from the same stem, and pairs it with in- for the negative.","cn":"considerable 是英语用后缀构成的词，而不是拉丁语借词：consider 加 -able。英语随后在同一词干上造出副词与名词，并用 in- 构成否定。"},"latinIntro":{"en":"The Latin base is considerare 'to look at closely', traditionally analysed as com- plus sidus 'star'. That analysis is generally assumed rather than proved, and alternative origins have been proposed without acceptance.","cn":"拉丁词基是 considerare“仔细看”，传统上分析为 com- 加 sidus“星辰”。这一分析只是“一般认为”，并非已证；也有人提出替代来源，但未获认可。"},"items":[{"word":"considerably","structure":"considerable + -ly (adverb)","meaning":"by a large amount; to a great degree","meaningCN":"相当大地；在很大程度上（-ly 构成副词）","example":"The second edition is considerably longer than the first.","exampleCN":"第二版比第一版长得多。"},{"word":"consider","structure":"con- (thoroughly) + sidus (star), traditionally","meaning":"to think about carefully; to regard as","meaningCN":"仔细考虑；认为（传统分析为 con- + sidus“星”，来源存疑）","example":"We must consider how the change will affect small shops.","exampleCN":"我们必须考虑这一变化会如何影响小店铺。"},{"word":"consideration","structure":"consider + -ation (action or result noun)","meaning":"careful thought; also thoughtfulness, or payment for a promise","meaningCN":"考虑；体贴；报酬（-ation 构成行为或结果名词）","example":"After long consideration, the board rejected the merger.","exampleCN":"经过长时间考虑，董事会否决了这次合并。"},{"word":"considerate","structure":"consider + -ate (adjective of manner)","meaning":"thoughtful of other people's feelings","meaningCN":"体贴的；为他人着想的（-ate 构成形容词，注意与 considerable 不同）","example":"It was considerate of you to call before arriving.","exampleCN":"你出发前先打电话，很体贴。"},{"word":"considerately","structure":"considerate + -ly (adverb)","meaning":"in a thoughtful, caring way","meaningCN":"体贴地；周到地（-ly 构成副词）","example":"He considerately lowered his voice in the hospital corridor.","exampleCN":"他在医院走廊里体贴地压低了声音。"},{"word":"considerateness","structure":"considerate + -ness (quality noun)","meaning":"the quality of being thoughtful toward others","meaningCN":"体贴；周到（-ness 构成性质名词）","example":"Her considerateness made the new colleague feel welcome.","exampleCN":"她的体贴让新同事感到受欢迎。"},{"word":"inconsiderable","structure":"in- (not) + considerable","meaning":"too small or unimportant to matter","meaningCN":"微不足道的；不值一提的（in- 表示否定）","example":"The cost was inconsiderable compared with the benefit.","exampleCN":"与收益相比，这点成本微不足道。"},{"word":"considered","structure":"consider + -ed (past participle, adjective)","meaning":"carefully thought out; also 'regarded as'","meaningCN":"经过深思熟虑的；被认为的（-ed 构成过去分词与形容词）","example":"This is her considered opinion after ten years of research.","exampleCN":"这是她研究十年之后深思熟虑的看法。"}],"latinEntries":[{"word":"considerare","structure":"com- (thoroughly) + sidus (star), traditionally; origin uncertain","meaning":"to look at closely, observe, examine","meaningCN":"仔细看；观察；审视（传统分析为 con- + sidus，来源不确定）"},{"word":"sidus","structure":"noun","meaning":"heavenly body, star, constellation","meaningCN":"天体；星辰；星座"},{"word":"consideratio","structure":"considerare + -atio (action noun)","meaning":"careful examination, contemplation","meaningCN":"仔细审视；沉思"}]}}]);
